/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160223-9","meetingId":"h28-cm02","date":"2016年2月23日","dateIso":"2016-02-23","committee":"文教委員会","time":"午前１０時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件抜き出しています。","topics":[{"id":"topic-01","title":"平成２７年度品川区教育委員会の事務事業の点検および評価報告書","agenda":"平成２７年度品川区教育委員会の事務事業の点検および評価報告書","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この今日の報告の中に教育委員会の仕事がいっぱいぎっしり詰まっているのですけれども、ここまでまとめ上げるのにかなり大変なご苦労があったのかなと思うのですが、この点検・評価報告書をつくる手順というか、ちょっと教えていただきたいです。どこまでの意見が吸い上げられてここに加わっていっているのかというのを知りたいので、その点を教えてください。","respondent":"品川庶務課長","answer":"この評価に至るまでですが、まず点検・評価表というものを作成するにあたりまして、教育委員会のほうで大体年間３回から４回にわたって、この教育委員会の事務事業評価についてご意見をいただいています。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"特に意見をいろいろいただいてというところで、どういう機会にどのような、三、四回、教育委員会の中でと言われていますけれども、意見をいただいているというところにおいては、どのような場所でどのような意見を、どのようなというか、どういった方たちの意見を吸い上げているのか教えてください。","respondent":"品川庶務課長","answer":"意見のほうは、そこのページでいいますと、４ページから５ページですね。この部分につきましては、教育委員会としての意見というふうになっております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"その中の具体的なところもお伺いをしたいと思いますけれども、４ページと５ページのところで、率直な疑問で質問をします。学校評価のところなのですが、4)のところなのですけれども、この評価委員の固定化とか、形骸化とか、「新たな視点の評価がしにくい課題がある」と書かれているのですが、具体的にこの中身、どんな部分においてこういう課題があるのかなということが１点です。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"私からは１点目と２点目のご質問にお答えしたいと思います。ただ子どもたちにおいては、フリースクールに通っている子も当然いますし、今後国のほうもこの検討を今進めているところですので、区としてはどのような形で行っていくか。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"それぞれありがとうあります。１点だけもう１回聞きたいのが、3)の学力定着度調査のところで、ほとんど全ての学校でこの民間のものを使っているということで、見直しをしていくと。その見直しの方向が、みんなやっているから支援をしていくという意味なのかどうか、ちょっとそこと、これというのは費用はどのくらいかかっているのか、ちょっと具体的に教えてほしいのが１点です。今の質問と絡んでくるので。","respondent":"渋谷指導課長","answer":"その見直しの方向というのは、当初、品川区だけがこの学力定着度調査を独自にスタートして、国、都も始まってきたというようなこともありますので、冒頭申し上げた当初の目的である学校の指導方法の改善等々にはそういったものも活用できないかということと。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"はい、ありがとうあります。この教育フォーラムのところで。ごめんなさい、もう一つが８２番の教育総合支援センターの巡回相談員の派遣のところのＡ（拡充）の評価で、スクールカウンセラーのところの重要性が増しているということで、人員的な問題がちょっと書かれているのですけれども、増員の方向でぜひお願いしたいのですが、そういう方向なのかどうかをお伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"２点目、巡回相談員につきましては、人数というよりも、今回、今、子どもたちに関するものとしては、小中一貫教育というベースにおいて、小学校、それから小学校からあがっていく中学校を１つのグループとして巡回が回っているというやり方、その中で若干。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"私もちょっとわからないところを伺いたいだけなのですが、６６番のスクールプロモーションが、そうするとフォーラムに向けてプレゼンテーションとかＩＣＴの活用を広げたということなのでしょうか。オリンピック・パラリンピック教育推進事業の１０６番です。１１種目のスポーツを子どもたちが縄跳びだったり、ボール蹴りだったり、いろいろやるという。お願いします。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"ただ、全校一律に代表生徒を、もしくは代表児童の発表の場を設けるという形から、もっと一人ひとりに表現力、発表能力を身につけていく方法と考えたときに、一律こういう形をとるよりも、ふだんの授業の中で。基本的には子どもたち同士でカウントをすることも可能としておりますが、やはり低学年はさすがにカウントすることが難しいということがありますので、できるだけ先生方も一緒に休み時間とか校庭に出て数を数えてもらったり。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"それと１４ページ、３４番の学校事務のＩＴ化推進のところなのですが、学校事務にかかわる業務のシステム・ネットワーク化により、事務の統一化、迅速化、効率化を図るとありますが、私も随分前に委員会で質問したことがあると思うのですけれども、この校務システムとか、そういうものはできていますよというふう随分前に答弁でいただいた記憶があるのですが、それとまた別なもの、新しいものなのか。","respondent":"品川庶務課長、野呂瀬学務課長、渋谷指導課長","answer":"教職員のストレスチェックのほうですが、こちらは年１回検査をしまして、大体１００％の方が、九十九・何％かですけれども。私からは３４番の学校事務のＩＴ化についてご説明いたしますけれども、こちらになりますと、システムはもう既に構築されております。私から５５番の固有教員に関するご質問にお答えしたいと思います。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"それぞれありがとうあります。カウンセリングですとか、それを何というのでしょうか、少し解き放つような。何というのでしょうか、もしも本当に重いということであれば、少しいい意味で休んでもらうみたいなところも出てくるかと思うのです。ここら辺はぜひとも教員を守る意味でも、しっかりと取り組んでいただければと思います。それとＩＴ化についてはわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"意見","question":"時間がないので、１点だけ絞ってやらせていただきます。１５ページの４８番の給食運営なのですけれども、「食物アレルギー対応を重視した委託栄養士の配置は適当である」、これは意味がよくわからないので、ご説明お願いしたいのですけれども。","respondent":"野呂瀬学務課長","answer":"その体制を今後も継続して、全校食物アレルギー対応というのが重視しているところなのですけれども、同じ視点に立って継続してやっていく、この方法については今後も継続してやっていくと、そういう意味で適当であるという評価をいただいているところです。","id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この間一般質問とか、特別委員会で何回もその質問をさせていただいているのですけれども、食物アレルギーの学校における対応に関しては、食物アレルギー対応委員会を各個別の学校で設置して、そこには教師、それからあとそのほかいろいろな職務の人、その職務の中には栄養教諭も入っていたと思うのですけれども。","respondent":"野呂瀬学務課長","answer":"ですから、その運用につきましては、今後今のやり方で平準としていって、そのやり方によってアレルギー対応は各校によって、何というのですか、質が落ちるだとか、そういうことはないと考えているところです。","id":"exchange-010"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今年もなかったですけれども。そのときに課長のご説明だと、給食調理の器具等で個別に対応しているので、１つの項目としては載せていないのだというご答弁だったと思うのですけれども、この５０番を見ても一言も書いていないのですが、これは食物アレルギー対応の食器とかを全く買っていないということですか。","respondent":"野呂瀬学務課長","answer":"例えば食器等は、当然破損したときの補充とか、そういうものはやっておりますけれども、それについては予算書上は、食物アレルギーという予算ではなく、給食の消耗品という形で載せざるを得ないということで、何というのですか、給食アレルギー対応という限定した。","id":"exchange-011"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ここの評価というのは、これは予算書ではないわけですから、食物アレルギーはほかの子どもと、要するに食物が誤食しないように特別のトレーをつくったり、容器をつくったり、容器をカラーにしたり、いろいろ手が必要だと思うのです。そうすると、この評価に一言も書いていないということは、それに関してはあまり重視がされていないのかなと思うのですが。","respondent":"野呂瀬学務課長","answer":"ここの事務事業評価というのは、この項目というのは給食調理機器の整備という、そういう事務事業評価の中ですので、例えばそれから食物アレルギーを独立して、その評価ということであれば、それはまた別に評価に入るのですけれども、今現在、給食アレルギーも含めて。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"次のページに対象事業数１２９としたとあるのですが、これは毎年これぐらいの数をしているのか、どういうふうにこの事業、事業数は多くある中で全事業なのか、この１２９事業はどのぐらいの事業数で、どういうふうにこの事業を対象としたのかという理由を教えていただきたいのと、あと学識経験者からの意見という部分で、意見をいただいている、この意見の取扱いについて。","respondent":"品川庶務課長","answer":"１点目、区民への説明責任ですけれども、毎年議会のほう、この文教委員会の場で報告をいたしまして、それを終了した後にホームページのほうで公表しまして、区民の皆様への説明ということでやっているような状況です。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"学識経験者からの意見について、こういった意見を受けて改善をしていくということで、その後、どういうふうに改善していきましたというような、今回あるような事務事業評価みたいなものは、これに対してはどういった形で出るのかなというのを教えていただきたいと思います。","respondent":"品川庶務課長","answer":"こうやって意見をもらいまして、どこで反映しているかということでご説明をするとすれば、やはりまた来年度の教育委員会の事務事業評価の中で、学識経験者からの意見としてこういうふうに対応したというところは特に項目は設けていなくて。","id":"exchange-014"},{"speaker":"大倉委員","kind":"意見","question":"昨年度も任意ということで、意見ということなのでそうなのだろうというところなのですが、今回の事務事業評価については、前回の意見は反映されて、また来年度については今回のこの意見が事務事業に反映されるということでわかりました。説明責任は、今後どういうふうに検討していくのかというのは。","respondent":"品川庶務課長","answer":"長年にわたりホームページに公表をしているという状況で、あとは説明の方法についてはやはり他区も当然同じことをやっていますし、ほかの自治体等も同じことをやっています。そういった自治体の動きなども見て、公表の方法については少し研究をしていきたいと思います。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"事務事業評価の内容なのですが、多岐にわたっていろいろあるのですけれども、Ｃのところだけちょっと見直しということなので伺っていきたいと思うのですが、スクールプロモーションについては先ほどほかの委員からもご質問があってわかったのでいいのですけれども、ほかの部分の１９番の子ども地域活動支援で、児童が利用したくなるような工夫とかということが。","respondent":"品川庶務課長、渋谷指導課長","answer":"１点目のほうですね。子ども地域活動支援のほうですが、昨年のちょうど１２月ごろから徐々に始めておりまして、当初説明が地域に対してなかなかできていなかったというところもございました。私からは互助会の見直しの部分、５７番についてご説明を申し上げます。これは平成２５年当時に検討したときの細かいデータは持っていないのですけれども、平成２５年当時でもうほぼ数区しか、これを実際やっているところがないと。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお尋ねしたいのですけれども、２０番の庶務課のところの学校事務非常勤職員等の雇用のところで、実は公費で来ている方が１人しかいないので、こういう形で補充していただけると非常に何といいますか、事務が円滑に進むと思うのですが、その仕組みが都ではなくて、区のほうでこの方を雇用しているのかというところで、本来だったらそれは都のほうでもという気はしないでもないのですけれども。","respondent":"品川庶務課長、渋谷指導課長、村尾教育総合支援センター長","answer":"こういった動きを見ながら、必要に応じて何か対応する状況があれば考えていきたいと、このように思っております。それから２点目です。今後展開する学校支援本部事業におきまして、こういった既存の事業を整理、統合しながら、効率的。それから１１４番の就学相談の件数ですけれども、昨年度、平成２６年度が１３７件でありましたが、今年度、まだ継続しているので明確な部分はないのですが。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。それぞれすみません、細かいところまでありがとうございました。就学相談については、先ほどお話ありましたけれども、年度内にできる限りやって、指導して適切に対応していただきたいと思います。もちろん今事務の方も教員の方と一緒に学校づくりに励んでいただいているのは認識しているのですけれども、また区の職員となれば、さらにそれが進むのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"伊藤副委員長","kind":"確認","question":"外部評価のことで、少し古い話ですけれども、イギリスの教育改革を視察に行ったときのことを思い出しました。オフステッドという制度の中で、イギリスは全国統一の基準で学校を評価する仕組みがあったと記憶をしています。だから確認したいのは、そういうチェックシートの項目は同じなのでしょうかということを、まずお伺いしたいのですが、お答えをお願いできますか。","respondent":"渋谷指導課長","answer":"同一の評価基準のようなものを設けて、それによるチェックというものを行うということではなくて、同一項目について記述式に、どちらかというと主観的にそれぞれの委員にご判断いただいて、学校がした自己評価について。","id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"質問","question":"だからそれはやり方ですから、それはそれでいいと思いますけれども、あと外部評価の問題との絡みだけれども、評価をして、それを受けとめて、どういうふうに学校側が改善して実績を出したかという、その実績を示すところがほとんどない感じがするのです。","respondent":"渋谷指導課長","answer":"今副委員長ご指摘の、まさにその改善の実績をどういうふうに評価を受けて、それを活かしていくのかということをホームページに発表してということが、そもそものスタンスで始まっているのですが、やはりこの部分も若干形骸化してきているというふうな。","id":"exchange-020"},{"speaker":"伊藤副委員長","kind":"質問","question":"非常によくできていると思います。子どもたちが頑張ってつくって。だからなかなか小学校１年生に対しては難しいと思われるので、新７年生に対しては、やはり全ての中学校で準備をしていただいて、それは勉強会を含めて準備をしていただいて、それで子どもたち、新入学生に対する学校紹介に使っていくべきだと思うのですが、いかがですか。","respondent":"渋谷指導課長","answer":"今の副委員長のご提案については、校長会等で周知をして、ぜひ有効活用を図っていただけるようにお話ししていきたいと思います。","id":"exchange-021"},{"speaker":"伊藤副委員長","kind":"質問","question":"いろいろな学校の取組みの温度差はあるでしょうから、一概に言えないのだけれども、全て公立の学校なのです。義務教育学校も含めて。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"大倉委員","kind":"質問","question":"すみません。ちょっと１点だけ、先ほどの質問で５７番、教職員互助会に対する補助のところで、都と区でかぶっているというところで、これ区の固有教員とかというのはどういうふうになるのかということを教えてください。","respondent":"渋谷指導課長","answer":"区の固有教員については、区の一般職員と同じ互助会で福利厚生について担っております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それで今インフルエンザはかなりはやっているのですが、それに関してちょっとお聞きしたいことが２点あるので、２点に絞って聞きたいと思います。１つは登校許可証の問題なのですが、今の品川区の小学校の登校許可証、登校許可のシステムについて、簡単にご説明をお願いしたいのですけれども。","respondent":"野呂瀬学務課長","answer":"学校についてはインフルエンザで臨時休業になりますと、先ほど申したとおり、出席停止することができるということで、出席が停止になったら今度は登校許可、親のほうからいわゆる解除願いというものを書いていただいて、それを学校に提出して。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"意見","question":"その間に、例えば医療機関のほうでいつまで休んでくださいということを口頭で保護者に話はするのですけれども、保護者のほうでそれをどう扱うかというのが、一切医療機関のほうは関知できないのです。きちんとその間お休みして、しっかりと自宅で安静にしている方がほとんどだと思うのですが、それが全てだという担保が全くないということに関して、教育委員会のほうはどういうお考えなのか。","respondent":"野呂瀬学務課長","answer":"少なくともこのルールに従ってやってくださいということで、各保護者のほうには学校の養護教諭を通じてですけれども、例えば１年生で入ってきて、まだ学校のルールとか、そういうものがわからない方についてはきちんと説明していく必要があるかなと考えています。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"だからその場合、今の状態というのはチェックが全くできないのです。何かの形でチェックするような体制というのを、どのような形でもいいからこれは１回検討する必要があると思うのですが、これはいかがでしょうか。","respondent":"野呂瀬学務課長","answer":"今現在のルールがこういう形で、今そういうご意見があったということを持ち帰りまして、今後検討させていただきたいと思います。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"提案","question":"いろいろな意味で、子どもも含めて好ましくないのではないかと思うので、学校にインフルエンザが蔓延しているのは、それが全てだとは言えないのですが、蔓延をする場合というのは誰か感染した人がいるから蔓延するので、その辺のこともちょっとよく考えたほうがいいのではないかというようなことで、１つ現状と提案をします。学校の先生との。あれは実際どのぐらい機能しているのでしょうか。","respondent":"野呂瀬学務課長","answer":"やはり判断というのは当然その学校によって、校長の判断ですけれども、校長はいわゆる学校医と協議しながら、助言をいただきながら、最終的に校長が判断するということで、最低３日はやらなければいけないというのは、当然校医ですから、それはご承知なのでしょうけれども。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません。インフルエンザにかかった小学校などは、６年１組がなりましたというのを学校の中での周知はどういうふうになっているのですか。ほかの児童とか、保護者の方に、お隣のクラスなんかだったらわかると思うのですが、ほかの学年等への連絡はどういうふうにしているのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"一般的に学級閉鎖または学年閉鎖が起きますと、学校のほうから保護者宛てに臨時の通知文を出すことが多いです。何年何組はこういう状態で学級閉鎖はいつまで行いますということで、各家庭においても十分注意していただきたいというような通知文を出すのが基本かなと考えています。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問","question":"本校ではないけれども、お子さんが外でいろいろ接触することが多いのに、ほかの学校の様子がわからないので、そういうものを知る方法があるといいですということをおっしゃった方がいらっしゃるので、これをつくられているようだったら、何らかの方法が、近隣小学校とかのものがわかるような仕組みもできればいいなと思うのですが、いかがでしょうか。","respondent":"野呂瀬学務課長","answer":"インフルエンザに関する情報につきましては、東京都のほうからインフルエンザ警報が出た部分も含めて各学校に、各教育委員会に通知が参りまして、その通知を受けて各学校のほうも、今はやっていますので各学校でも気をつけてくださいみたいな、各学校に通知して、それは全保護者。","id":"exchange-029"}]},{"id":"topic-02","title":"臨時福祉給付金","agenda":"臨時福祉給付金","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"臨時福祉給付金のほうで一番上の表を見ると、７３.４３％の申請率ですね。昨年も７９.３２％ということで、８０％、９０％にいかないのだなと思ったのですけれども、これは２月２９日が申請期限ですので、これからまたさらに周知されるのか、そしてこの申請されない方、できない状況もあるのかと思うのですが、そういった状況は把握をされているのかお伺いいたします。","respondent":"廣田臨時給付金担当課長","answer":"現在、区内の事業所の皆さん、ケアマネジャー、高齢者福祉課との連携を図りまして、ケアマネジャーが、１１月ごろから開始しているのですが、１カ月、２カ月に１回介護保険を受けている方をケアマネジャーが訪問するということで。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"確認","question":"いろいろ周知や申請されるためにやられているのだなということがわかりました。それで、裏面の４番のほうの平成２８年度の高齢者向けのものですけれども、これは平成２８年度だけのものでしたか。今のところそういう状況ですか、ちょっと確認させてください。","respondent":"廣田臨時給付金担当課長","answer":"この制度につきましては、平成２９年度から実施される予定となっております年金生活者支援給付金の前倒しというもので、臨時的に行われるものなので、今回限りというふうに国から情報をいただいております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"個人消費の下支えに資するということなのですけれども、やはり消費税増税等々もなってくれば、この３万円では到底、それに値するだけの増税になって、負担増になっていくので、これさらに続けてもらえるようにぜひ、品川区のほうからもよびかけていただきたいなというふうに思いますけれども、いかがでしょうか。","respondent":"廣田臨時給付金担当課長","answer":"国からの通知によりますと、平成２９年度から年金生活者支援給付金を実施予定ということで、満額６万円という制度ということで、そういう計画ということですので、そちらが代替になるというふうに聞いてあります。","id":"exchange-032"}]},{"id":"topic-03","title":"区立幼稚園および保育園等の保育料減額基準等の改正","agenda":"区立幼稚園および保育園等の保育料減額基準等の改正","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"２番の改正する規則のところの(3)なのですが、「品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担」とあるのですけれども、この規則に該当するところがどこなのかをちょっと教えてほしいのと、あと３番の(2)の2)のところで改正を行う減額基準のところなのですが、（ア）のところ、廃止をする基準ということで（ａ）と（ｂ）とありますが。","respondent":"竹田保育課長","answer":"それから収入源に関する変更ですが、今までは出産や育児休業、それから自己都合退社等も、全てがこちらの対象としていたところですけれども、今後は疾病等による休職など、やむを得ない事情に限らせていただきたいというような変更を考えております。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"２の(3)のところはわかりました。ということで、減免の対象のところなのですけれども、若干今までここに該当して、今回新しくなったら受けられないような人が出てくる可能性はあるということですかね。特に2)の（ｂ）の医療費のところとか、あと（ア）の（ｃ）の収入減のところで、今まではここに該当していたけれども、該当しなくなるようなケースが出てくるのでしょうか。","respondent":"竹田保育課長","answer":"医療費は、今までは確定申告していただいて、その金額に基づいて保育料のほうを再計算していたというところですが、即効性がないこと、それから今まで受けられていた方におきましても、収入減のところで疾病等による休職ということで定めておりますので。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"件数はそんなにたくさんないのかなとは思いますけれども、例えば収入減が、疾病以外でも収入が減ってしまうような事態はあり得るのですが、そういうときにこの保育料が本当に実態的に払えないような状況が生まれた場合に、何か救済する手だてとか何かあるのでしょうか。","respondent":"竹田保育課長","answer":"ここには記載がないのですが、住民税が免税になった方についても一定の配慮はなされますので、そういった制度もご利用いただいてと考えております。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"個別に丁寧にということなので、どういうケースがあるか、ちょっと今の段階では私にはわかりませんけれども、ぜひいろいろな事情があって困難なケースについては、個別に丁寧に対応をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-04","title":"区立保育園の民営化対象園および八潮地区幼稚園・保育園の大規模改修","agenda":"区立保育園の民営化対象園および八潮地区幼稚園・保育園の大規模改修","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、品川区が今いる、これからもそうですが、品川区の子どもたちに区立の保育園としてどう責任を持っていくのかというところをまずきちんと表明をしていただきたい、書いてほしいなと思いますが、いかがでしょうか。","respondent":"竹田保育課長","answer":"乳幼児教育の基本的な考え方ですが、日頃の乳幼児教育の成果の１つであります「のびのび育つしながわっこ」にも、冒頭の部分で書いてありますけれども、就学前乳幼児が等しく質の高い保育・教育を受け。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でないと、当たり前だとおっしゃるかもしれないのですけれども、民間委託をしていく方向において、やはり区の姿勢がどうなのかというのをきちんと書いてほしいし、「のびのび育つしながわっこ」のところを今説明していただいたのですが、乳幼児教育という、教育だけ協調しないで、保育と教育、幼育両方なので、ぜひそこのところを握って離さないよという立場をまず表明をしていだたきたいなと思うので。","respondent":"竹田保育課長","answer":"それから当面という表現を使っていますのは、今、乳幼児人口の新しい推計が出てきたところですが、まだ流動性があるところですので、乳幼児人口をしっかり見きわめながら、今後の方針については考えていきたいと考えています。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"なぜ５園程度選んだのかというところをお伺いしたのです。なぜ５園選んだのかと。は乳幼児人口の動向、だから私は今の答えを素直に受けると、４３園中５園、３８園は残すのかなという受けとめ方もしてしまうわけですけれども、そうではないですよね。なぜ今の段階で５園で、そしてその後、乳幼児の動向を見てやっていって、でも相当数は区立のままと。この相当数というのはどのくらいなのですか。","respondent":"金子子ども未来部長","answer":"５園も５と決めたわけではありません。ここに書いてありますとおり、５園程度で実地検証をした上で、今後の方針をまた固めていこうというような考え方ですので、あくまでも程度ということであるということでご理解いただきたいと思います。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"というと、相当数というのはこの５園を検証してみて考えていくということなのですか。相当数。そういうことなのですか。そういう大事な５年間であるということですか。","respondent":"金子子ども未来部長","answer":"ただ、数については今の時点では考えてございません。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"数は考えていないということですが、かなりの数、乳幼児教育の発展のために区立が一定力を発揮してきたというところにおいては、かなりの数、大事だと受けとめていいのでしょうか。ですからそういった意味で、今までは頑張ってきたけれども、これからがらがら変わっていくということでは困るわけですけれども、その辺のお気持ちはどうなのでしょうか。","respondent":"竹田保育課長","answer":"決めるにあたっては、乳幼児人口や地域バランス等、さまざまなことを考慮しながら決めていきますが、今まで品川区として培ってきた乳幼児教育の基本的な考え方は変わらず、充実に努めていくという点では変わりはないところです。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的に伺っていきます。３の対象園の検討のところなのですが、今回具体的に三ツ木保育園の名前が挙がりました。アバウトなのです。そういった意味で、建物の状況、今の状況からかんがみたのだと思いますが、併設施設、築年数、あと施設規模等と３つ書いてあるのですけれども、それぞれの基準、どういう基準をもって判断しているのか、ここのところをもうちょっと詳しく中身を教えてください。","respondent":"竹田保育課長","answer":"それから三ツ木保育園は築年数が４２年というところで、老朽化のほうも進んでおりますので、一定程度適切、そういった建替えの需要もある施設だと考えております。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、併設の施設を持たないところ、あと古いところ、あと定員規模と考えると、適切な規模というと、大体１００とか、そんなものなのですけれども。古いところはもっと古いところがありますよね。この３つをすると三ツ木になったのですか。八潮北と八潮西もありますけれども。あまり古くないところがそうやって選ばれたのはなぜかなと思うのですけれども。どうですか。","respondent":"竹田保育課長","answer":"改築等、建替え等の時期を捉えて民営化するというのは、ほかの自治体等でもよく見受けられるケースです。こういった機会を捉えて民営化していくというのが有効な手法だと考えまして、今回、八潮も対象としたところです。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"当面５園程度ということで、今回、八潮のところも含めてですけれども、あと２園はいつぐらいに発表されるのか、それをちょっとお伺いしたいのと、あと前にも１回ご説明をいただいたのですが、もう１回、基本のところの目的のところもお聞きをいたします。民間活力の活用（公民の適正な分担）と書いてあるのですけれども、民間活力の活用というのは一体何なのでしょうか。保育園にいってみたらですよ。","respondent":"竹田保育課長","answer":"残り２園はというご質問ですが、こちら資料のほうにも５園程度というふうに書かせていただいていますので、２園ということで限定したものではございませんが、今後検討を進めてまいりまして、方向性が決まり次第、またご報告させていただきたいと思います。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"官民が一緒になって安定して行っていくことが大事であると。この官民の分担というのは、品川区はどう考えているのですか。民間のできることは民間で、このところどんどん民営化とか、指定管理が進んでいますが、保育のところにどこに線が引かれるのですか。官と民の線がどこに引かれるのですか。相当数という、この微妙なあれなのですが、どこに線を引いて考えていったらいいのですか。","respondent":"金子子ども未来部長","answer":"ですので、ここは公設民営で、民間の力をお願いしながら、区立として運営していこうと、そういうように具体的な事例に当てはめると何が適切かということで、また一つひとつ判断していく必要がありますけれども。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"違いがありますよね。私は決定的に保育の質のところが違うと、きのうも保育士がころころかわるところを言ったのですけれども、そこら辺についても含めて一緒ではないと思っていますが、同じサービス、サービスという言葉は私あまり好きではないのですけれども、提供しているという捉え方なのかどうか、ここは質問です。","respondent":"竹田保育課長","answer":"それぞれメニューを増やすことによって、区民の方の選択肢も広がることですし、また私立の園では公立とは違った工夫をされている園もありますので、メニューを増やすという点ではサービスの向上に当たると考えております。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お母さんたちが一番わかりやすく発信するのは、園庭がない保育園よりも園庭がある保育園がよいに決まっているではないかとおっしゃるのです。だからこれ１つとってみても、私は子どもの成長発達に重大な影響がある、違いがあると思うのです。区立で守ってきて広げてきたというお話をきのうも伺ったのですけれども、保育の質というのを具体的にどう考えているのか、ぜひ聞かせていただきたいと思います。","respondent":"竹田保育課長","answer":"総合的に考えて、子どもの健全な育成に寄与しているかです。昨日も申し上げましたが、区立保育園で培ったノウハウ、あるいは私立保育園の独自のノウハウを融合させることによって地域の保育サービスを充実させていきたいというところの考えには、変わりはないところです。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"意見","question":"すごい保育の質のところはとても大事なので、総合的と言われても、具体的にどういうことが保育の質と捉えているのか。具体的に子どもの健全育成、もちろんそうですよね。否定していません。歴然として違いはあるのです。ここにいらっしゃる皆さんはどうかわかりませんけれども、保育園を選ばれている保護者の皆さんは、本当に施設見学をして、あちこち比較をして、見ているのですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"切り離せませんよ、大事な話です。とめられてしまったので、どこまでいったかわからない。切り離せというのは、園庭の話を話題にするなということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"そうですか。わかりました。そういった意味で、職員がかわっていったりすることが、子どもたちの成長発達にとても影響するのではないかということで質問しましたけれども、そういった面で実際的に質を保っていくために大事な企業のところの水準が、やはり保育水準のところが区立に至っていないところもあると思うのですが、その点はどう考えていらっしゃるでしょうか。","respondent":"竹田保育課長","answer":"保育の質ということから考えますと、例えばですが、国や都から示されたハード面の基準をクリアしているか、あるいは保育に携わる人材やノウハウを持っているか等、保育の質というのは一言では語れない面があろうかと思いますので、そういったところをしっかり管理監督しまして。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"今の最後の、人がかわっても仕方がない。仕方がないという言い方でいいのですか。人がかわっているという実態は把握をされていますよね。かなりの率で企業立のところを中心に、職員が、保育士が次々にかわっているということは認めますよね。でも、それが仕方がないという言葉でいいのでしょうか。ちょっとそこ大問題だと思うのですけれども。","respondent":"竹田保育課長、金子子ども未来部長","answer":"ただ、人が勤めていく中で、一定程度の退職等はあろうかと思います。そういった人がかわっても、保育の方針等は引き継がれていくと思いますので、適切な乳児教育、保育に努めていきたいと考えています。先ほど課長も申し上げましたとおり、また一般質問でもご答弁申し上げたとおりですけれども、そういうふうに過度にわたって保育士が交代する、そういうような事態はもちろんよくないことだと思っていますので。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"過度な離職率、高いところはよくないと。そうならないように配慮していくということなのですけれども、どういうことができるのですか。品川区にとって、そういう過度な。今、本当に介護の分野でも、保育の分野でも、このところの株式会社参入で介護も保育も質の低下が明らかになっていて、本当に福祉というのは人に蓄積されますよね。経験とかあって。その点はどうなのでしょうか。","respondent":"竹田保育課長","answer":"特に人間関係で辞する方も一定程度いると聞いています。ある民間企業ではなかなか上司である園長が直接悩みを聞くのは難しいので、別のスーパーバイザーみたいな方が巡回しているというような園もあると聞いております。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"私はちょっと保育の質のところなので、とても譲れないというか、絶対に保育の質は下げてはならないと思っているので、ちょっとこだわって質問させていただいているのですけれども、保育の質とは一体何だろうというのを常に……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"意見","question":"ここのところずっと民間委託化とか規制緩和が進んでいる中で、子どもの最善の利益、子どもの権利は守られなくてはいけないというのが、私は本来だったらそれがもっともっとよい方向に向いていかなくてはいけないのに、今の規制緩和の中で国が、今回の委託化も大もとには国のお金がおりてこない、自治体が苦労しているというのが大もとにありますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"意見","question":"委員長、お言葉ですけれども、言葉とかは掲げられるのですよ。それが実現をしているのか、進行形でどうなっているかというのは……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"意見","question":"ちょっと子どもの幸福宣言というのを６点読ませていただきます。子どもの立場を知ってほしいということです。１点目、存分に楽しく遊べると幸せです。遊べる場所と時間をください。２点目、温かく抱き締めてくれると幸せです。３点目、空を見て花を見ると幸せです。４点目、おいしいものを食べるときに幸せです。５点目、本を読んでくれるときに幸せです。６点目、大人が待ってくれるときに幸せです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりこれが、応えていくのが、子どもの成長発達に応えていく観点だと思うのですが、民営化によって、この保育の質の低下が行われていくのが、ここに一番あらわれるのではないかなと思うのです。子どもの立場から見て。その点をお答えいただきたいと思います。","respondent":"竹田保育課長","answer":"今６つの視点を挙げていただきましたが、これはいずれも公立・私立関係なく、保育・教育の中で大事にしているものですので、施設にかかわりなく、品川区の保育・教育の中でこういったことも十分加味しながら。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"財政負担の軽減のところなのですけれども、この間５,０００万円のお金がかからない、安くあがるということなのですが、この５,０００万円の中身をどう受けとめていいか、漠然としていてわからないのです。この影響が、私なんかは人件費に響いてくるのではないかなと思いますけれども、この５,０００万円の数字を出してきた根拠というか、この中身をもうちょっと詳しく教えていただきたいです。","respondent":"竹田保育課長","answer":"昨日示させていただいた数字は大ざっぱな数字ですので、また精査して数字についてはお示しさせていただきたいと思います。どういうものがあるのかといえば、もちろん年齢構成等違いますので、人件費等もあろうですし、さまざまなものがそこにはあろうかと思います。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"提案","question":"今回の提案は民営化によって財政負担の低減を行うということなのですが、私は今でも十分、今でもというか、今、品川区の財政は健全財政でいるわけですよね。今でも健全財政を保っているのに、今、この民営化をしないと健全財政は保っていくことができないのかということ。","respondent":"竹田保育課長","answer":"これから多大な行政負担、あるいは建替え等、多大な行政負担が考えられる中で、効率的な運営を考えていくというのは、我々に課された使命であり、責任だと考えておりますので、充実した保育サービスが安定的、継続的に進められるように。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"最後のほうにしますけれども、民営化しないと安定的な、経済的な運営ができていけない、そういうことなのでしょうか。税金を必要なところにしっかりと投入をしていく、このことに私は民営化が反することであると思って、一生懸命反対の声を唱えているわけなのですけれども、その点どう思われますか。","respondent":"竹田保育課長","answer":"減らしていくというようなご趣旨のことをおっしゃられていますが、保育需要が高まって、あるいは新たな施設の整備等、大きく膨らんでいくことに対して対応していくということですから、現行のものを削っていくということではないので、ご理解いただきたいと思います。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"減らしていく、削っていくというつもりはなかったです。そう聞こえたら違うのですけれども、これから乳幼児人口増えますよね。だから今のこの伸び、伸びといっても品川の統計からしたら、先に伸びたけれどもやがて減っていくと言われている中で、今ここで民間活用というか、民営化をしていかないと、品川区の財政はもたない、パンクをしてしまうということなのでしょうか。最後になります。お伺いします。","respondent":"竹田保育課長","answer":"あらゆる可能性に備えまして、先手先手で対応策を考えていくというのは大変重要なことだと思いますので、今後、適切な運営ができるようにさまざまに考えていきたいと考えています。","id":"exchange-061"},{"speaker":"浅野委員","kind":"質問","question":"私のほうから何点かお伺いしたいのですが、八潮地区における大規模改修ということで、三ツ木保育園を対象にして、八潮北・西の保育園の改築ですか、大規模改修ということが出ておりますけれども、その中で三ツ木保育園というのは４２年経過しているのです。それで建替えということで仮園舎を設置して、そして対応していくということだと思います。","respondent":"竹田保育課長、金子子ども未来部長","answer":"それで、民営化の時期ですが、改修・改築をすぐにやるのか、一定程度おくのかというのにつきましては、在園児との関係もありますので、今後検討させていただいて、またわかり次第ご報告させていただきたいと思います。そういう意味で、通常、保育園は大規模改修をするとしても、居ながら工事といいまして、部屋を移りながら工事していくのですけれども、それができないというのが一番大きな原因ですので、１カ所南をあけて。","id":"exchange-062"},{"speaker":"浅野委員","kind":"質問","question":"ありがとうございました。八潮という特殊性というのも伺いました。この間に待機児童の状況が大きく変化してきた。今までの推計の中でおさまればスムーズにいくのかなと思われますので、順調に工事のほうを進めていただいて、子どもたちの、また親御さんの希望をかなえられるような、そのような保育園を目指していただければと思いますし、また民営化についても早く進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問","question":"いただいた資料の４番のところの、八潮地区における幼稚園・保育園大規模改修のところで、八潮南保育園があく、そこを仮園舎として活用すると。そして、ではそれが終わったときは、八潮南保育園の跡地は何になっていくのかはわかるでしょうか。","respondent":"竹田保育課長","answer":"こちらの工事が最終的に終わるのが大分先になりますので、そのときの保育需要にかんがみまして、その用途については決めていきたいと考えております。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうすると、保育需要等々を見た中で、また保育園が必要だということになれば保育園になっていくということなのでしょうか。ですよね。ちょっと確認お願いします。","respondent":"金子子ども未来部長","answer":"これはこれから協議するので、結論はわかりません。その後の南保育園の跡については、これは今後また全ての見通しが立った後に検討していくべきだと考えています。","id":"exchange-065"},{"speaker":"伊藤副委員長","kind":"意見","question":"記憶されている方もいらっしゃると思うのですけれども。要するに品川区はひどいなと。その中の１つに民営化だと思っているので、ぜひお願いしたいのは、そういう何というか、非常に的確な説明とＰＲをしていかないと、品川区のほうが。いろいろな情報に惑わされる可能性は高いと思われるので、品川区のお考えをお聞かせください。民営化に対してですが。","respondent":"竹田保育課長","answer":"副委員長ご指摘のとおり、民営化についてはまだこれからの説明になりますので、今後十分ご理解いただけるように、丁寧な説明を心がけていきたいと考えております。","id":"exchange-066"},{"speaker":"伊藤副委員長","kind":"質問","question":"民営化が全部悪というのがずっと、先ほど来聞いていたんだけれども、例えば民間企業で、旧国鉄がＪＲになりましたよね。国鉄の時代にね。だから、話をまとめていくと、そういう総合的な総力を結集しながらコストを下げつつも、保育の水準、サービスを逆に上げて、最終的な保育の責任は品川区で責任を持って、民営化も１つの方法として進めていくべきだと思うのですが、いかがでしょうか。","respondent":"竹田保育課長","answer":"私立保育園のよさ、あるいは公立保育園の役割等、さまざまあると思います。１人でも多くの区民の方にご理解いただけるように十分ご説明すると同時に、保育の質を下げないように、維持、向上させていくように我々も全力で頑張っていきたいと考えております。","id":"exchange-067"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"まとめますが、要は一番最後のことが重要なのです。どういう運営主体であったとしても、品川区では保育の水準、サービスは下げませんよと。むしろ上げていきますと。だからそういうことはしっかり担保をしていただいた上で、さまざまな手法の１つとして民営化を検討していく、これはぜひ対処していただきたいことを最後にお願いしておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"大倉委員","kind":"質問","question":"１点お伺いします。八潮地区における幼稚園・保育園の大規模改修についての中で、「八潮わかば幼稚園を改修し、近隣の八潮南保育園を合併した幼保一体施設を開設し」とあるのですが、これというのは以前、今あるものとは違う幼保一体施設を開設するという報告というのは、以前ありましたか。","respondent":"竹田保育課長","answer":"今回保育園等の改築を考えていく中で導き出した考え方です。","id":"exchange-069"},{"speaker":"大倉委員","kind":"質問・要望","question":"ということは、今回初めて出てくるということになると思うのですけれども、そうしたらこれもう１個、この幼保一体施設を開設しますということの報告というか、しなければいけないのではないかなと、今ふと思ったのですけれども、こういう新しく八潮がわかば幼稚園の幼保一体施設というのはどういうものなのかというのは、ご報告していただきたいと思うのですが。","respondent":"金子子ども未来部長","answer":"今回、特にこの４番ですね。大規模改修に絡めた八潮の保育園・幼稚園をどうしていくかというのをもう少し詰めさせていただいて、まとめたところでご報告していきたいと考えておりますので、少しお時間をいただければというふうに考えてあります。","id":"exchange-070"},{"speaker":"高橋（し）委員","kind":"質問","question":"訴訟が起きていないというふうに私は伺っているのですけれども、そこのその後、わかる範囲でいいですが、こういうところをこういうふうに進めた結果、もうそういう問題は起きていないのだというふうなことがわかればお願いしたいのですが。","respondent":"竹田保育課長","answer":"それから訴訟の件ですが、私の知る範囲では、急いで民営化をした結果がそういうことになってしまったというふうにも聞いておりますので、適切な事業を踏まえまして、それで民営化にしていきたいと考えております。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話の裁判などというのは非常に拙速というか、そういった言葉も判決で使われていたように思うので、こちらにあるようにじっくりと周知しつつ、説明しつつ、丁寧に進めていっていただきたいと思います。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"確認","question":"ちょっと八潮のところ、さっき聞けなかったので、今回この八潮地区の幼稚園と保育園の大規模改修というのは、何か突然出てきた感がすごく大きいのですけれども、いつぐらいからこの中身を検討されたのかというのを１つお伺いしたいのと、公設民営のときにおいては、国からも都からも、改めて特別な財源は来ないのですよね。民間にこれから移していくところには税金多額に投入をして、大規模改修をしていく。","respondent":"竹田保育課長","answer":"ただ、民設民営につきましては補助金が出ます。ただ、今回品川区としては初めてのケースですので、より慎重に民営化をしていくために、まず公設民営で十分検証しまして、そして民設民営を検討していきたいという考えです。","id":"exchange-073"}]},{"id":"topic-05","title":"公有地活用による公設民営型保育園の開設","agenda":"公有地活用による公設民営型保育園の開設","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"運営の主体なのですが、希望です。開発絡みだというのは重々承知をしていますが、必要に応じては延長可能なのかどうか、その点をぜひ必要な部分で、５年ではまだだなと思うので、延長可能にしていただきたいなと思うのが１点です。3)の計画概要の年齢構成なのですけれども、１歳から５歳となっているので、ゼロ歳がありませんが、この辺、地域要求とも絡めてどういう検討をされたのか聞かせてください。","respondent":"今井待機児童対策担当課長","answer":"期間につきましては、今品川区では平成３０年末を目途に待機児童の解消を予定しておりますので、これが開設しましての中ごろの年になりますけれども、その状況を踏まえてとなります。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問","question":"今、最後のところなのですが、１歳児を担保していきたいと、当然だと思いますけれども、地域要求としてここにゼロが入っていない、ああ残念だな、あったらいいのになと思うような、その辺の高い要求とかは特別ないのでしょうか。その点だけ。最後。","respondent":"今井待機児童対策担当課長","answer":"この近隣では八ツ山保育園も１歳児園ですけれども、北品川第二ですとか、近隣にもほかの認定こども園等もありますので、全体の地域バランスとして１歳児で適当だというふうに考えているところです。","id":"exchange-075"}]},{"id":"topic-06","title":"の２、その他を行います。 まず、(1)所管質問","agenda":"の２、その他を行います。 まず、(1)所管質問","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今委員長から言っていただいたとおりなのですけれども、鈴木ひろ子議員の代表質問「待機児ゼロ先送りを撤回し、認可保育園の大幅増設を保育士がコロコロかわる区立保育園の民営化はやめよ」の質問で、その中で１,１８５人の不承諾数が出されたのですが、その年齢の内訳と新年度、平成２８年度４月の受入れ枠拡大数、そしてその拡大した枠のゼロから２歳児の内訳、３歳以上の内訳をお聞かせください。","respondent":"今井待機児童対策担当課長","answer":"８３９のうち、ゼロから２歳の乳児の受入れ枠３７６が４月１日時点での拡大数になります。３歳以上の幼児につきましては４６３という数です。","id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/702264?Template=document&Id=4878#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":65061,"voices":214}},{"id":"h28-20160223-5","meetingId":"h28-cm02","date":"2016年2月23日","dateIso":"2016-02-23","committee":"総務委員会","time":"午前１０時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件抜き出しています。","topics":[{"id":"topic-01","title":"平成２８年請願第１号 雇用促進住宅八潮宿舎存続のための施策を品川区に求める請願","agenda":"平成２８年請願第１号 雇用促進住宅八潮宿舎存続のための施策を品川区に求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この間、議員間討議もやってきましたけれども、区に対応を求める請願ということもありますので、幾つか区にも対応について伺いたいと思いますので、よろしくお願いします。冒頭、機構が丁寧な対応をというお話がありましたけれども、機構にどんな対応を求めているのか。この２点、まず伺いたいと思います。","respondent":"柏原企画調整課長","answer":"説明会後に、区のほうにも、そういった説明をいたしましたというお話がありましたので、きちんとした対応をとるようにという、とっていただきたいというような話はさせていただいたといったところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"機構の対応について伺ったのですけれども、きちんとした対応をとるようにというのは、要するにどういうことなのか。この点を少し具体的に住民の方にお話を伺いましたけれども、仮に民間売却された場合も、１０年後はどうなってしまうのかという不安の声も伺っております。売却先が見つからず更地になったときも、自分たちは一体どうなってしまうのかという不安を強く訴えておりました。","respondent":"柏原企画調整課長","answer":"ちょっと繰返しのところにもなってしまいますけれども、そういったところでの対応を、まずは、国としてのしっかりした対応を進めていくというのが、まず第１番ですので、そういったところ、将来のところに関しましても。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"更地であればそこには住めないよと。そこはしっかりとご説明いただきたいと思います。いわゆる修繕積立や何なりいろいろ、この間、築３０年とおっしゃっていましたでしょうか、３２年、ありますので、マンションとしては、実際に見ても、十分まだ住むことができる、修繕も含めて住むことができると私は思うのですけれども、区が購入を拒む理由を改めてご説明いただきたいと思います。","respondent":"柏原企画調整課長","answer":"あと住民の方の、どういった対応の具体的なところというお話ですけれども、それも、お住まいの方の立っている立場というところであれば、例えば１０年後どうなるかであるとか、民間売却ができなかった場合だとか、その先のことを、では住民の方がどういうふうに対応といいますか。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"とにかく住民の住まいの継続を、そういう立場に立つべきだと思いますけれども、２点目、そこはいかがでしょうか。最後に、機構が区にも示したこの購入金額、２２億円というように伺っているのですけれども、マンション３棟でこの金額というのは、例えば一般のマンションに比べて、区は高いと思っているのか、安いと思っているのか、妥当だと思っているのか、この辺についても率直に伺いたいと思います。","respondent":"柏原企画調整課長","answer":"それから金額等々につきましては、通常の、民間で売買されている金額というところとは、これはちょっと、そういった趣旨でできている住宅ですので、単純な比較はできないだろうというふうに思ってあります。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"一応、きちんとこの借地借家法に基づく契約があるわけで、オーナーが変わればオーナーチェンジですから、今までの法、借地借家の、そのまま継続されるということだと思うのですけれども、さらに１０年後、下げるとか、更地にするとか、いわゆるオーナーさんの一方的な、家賃を下げる、また退去を求める、これは両者が合意しないと、借地借家法に基づいて借家人を保護する規定があると私は思うのです。","respondent":"柏原企画調整課長","answer":"その八潮の住宅などの施策をどう取り組んでいくかといったところを鑑みながら、例えば空いているところ、部屋についてどういうふうに活用するのか、そういったところで、住宅の関連部門と検討しながら進めているといったところがあります。それから後段の、法律の関係の部分です。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の区の対応では、住民が住み続けられない。今日的に、住宅の新たな役割も、八潮のまちづくりという観点で必要だと思いますので、ぜひ、ここに書かれているとおり、機構との話し合いや、また区の購入や、閣議決定の廃止・撤回、それを求めていただきたいと強く要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"区としては、今この住宅にお住まいになっている方々の実態とか現状というのは、どの程度把握をされているのでしょうか。例えば対象者などです。例えばこの住居がなくなったときに、転出してほかで生活が成り立つ資力をお持ちの方と、そうでない方と、やはりいらっしゃるのではないかと思うので、その辺の把握というのはどうなっているのでしょうか。","respondent":"柏原企画調整課長","answer":"こちらの世帯の方々で、概ね３２０から３３０世帯ぐらいの方というところでの把握は、機構のほうからも情報をいただいていますので、そういったところの把握はしているといったところです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"平成１９年の閣議決定で廃止が決まって、これを区として、完全に覆すというのはなかなか難しいことかと思っているのですが。機構に対して、確実にそれを履行するような、区としてはお考えがあるのか。もし、機構が不十分であった場合に、区がその役割を補うというのも、区民への責任としてあるのではないかと思うのですが、その辺のお考えはいかがですか。","respondent":"柏原企画調整課長","answer":"それは、そのどういった対応をして、その先をどうするのだ、検討して進めるのか、そういったところを、きちんと、明確なビジョンといいますか、お話をして、説明をしながら進めていく、それがまず一番、第一義だというふうに思ってあります。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"一方で、もう平成３３年にはというような数字も出てきておりますけれども、３３年度末ですか、民間で売却できなければ３３年度末ということで、もうこの春からは、一応、民間を探す手続きに入る。結局だめでしたというのが３３年度末だったら、もうその方々の生活というのは継続ができなくなってしまうのですよね。その辺の見通しの示し方というのはどういうお考えでしょうか。","respondent":"柏原企画調整課長","answer":"こういう言い方はあれですけれども、通知１本だけで終わらせるようなことも、若干、区に対してはあったことがありますので、情報の交換は、きちんと情報をこちらにもくださいというような話はしているところではありますので、そういった中で、区としての考え方といいますか。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"ということは、先ほどから、丁寧な対応を申し入れるというようなお話をしていても、それはお願いベースであって、機構がそれをするかしないかというのは、こう言っては何ですけれども、区の意向にかかわらず、機構が自分でやる・やらないを判断し、区としてはお願いはするけれどもその先はどうかわからない、そういう関係なのでしょうか。","respondent":"柏原企画調整課長","answer":"ちょっと同じ言葉での答弁になってしまいますけれども、きちんとした丁寧な対応というのはずっと言い続けている中で、こちらのほうとしても、より突っ込んだ対応というのを、地元の自治体、それは売却をこちらで受けるのかという、それ以外にも。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"今の件。区は、情報提供なり対応をお願いをして、機構はどのような反応をしているのですか。はい、わかりました、みたいな話なのか。あるいは、どう対応するというようなことを、区と相談するような姿勢であるのか。今のところ、機構としては、区に対してどういう、今後の対応について、どのような説明をしているのでしょうか。聞いても、まだ説明がない状態なのでしょうか。","respondent":"柏原企画調整課長","answer":"情報といたしますと、こちらのほうが、どういうふうに進めるのだというような中で、年次を、民間売却へ向けた動き、それからそうでなかったときの対応をどうするかといったところのお話を、こちらも情報としてはいただいているといったところであります。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと話がずれてしまいました。機構に聞いているのは、要は、売却の手続きや、手放す手続きについては確かに情報提供があると思いますけれども、そうした措置をとったときに、住民の方々にどのようなフォローを行うかということの対応についてはどのような説明があるのでしょうか、まだないのでしょうか。聞いていないのか、あるいは聞いたけれども答えてきていないのか。そこを含めて教えてください。","respondent":"柏原企画調整課長","answer":"具体的なところでどういう形をとっていくかというのは、その辺のところの情報交換はできていないというのが現状ではありますけれども、ただ、民間への売却、それからそうでなかったときのあり方というところがありまして、さらにそれに対して。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっと繰返しになりますけれども、住民への対応をどのようにするかというのは、ここはやはり、区も責任者の１人として、ぜひ積極的に関与していただきたいと思います。このお考えについて、ご答弁ください。もう１点なのですけれども、この建物が、先ほどもちょっと、月２,０００万円ぐらいの収入があるということで、年間に直すと２億４,０００万円。","respondent":"柏原企画調整課長","answer":"それから先ほど申しましたように、半額という、そういう提示はあった、その金額ですので、我々、住宅とかマンションを経営する立場の者ではありませんので、施策として何をするかといったときに、いろいろなことを、条件とかいろいろ考えたときに、そういった金銭的なところでも。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"わかりました。前半のほうは、ぜひよろしくお願いいたします。それと、後半のほうです。１０年間固定となると、なかなか厳しいものもありますが、大体１０年間で、ちょうど購入金額に見合うという、いわゆる表面利回り１０％的な数値なわけですけれども。そうすると、築４０年、１０年後。一旦、私の質問はこの辺にいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"なので、この独立行政法人高齢・障害・求職者雇用支援機構に管理を任せているということは、もう既にやはり、最初の雇用促進に絞ったところから、国の施策が、この住宅の目的とするのは、少しずつ変わってきているのではないかというふうに理解するのですけれども、それは違うのでしょうか。教えてください。","respondent":"柏原企画調整課長","answer":"ただ、先ほどありますように、雇用促進住宅の部分に関しましては、国の一定程度の方向性というのが出ましたので、その中で運営をしていくというような業務の位置づけというのを、この機構が持っているというふうに思っております。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"この八潮に関しては、ちょっとこれ、あべ委員の最初のほうのご質問に重なるかもしれませんけれども、今住んでいらっしゃる方の実態として、その辺のことは把握していらっしゃるのでしょうか。","respondent":"柏原企画調整課長","answer":"現在も定期借家の中で、居住者の方を受け入れようとしているというふうに聞いてありますので、一定程度、やはりその雇用促進に関する部分での住宅としての目的を今も果たしているというふうには考えているものです。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうもさっきからお話、皆さんの議論を聞いていても、この機構と区の、何というのでしょう、話し合いというか、それがすごくデジタルというか、文書で申し入れがあった、何か質問したという感じで、すごく、もうちょっと具体的にお互い、今住んでいる人たちの、今後の暮らしを保障するというか、そういうような視点での、お互いの話し合いみたいなところはないのでしょうか。","respondent":"柏原企画調整課長","answer":"そういった中で具体的な内容といいますか、どういうふうな展開をするのだというところにつきましては、今後とも動きが出ましたらいつでも、今後も逐一把握してまいりたいとふうに思ってありますし、そういった進め方でいきたいというふうに思っています。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"私もちょっとお話も伺ったのですけれども、やはりいろいろな方があって、将来的にはどこか故郷に帰るからとか、転勤があるからという方も住んでらっしゃると聞いていますので、いろいろな事情の方があると思うのです。だから、その辺の、きめ細かな施策ができないものなのだろうかというふうに思うのですけれども、その辺についてはいかがでしょうか。","respondent":"柏原企画調整課長","answer":"具体的なところが、機構のほうからどういう手順で、どういう手法、手法といいますか、条件ではないですけれども、話をしていくのだというところが見えていないところがあるというのはありますけれども、おひとりおひとり、世帯世帯の、お住まいになられている方の。","id":"exchange-018"},{"speaker":"吉田委員","kind":"意見","question":"今現在、そういうふうに申し入れをしていて、それでも機構としてのその対応があまりないということで、こういう請願が出てきたのではないかというふうに思うのですけれども、その点につきましては今後どのように捉えられるのか。","respondent":"柏原企画調整課長","answer":"それをどういう形で進めていくかというのを、機構のほうで検討しているところではないかと思いますけれども、そこに対して、それが先ほど来、ちょっと曖昧な言い方に聞こえるかもしれませんけれども、丁寧な対応をしていただきたいというところに。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"とりあえずこれで最後にしますが、やはり機構が今どうしているかが、私たちも把握できない。今の皆さんからの質問からの答えでも、それから今、私が伺った範囲でも。だからもうちょっとやはり何か、例えばこの請願を判断するのに、１回機構からのお話を委員会として聞くなどということは無理なのでしょうかね。ちょっとそれは委員長に対する質問になるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"提案","question":"はい、わかりました。最後に、ではちょっと意見としては、もう少しやはり機構が今どういう対応をしているのか、総務委員会として聞いてはどうかなということ。こちらは皆さんへのご提案ということで、一旦やめます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"我々、生活基盤どうなるんだとなったときに、これは準拠されるかどうかわかりませんが、借地借家法というのがあるわけですから、簡単に退去、その人を追い出すということが可能なのかということを考えますと、そんなこと、期限を切られても、なかなか出て行かなかったら、出せないような気もするし、何か今、机上の空論で。一応、ちょっと意見だけ言わします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"昭和５９年の運営開始から３１年強なのですが、その間の背景をちょっと教えていただきたいのですけれども、この雇用福祉事業で建物が建って、ニーズが当時相当あったと思うのです。運用開始の３１年前から、この３１年間内で。その辺の時代背景というのを何か、もし把握されていたら教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"この八潮の宿舎に関してだけということでなく、一般論のところもちょっと入ってきますけれども、この雇用促進住宅という住宅の性格そのものが、職場が変わって大きな転勤だったりとか、場所を移らないと仕事ができないというような方々、例えば一般論で言われるところでは。","id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"ただ今、先ほど机上の空論という言葉がありましたが、まさに今この場で生きた議論をやっておりまして、この請願の気持ちを区がどう考えるのかという審議をやっている中で、この請願に書いてあるのが、品川区は購入等々、購入したりできなかったときの措置を講じてくださいとか、３３年度末の延長を政府に求めてくださいとか、こうした請願の気持ちを、区は誠意に応えているわけです。とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほどご答弁の中で、機構からの一方的な通知があったと、最初は多分、そういったところもあったと思うのですけれども、丁寧な対応を求めていく。求めていくというまでご答弁はしていないかもしれませんが、先ほどのご答弁の中で、契約形態の違いによる対応の問い合わせみたいなものもされたということがあったのですけれども、そこについてはちょっとお聞かせいただければと思います。","respondent":"柏原企画調整課長","answer":"それに関しましては、その期限が切れたところで、その契約は終わると。通常はその流れになるかと思いますので、そこでの、次のお住まいの対応ということになると思います。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"今のご答弁に関することでちょっと１点だけ念のために確認させていただきたいのですが、先ほど全国でこういう問題が起きているのではないかと申し上げましたけれども、例えば自治体が購入をすることについて、何か情報があるのかどうか。購入に限らず、何かそのほかの手段で自治体がそういうふうに関与した部分があるのかどうかという、何か情報があればそれを教えていただきたいです。","respondent":"柏原企画調整課長","answer":"それ以外では、今、我々がお話を聞いた、品川区に話がきたのと同様な形の動きというのは、この近郊ではないというふうに承知しております。","id":"exchange-026"},{"speaker":"あくつ副委員長","kind":"確認","question":"福島では、ああいう原発事故があって、大震災の影響もあって、事情があると思います。東京都ではないということ、今のところはつかんでいないということは確認させていただきました。最後になりますけれども、先ほど、そのやりとりのことがありましたが、ほかの委員からもありました。繰返しの答弁になってしまうかもしれませんが、そこについてもう１回お聞かせください。","respondent":"柏原企画調整課長","answer":"いろいろ、これまでご議論をいただいているところではありますけれども、主体として動いている機構に対して、方針をきちんと立てていただきたいというところで、丁寧な対応というところで、情報の共有であるとかといったところで、後の動きをどう見て。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問・要望","question":"２点ほど。１点目なのですけれども、最初の最初の質問でいたしました居住実態、確かに個人情報の関係で、区が行政として公に入手するのはなかなか難しいことだと思います。それによっても、区の動き方というのは大きく変わってくると思います。それからもう１つ。もう日本がどんどん使い捨て社会になってしまうというのは、もったいないと思っているのですけれども、その辺のお考えはいかがでしょうか。","respondent":"柏原企画調整課長","answer":"ちょっと難しいお話だろうと思います。","id":"exchange-028"},{"speaker":"大沢委員","kind":"質問・要望","question":"いわゆる、この雇用促進住宅でありますから、国の政策判断に任せる、これが第一義だと思いますけれども。その制度の違いを埋めるべく、やはり様々な工夫を凝らしていただきながら、この雇用促進住宅の居住者の方に対する対応に当たっていただきたいと思います。そこの微調整は、今後される、その場合になったら、していく必要があると思うのですけれども、どうでしょうか。","respondent":"柏原企画調整課長","answer":"先ほど来、お話し申し上げている雇用促進住宅というところには１つの目的を持った考え方があって、先ほどもちょっと議論させていただきましたけれども、いろいろな今までの背景がある中で、居住者の方の形態といいますか、ということも変わっていったところがあります。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問・要望","question":"このことに関しては、最終的には国の管理する、この部分に関しては、私は、国の政策判断に任せるべきだと思いますので、区は、先ほどお話をしたように、各々のいろいろな部分の制度をうまく使いながら、この居住者の方たちに対する今後の対応をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"中塚委員","kind":"確認","question":"ただし、まずもって国の対応自身の不十分さも改めて思いました。直接、機構がどう考えているのか、具体的にこの先どういう対応を考えているのか、そこはやはり委員会としてしっかり聞く必要があるのではないかと、私は議論を伺ってそう思いました。それで、その判断は判断としてあるとして、委員会条例上、この機構の責任ある人を委員会にお呼びしてお考えを聞くということは、委員会条例なのでしょうか。","respondent":"原区議会事務局長","answer":"委員会条例、品川区の中には当然ございまして、その中に、公聴会の開催があって、あるいは参考人というような位置づけが各条項の中で持たれると。それは委員会が決定した場合においてという、当然のことながら判断があってというような、そういうような仕組みになってあります。","id":"exchange-031"},{"speaker":"本多委員","kind":"質問","question":"今日、結論を出すという考えであります。先ほど、ほかの委員から発言がありました参考人の件、申し入れにつきましては、当然手続き的にありだと思います。申し入れのとおりにするのであれば、結論を今日出さないで継続に、今日の招致は難しいでしょうから継続になると思うのです。結論については、願意に、思いはわかりますが、願意、区が買うとかは難しいと思いますので、不採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、今、必要なので、今の時点では、住民にとってはせっぱ詰まった問題ですので、結論を出すということと、雇用促進住宅八潮宿舎の存続のための施策を品川区に求める請願は十分に理解できますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あべ委員","kind":"意見","question":"本日、結論を出すということでお話ししたいと思います。ただ、この請願が、雇用促進住宅八潮宿舎存続ということを第１に出されている。閣議決定が９年前になされて、全国で同じような状況が進んでいる中で、ここをひっくり返す方向というのは、なかなか、私、困難だと考えています。結論としては不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、本日、きちんと判断を示していきたいと思います。要望としては、品川区は、今後も、やはり機構に対しては、住民に誠意ある対応をしてほしいということで、今後も要望してほしいということ。住宅に住まわれる方々に対して、親身なアドバイスを、私はしていただきたいと思います。民間のマンションもあります。今回の請願に対しては、私は反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"吉田委員","kind":"意見","question":"いろいろな思いの方もいらっしゃるようなので、この請願項目１つ１つはここまで、ちょっと採択するのは難しいのではないかという項目があるのですけれども、それを判断するためにも継続を主張して、ぜひ機構の方たち、それでもっと可能なのであれば、誰か住民のそういう思いを持った方たちの話もきちんと聞いて判断すべきというふうに考えて、継続を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-02","title":"平成２８年度都区財政調整","agenda":"平成２８年度都区財政調整","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に事業名でご説明いただけるとわかりやすいので、ご説明いただきたいと思います。こういう規模というのは、今後どれぐらい続くというふうに見ているのか、区の見通しというのでしょうか。もちろん、先行きいろいろ不安定な要素もありながらも、現状で思う区の見通し、こういう規模がどういうふうに続いていくのか、そこの考えを伺いたいと思います。","respondent":"秋山財政課長","answer":"これについては、景気の動向にかなり左右されるということで、今後どうなるかというのはなかなか見通しとしては難しいものですけれども、このようなことがずっと続いていくというふうには当然考えてございません。今回はこういう結果になったということで考えるところです。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１回、３ページ目の新規算定等で、区の具体的な事業でいうと、というように伺ったのですけれども、例えばこの子ども・子育て支援新制度で、ここに当たる部分は、区でいうと、例えば開設支援なのか、それとも、いろいろ事業があるとは思うので、もちろん、区の判断で使うものですから、縛られているものでは、縛り方というのは違うのは違うのでしょうけれども。","respondent":"秋山財政課長","answer":"それから耐震診断支援ですけれども、これは、住宅の耐震化の目標が、２７年度までに９０％というものから、国等の基準が変わりまして、平成３２年度までに９５％ということで、エンドが延びて％は上がったということで、その算定を継続するというものです。","id":"exchange-038"}]},{"id":"topic-03","title":"休憩前に引き続き、総務委員会を開きます。 次に、(2)品川区シティプロモーション","agenda":"休憩前に引き続き、総務委員会を開きます。 次に、(2)品川区シティプロモーション","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"コースターの配布をかなりされていると思うのですけれども、これは、どういうシチュエーションで使うことを想定されて、制作・配布をされているのか。家庭内でも今、紙のコースターとかはあまりないと思うのですけれども、何かこう、特段のイメージがあれば教えてください。もちろんしていると思うのですけれども、一応、確認で。","respondent":"中元広報広聴課長","answer":"こちらのほうは１月末に納品されまして、いろいろな、区長・副区長の出席会議などで使わせていただいているところです。缶バッジのほうは５,０００個を発注いたしまして、３月１０日頃に納品の予定です。","id":"exchange-039"},{"speaker":"あべ委員","kind":"意見","question":"ということは、コースターは、コースターとして使ってもらうというより、コースター型の、何というか、チラシといいますか、そういうイメージなんですね、わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"あくつ副委員長","kind":"質問","question":"ピンバッジなのですけれども、私もつけさせていただいていて、結構、反応があります。これは今後４,０００個発注をして、納入されたということですけれども、どういう形での配布を考えられているのか。もしくは販売等を考えられているのか、ちょっと伺いたいと思います。","respondent":"中元広報広聴課長","answer":"販売のほうですけれども、実費程度ということで考えておりまして、ピンバッジのほうは１個１００円で、缶バッジのほうも１個１００円ということで考えています。コースターのほうが、ちょっと両面印刷なところがありまして、単価としては１枚２０円ということで予定しています。","id":"exchange-041"},{"speaker":"あくつ副委員長","kind":"質問","question":"欲しいという方がいらっしゃったのですけれども、販売する場所というのはどちらになるのですか。細かいことですみません。","respondent":"中元広報広聴課長","answer":"販売といたしましては、当面、広報広聴課の窓口のほうと、区政資料コーナーのほうで販売をするものです。もう準備をしています。ただ、納品されたものがコースターだけですので、まだ、バッジ等につきましては４月からの販売、頒布の予定です。","id":"exchange-042"},{"speaker":"大沢委員","kind":"意見","question":"ちょっとピンバッジから話がそれてしまうのですけれども、裏面のほうの、シティプロモーション認定事業の実施予定のところで、品川宿情報発信というところがありますけれども、それは新聞の、品川区の情報ということで記事が載っておりまして、そこで品川は漁師町という。これはどちらが。ちょっとごめんなさい、指摘だけで結構です。ちょっと今思い出したもので。","respondent":"中元広報広聴課長","answer":"すみません、ちょっと私のほうで、その辺の事実関係を確認をさせていただいて、正しい認識をしていきたいと思います。","id":"exchange-043"},{"speaker":"大沢委員","kind":"質問・要望","question":"２月下旬にホームページ完成予定ということで、仮にその記述があるようであれば、ちょっとそこのところをご留意いただきながら見ていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-04","title":"コンビニエンスストアにおける個人番号カードを利用した住民票等の交付サービス","agenda":"コンビニエンスストアにおける個人番号カードを利用した住民票等の交付サービス","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"住民票の写し、印鑑登録の写し、納課税証明書というものの発行件数というのですか、見込みをそれぞれ伺いたいと思います。情報漏えいの問題ですけれども、まず教えていただきたいのが、この裏面で見ると、まず個人番号から、青いラインに沿って届いて、赤いラインで返ってくるという、そういう流れになるのでしょうか。コンビニで中継するデータそのものも、いわゆる暗号化されているものなのか。","respondent":"仁平情報推進課長","answer":"１点目のご質問の交付見込み、取扱い、今後サービスを開始した後でどのぐらいを見ているかですが、これも歳入予算の審議の内容にはなってしまいますけれども、一応、ご参考までに、所管のほうから聞いている話ですと、住民票につきましては年間１万５,０００通。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"この情報漏えいのことですけれども。今度はコンビニにあるマルチコピー機になるわけですから、そういうところの情報漏えいの対策というのはどういう仕組みになっているのか、伺いたいと思います。その辺については矛盾するのではないかと思うのですけれども、持ち歩くべきものなのか、持ち歩かないほうがいいものなのか、改めてそこを伺いたいと思います。数字だけだとあれですよとか、記号とか。","respondent":"仁平情報推進課長","answer":"２点目のご質問の、マイナンバーカードをあまり持ち歩かないほうがいいという、そういうお話も出ておりますけれども、このコンビニ交付、個人番号カードの制度のために伴いまして、区民の利便性を向上させていく１つの手段というふうに考えておりますので、必要な場合には。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問","question":"例えばコンビニのマルチコピー機で解読するのであれば、そこで悪意をもって、違法なことでとろうと思ったら、そういう余地を残してしまうのではないかというように、単純に仕組みとして思ったので、返ってくるＰＤＦのほうで、改めて伺いたいと思います。マイナンバーにかかわる、今までかかったお金もそうですけれども、全体のお金がどれぐらいかかるのか、そこを伺いたいと思います。","respondent":"仁平情報推進課長","answer":"来年度予算まで含めますと、２７年度は決算の見込みという形になりますけれども、システムの開発関係で６,９４０万円ほどを予定しております。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり情報漏えいの危険はもちろん、３年間で３億円を大きく超える予算をかける、そもそも人に番号をつけるというのもけしからん話だと思いますけれども、マイナンバーはやめるべきだと思いますので、中止を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"先ほどの発行業務の件数なのですけれども、それぞれお答えいただいたのですが、今、年間で、それぞれ何通発行されているのかということと、それぞれ今、窓口の場合は手数料がいくらかということをお伺いします。","respondent":"仁平情報推進課長","answer":"今回、住民票をコンビニ交付で予定している件数でいいますと、先ほどは１万５,０００件というふうにお話し申し上げました。一応、見積り上、証明書送付件数の１０％というふうに見込んでいるところです。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"それぞれありがとうあります。先ほどの数字を全て１０倍すれば、年間の発行枚数ということですが、それぞれ手数料３００円ということで、コンビニで行う場合は１通２００円というふうになっているのですが、この差額の根拠というのはどのような考え方によるものですか。","respondent":"仁平情報推進課長","answer":"これの決め方といいますか、２００円にしたというのは、近隣区のほうを参考にさせていただいたのと、コンビニ交付での交付の促進を、全体的な発行業務の効率化につなげていきたいということで、促進していきたいという思いと。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問","question":"一方でコンビニの場合にはランニングが７ヶ月で１,３００万円と。先ほどの１万５,０００通、計２万５,４００通ですか。割り返すと１通当たり５００円ぐらいはかかるようなランニングコストなわけですよね。一方で、コンビニでの利用を促進するために、本当はもっと手数料としてはかかるのだけれども、あえて政策的に安くしているという意味なのでしょうか。","respondent":"仁平情報推進課長","answer":"これは一応、歳入の２００円のほうも見込んで、持ち出し分を割り出した数字としての形になります。それと手数料の２００円なのですが、政策的なところはあるかと思いますけれども、その額の決定自体は私のほうではございませんので、立場上ちょっとお答えが難しいです。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"窓口のほうは１,０００円弱というのは、３００円を算入して１,０００円弱なのか、それとも算入していないのかもわからない。それなりにマイナンバーは、むしろ安くなるということではなくて、より、区役所の窓口以外でも簡便にとれるということがメリットだったと思うので、これを２００円にしなければいけない理由が私にはわからないのですけれども、その辺はどうなのでしょうか。","respondent":"中山企画部長","answer":"冒頭言ったように、条例そのものの審議を区議会でやっていただく中で、今のも理由についてご説明している部分があって、細かいコストに基づく分析的なものができてどうかという、私もそこまで細かく、所管として周知しているわけではありませんけれども。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"新しい制度だから、導入に際してというのもあると思いますけれども、やはり区民の方に、行政としてどういう価格設定、手数料設定をしていくかというのは、ぜひ常に見直しながら進めていっていただきたいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"すみません、さっきの数字なのですけれども、住民票の写しの利用の見込みが１万５,０００件で、数字の立て方としては、今利用されているものの１割程度というお返事だったと思うのですけれども、ということは、１５万件ぐらいということでよろしいのでしょうか。ちょっとごめんなさい、その数字だけ、まず。","respondent":"柏原企画調整課長","answer":"先ほど来お話が出ている数字については、来年度の見込みということで出していますので、予算の審議にかかる部分ではありますが、見込みとしては、１０％程度ということで見込んでおりますので、住民票については１万５,０００通を見込んでいますけれども、全体。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"すみません。それは、予算にかかわることだというのは承知していますが、知りたかったのは、住民票ってどれぐらい発行されているものなのかということで、ずっと、区民の利便性ということで、コンビニでの発行となったのですけれども、この数字をどう見るのかというのが、１つ検討すべきことかと思います。それなので、ちょっと数を伺いました。","respondent":"柏原企画調整課長、仁平情報推進課長","answer":"昨日、同様の議論のほうがあったかどうかちょっとわかりませんけれども、私どもはそういう考え方、捉え方をしているものです。４桁パスワードの変更なのですが、ちょっと私のほうも、そういう簡単な仕組みができるのかどうかまでは承知していないのですけれども、今後、国のほうでマイナポータルといいまして、個人のパソコンのほうから個人番号カードを使って。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"私は、区民全体、マイナンバーカードということが、その区民の利便性に資するということだったのですけれども、これが区民全体の利便性という意味ではどうなのかと。税を投入するということは区民全体、ある程度カバーするところの利便性を高めるためというふうに考えるべきではないかと思ったので、その辺のお考えを伺いたかったのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"今、利用されていない方もこの先利用する可能性もあるといったところを考えたときには、広い意味では、やはり多くの方が利用されるサービスに、区役所としては重要なサービスの１つだというふうに思いますので、そういった意味で、身近でそれが、今までよりも時間が長いといった。","id":"exchange-056"},{"speaker":"あくつ副委員長","kind":"質問","question":"区民委員会、昨日審議されたということで、切り分けは難しいのですが、ちょっと情報推進の観点から、同じ質問かもしれませんけれども。先ほどから近隣区を見てというお話がありましたけれども、２３区としては、そういうことをどういうふうに取り入れ、導入を考えられているのか、ここについて伺いたいと思います。","respondent":"仁平情報推進課長","answer":"区のほうも検討はしたのですが、ちょっと国のほうが、全国的に戸籍の関係のシステムのあり方を見直しまして、区の場合、戸籍の住所といいますか、それと住民票が一致する方が全体の４割ぐらいいたということで、個人番号カードを取得されても。","id":"exchange-057"}]},{"id":"topic-05","title":"区立公園におけるフリーＷｉ－Ｆｉサービスの運用開始","agenda":"区立公園におけるフリーＷｉ－Ｆｉサービスの運用開始","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"私はあまり、まだそんなにＷｉ－Ｆｉを使ってどこかへ旅行へ行くというのは、でも何となく、駅を降りたときとか、あと、それこそこういう区役所やきゅりあんやスクエア荏原や、何かイベントで集まるところや、手続き系、道案内であれば交番とかもそうかもしれないけれども、区民や区の来訪者の観光や防災で収集して、という視点に立つと、やはり多くの駅前や、また、この防災のときを思うと。","respondent":"仁平情報推進課長","answer":"その他、観光施設とか、それから区の施設関係ですけれども、この辺も、ちょっとやり方、費用のかけ方等も含めまして、順次検討していく予定としております。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"区民や来訪者の利便性を高めるという意味は、どこのスポットがどういう利用や、またその流れがあるのかというのは、よく調べて、優先順位をつけられたと思うのですけれども。例えば、オリンピックをどうすれば、当然、オリンピックの会場や、そこに向かう道や。あまり予算にかかわらないように、今後どういうふうに展開があるのか、もう少し伺えたらと思うのですけれども、質問します。","respondent":"仁平情報推進課長","answer":"その中で区のほうですけれども、ちょっと鉄道関係とか、公共交通機関関係は、それぞれの事業者のほうの責任の範囲かと思いますけれども、区は区としまして、ちょっと民間では難しいようなエリアとか、あとは区の関係の施設、この辺をちょっと主眼にして。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"順次整備されていくのはいいことだと考えています。利用時間は１回６０分で、１日の接続回数に制限なしというのは、結構、大盤振る舞いといいますか、利用者には使いやすいといいますか、公共施設の中でも、これだけいい条件で提供しているということはすごいなと思います。災害時は別の運用方法があるのか、そのあたりを教えてください。","respondent":"仁平情報推進課長","answer":"区が今回提供しているサービスの能力的な話になりますけれども、一般に店舗等で導入されているフリーＷｉ－Ｆｉ、入れてらっしゃる店舗とかがありますけれども、あちらのものよりははるかに能力が高い設備でございまして、１アンテナ当たり３００人が同時に通信できるような。","id":"exchange-060"}]},{"id":"topic-06","title":"障害者差別解消法施行に向けた区の体制","agenda":"障害者差別解消法施行に向けた区の体制","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"名前とかではなくて、役職はどちらも副区長という身分なので、それは２人ともなのかと思うのですけれども、本部長はどちらかということが１つ。アンケートだったり聞き取りだったりありますけれども、まずは発足ということなので、幅広い参加や、また当事者からの悩みや意見やお声や、しっかり聞き取るということが大事だと思うのですけれども、その点について、どういう位置づけか伺いたいと思います。","respondent":"米田人事課長","answer":"当然、障害をお持ちの方、当事者の方の、例えば行政での現在の対応等についてのご意見等があればそれを拝聴してというようなことで考えておりますので、その辺は随時、例えば職員の対応要領というようなものでも、我々としては当たり前のものとして。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、実際にこれから始まるというものですけれども、例えばこの１年間でどういう取組みや、どういう成果や、どういう議論や経過があったのか、そういう報告書というのでしょうか。全体の本部の、報告書、成果物、そういうものというのは年度末にお考えなのか、ぜひ、こういうものが必要ではないかと思うのですけれども、現状を伺いたいと思います。","respondent":"米田人事課長","answer":"当然、進めていく中で、いわゆる推進本部というものを設置してまいりますので、それぞれの所管のところでの対応についての声というものを拾ってまいりますので、その中で、こういうふうに動いていったというものについては。","id":"exchange-062"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、この体制はこれからつくるということなのですか。職員対応要領もこれから作成するということなのでしょうか。","respondent":"米田人事課長","answer":"職員対応要領というものにつきましても、先行して国の省庁等で対応要領というものが示されておりますし、また、障害を理由とする差別の解消の推進に関する基本方針というものの中にも、自治体の努力義務として、対応要領。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問・要望","question":"いわゆる手帳を持った方だけが障害者ということではなくて、合理的な配慮が、つまり配慮が必要な方、それぞれに配慮をしていくということが法の趣旨だと思いますので、そういった意味では、いわゆる障害者と位置づけられていない方々に対しても、例えば発達の関係ですとか、少し読みが苦手とか、いろいろなタイプの区民の方がいらっしゃると思いますので、以前。","respondent":"米田人事課長","answer":"合わせて、職員対応要領を策定するに当たっては、現在、窓口で、障害者の方と対応しているときに、何かお叱りのご意見をいただいたりというようなことがあったりしたら、それを上げていただくとともに、どういうようなことを各窓口でやっていったらいいかというようなことでの。","id":"exchange-064"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ、このしながわこころつながる映画祭の開催ということで、いろいろと企画をこれからされると思うのですけれども、いろいろないい映画を見て意識が高まると思うのですが、ぜひ「ゆずり葉」を、こういう機会ですから、こういう組織が立ち上がるわけですから、全職員に見ていただきたいと思っています。","respondent":"米田人事課長","answer":"どういうような形で、職員に向けて研修・啓発を行っていこうかということ、啓発・働きかけを行っていこうかということにつきましては、こちらのほうでもある程度具体的なものとしての検討を始めているところですが、委員より今ご指摘のありましたものも含めて。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、この職員研修が、既にいろいろ考えられていると思いますけれども、具体的にどういう形で、今、映画のこともありましたけれども、どういう内容で行われているのか、もしくはこれから行おうとしているのか、そのプログラムなどがあれば教えていただきたいと思います。","respondent":"米田人事課長","answer":"それからあとは、新入職員のほうについても、やはり最初に窓口対応等をするに当たって、ある種、その辺のところの意識づけということでは、職員同様にやはり大事だと考えていますので、そういうようなところでの、例えば今年度やっておりますところでは。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、そういうような視点のプログラムをつくっていただきたいというふうに思います、これは意見です。それか、もっとフリーな、そこで出た意見を全部とり入れるとかそういうことではなくて、とにかく意見を出す場を設定するというようなことは、これを機会に考えていらっしゃるか、もしくはこれから検討をする余地はあるのかどうか、その辺のお考えを伺いたいと思いますが、いかがでしょうか。","respondent":"米田人事課長","answer":"文書のほうで、職員対応要領ということで書いておりますが、対応という言葉が出てきておりますけれども、当然、対応要領は努力義務ということなので定めていこうというふうには考えてはありますが、その根底にあるのは。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"前、あそこに防災の公園を、ヘリポートとかつくる所の視察に行ったときに、ちょっとその後の会議の場面で意見を言ったのですけれども、品川区の区役所の障害者福祉課、場所の説明は何と言ったらいいのだろう、３階の受付を入ってエレベーターの向かい側にあるトイレ、だれでもトイレというのでしょうか、あそこはベビーだけでないおむつ交換台があるのです、大人の。","respondent":"米田人事課長","answer":"前段の部分については、いわゆるこちらで本文にありますほうの相談対応というところでの強化ということで、まさしくこれは苦情も含めた、あるいはご心配事も含めた相談対応の強化ということは、障害者福祉課が中心となってまいりますけれども。","id":"exchange-068"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"この合理的配慮というところについて、本当に研修、先ほども何度も出ましたけれども、形一遍の研修だけではだめですよということで、ケーススタディであるとか、ワークショップということで、今後やっていかれると思うのですけれども、こうした過去の事例等も、ぜひ品川区で起きたということも含めて、成人式の、数千人単位の、非常に人がごった返している中ですから、普通ただでさえあんな大変な中で。","respondent":"米田人事課長","answer":"職員の部分ですので、私のほうからお答えしますけれども、そういうような個々の事例で、やはり職員の対応について、あるいは心がけについて足りなかったというようなことがありましたら、その辺については、随時あるいはその辺の事例も踏まえた、やはり職員の育成ということでは。","id":"exchange-069"},{"speaker":"あくつ副委員長","kind":"質問","question":"誠実なご答弁だと思いますし、取り返しのつかないことってあると思います、一生に一度のことですから。ぜひそういったことが二度とないようにお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"すみません、ちょっと聞き漏らしがあったので教えてください。実施のところで、職員の対象なのですが、全職員とあるのですけれども、ここに、指定管理で働く方。やっているのならありがたいのですし、ぜひやってほしいということで伺います。ハード面と、それからここは役所なので、制度面のバリアフリーというものも、合わせて考える仕組みになっているかを教えてください。","respondent":"米田人事課長","answer":"それからいわゆる推進本部のほうですけれども、やはりこれから、そういったハードであったりとか、制度面であったりということの、それぞれ所管のほうから、やはり状況であったりとか、区民の方のお声というのがやはり集まってくると思いますので。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"、それぞれ進めていただければと思います。区民のお声が上がってきて、初めて検討するということではなくて、やはりそれは積極的に、自らどこに課題があるかという視点をもってやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]},{"id":"topic-07","title":"選挙人名簿の登録に関する公職選挙法の改正","agenda":"選挙人名簿の登録に関する公職選挙法の改正","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"参考までに、これまでは二十歳ぎりぎりでの転居でこういった問題が起こり得たと思うのですけれども、品川区で該当のようなケースというのはどのくらいあったかどうかみたいなことは、特には把握はされていないでしょうか。","respondent":"工藤選挙管理委員会事務局長","answer":"こちらの数は、今までという部分は捉えておりませんけれども、今回の法改正によりまして、ちょっと私どもも、昨年のデータで試算をしてみました。そうしますと、大体１５０名前後が、今回の法改正で救われるのではないかというふうに思っているところです。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"大変基本的なことで申し訳ないのですけれども、これは１８歳と１９歳だけということなのでしょうか。転入・転出の関係だとほかの年齢もあるので、ちょっと本当に基本的なところですみませんが、ご説明いただきたい。もう１つは、そうは言っても、Ｂ区に行ったこの若者にどうやって案内をするのか。その辺の仕組みがちょっとよくわからなかったので、ご説明いただきたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"もう１つ、ちょっとございまして、ケースのほうには入れておりませんけれども、例えば旧住所地、これは選挙権年齢に達している方ですけれども、旧住所地での居住期間が３ヶ月を経過してから初めての定時登録の前に転居をして、その直後に選挙があった場合には。","id":"exchange-074"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ちょっと関連なのですけれども、１８歳、１９歳、今回新しく投票が認められたということですと、選挙権ができたということで、２点ちょっと伺いたいのです。ちょっと直接関係なくて申し訳ないのですが。東品川などにはそういうご要望もあります、大きなショッピングモールがありますので、それが１点。報道等でそれをご存じなのかどうか。この２点をお伺いしたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"そういった事例も検討はしてまいりますが、やはり一番は、選管がというよりも、事情を聞きますと、大学のほうからというのがまず１つあるということ。やはり地方大学と都心の大学は違うかと思いますけれども、地方大学になりますと、その周りに住まれている方が多いと。","id":"exchange-075"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ぜひ、最初の投票所の件については、若い方への投資ということで、検討を続けていただきたいと思います。このビラに関しては、選管の公職選挙法上というのがなかなか難しいと思うのですけれども、これは公党が責任を持ってやっていただくということです。私どもも、しっかりそれは監視をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"国立大学の値上げについて、共産党が出したビラをデマだと断定したのは事実でないので、発言の訂正を求めたいと思います。評価についての違いは、それは政治ですから、それぞれご意見があることはいいとは思いますけれども、デマとの断定は事実ではないので、発言の訂正を求めたいと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"あくつ副委員長","kind":"質問","question":"このビラについては、訂正しましたよね、共産党さん。訂正していますよね、それは訂正をしていますよ、手元にもありますけれども。訂正をしているということは、間違いを認めたということではないのですか。だから私は、発言を訂正をする必要もないし、そのつもりもありませんが、という考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"中塚委員","kind":"確認","question":"経過については、冷静に後で私もきちんと確認したいと思いますけれども。やはりデマだという断定は、事実でないと思いましたので、指摘をさせていただきました。事実関係については、後でしっかり確認をしたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227390?Template=document&Id=2040#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":75092,"voices":187}},{"id":"h28-20160224-14","meetingId":"h28-cm02","date":"2016年2月24日","dateIso":"2016-02-24","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時２７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","topics":[{"id":"topic-01","title":"国家戦略特区に関すること","agenda":"国家戦略特区に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"現在のところ、西大井広場と区民公園において区立の認可園の建設が、特区活用で区の方針として発表されておりますが、その先については何カ所の検討があるのでしょうか、１点伺います。この特区活用の具体化待ったなしかと思いますけれども、その点も伺います。","respondent":"柏原企画調整課長","answer":"その他につきましては、条件等々その他いろいろありますので、どこの場所がという具体的なところでは申し上げできる段階ではございませんけれども、幾つか候補を挙げて、それについて検討しているといった状況です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問したところで、何カ所の検討ということだと、幾つかということでしたけれども、何カ所の検討なのかというのをお伺いしたいと思います。今の現行計画、平成２９年の４月開設だったと思うのですけれども、そこら辺の心配はないのかもあわせてお伺いします。","respondent":"柏原企画調整課長","answer":"申し訳ございません、少し私の説明不足だったかもしれませんが、３月にずれ込んだというよりは、もともと区域会議は年度明け４月ぐらいを想定しながら準備を進めていて、平成２９年４月に向けてというところで動いていたものですから。","id":"exchange-002"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"１点だけ教えてください。国家戦略特区の話で来て、羽田空港跡地の、さっきいろいろ話が出たのですが、ここはアジアヘッドクォーターではなかったのですか。それで準備を進めてきて、国家戦略特区というと、要は、都市計画の中でアジアヘッドクォーターを使って様々に展開していくということとの整合性が、どこにあるのかなというのだけ教えてください。","respondent":"柏原企画調整課長","answer":"細かい部分の差異は若干あるようなのですけれども、国家戦略特区とアジアヘッドクォーターと、両方の特区の区域に入れる中で、国家戦略特区のほうの規制緩和を、選んだという言い方が正しいのかどうかわかりませんけれども。","id":"exchange-003"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"なぜこんなことを聞くかというと、私はここの羽田については、もともと最初のときは品川区も入っていたわけだから、知らないうちに外されてしまったというか、やはり意見は言うべきで、品川は今、観光にしても何にしても、それを必ず一緒に羽田空港、水辺でもいいのだけれども、舟運でもいいのだけれども、一緒にやりましょうというのを考えているわけではないですか。","respondent":"柏原企画調整課長","answer":"ご説明、前段したところに重なる部分はありますけれども、国家戦略特区のほうがやはりエリアとしては幅広くとっているというのがありますので、そういう意味ではやりやすいといいますか、幅をとったやり方ができるのですが。","id":"exchange-004"}]},{"id":"topic-02","title":"公有地・跡地活用に関すること","agenda":"公有地・跡地活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１番の品川第二寮ですけれども、日本ペイント近くの南品川にあるところですが、都営住宅に隣接している敷地だと思うのですけれども、今、一回社会福祉法人から申し出があったのだけれども辞退したということですが、現在に至るも売却先が未定となっている大きな理由は何なのかを伺います。","respondent":"柏原企画調整課長","answer":"恐らくその部分において、近郊というか近況の土地との関係のところがうまく調整できなかったのではないかと想像はできますけれども、細かい具体的な理由を聞いているわけではありませんので、恐らくその辺が支障になっているのではないかと思ってあります。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"今からでも、隣に都営住宅があるわけです、そことの隣接地なので、東京都に対して、取得してほしいと。都営住宅の増設にもなりますし、必要な公共施設等の複合施設などもできると思うのですけれども、やはり地元の自治体としましては、東京都に対して取得を求めて、そうした活用を求めるべきだと思うのですけれども、区の考えはいかがでしょうか。","respondent":"柏原企画調整課長","answer":"民間が買えないところを公でというところでありますけれども、民間が活用できませんので、公もそれに合わせて活用というのはなかなか難しい部分がありますので、ここは我々としても、周りの土地の状況とかというのは見ないといけないところですが、現在のところでは。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"改めて、区が都営住宅の区の移管を受けて、隣も取得して、区営住宅としてさらに増設することを検討すべき時期だと思うのですけれども、改めて伺います。","respondent":"柏原企画調整課長","answer":"１年、２年前ですか、お話をしたときには、移管に関しては都も難色を示したというところがありますので、現段階ではここをすぐに取得してというところでは、区としては考えていないといったところです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとごめんなさい、２番目の上大崎寮ですけれども、これは随意契約の相手方とする旨の通知があったということで、これをストレートにすぐ区に売るというふうになるまでワンクッションあるということで、回りくどいのだなと思いましたけれども、「関わる通知を待ち」ということがありますが、区から積極的に、ここは待っているのではなく、待機児童の深刻な問題もありますので。","respondent":"柏原企画調整課長","answer":"こちらにつきましては、国のほうもどういう法人と交渉しているかというのは公表できないところでありますので、そういう法人というところから、一般的な流れで言いますと、公の団体に照会をして、その次には福祉的な要素であるとか、準公的なところの法人等を受け付ける。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"上大崎寮に関しては、迅速な働きかけと丁寧な説明をお願いしたいと思います。それと、参議院会議等施設のほうは、通常の流れでいうと自治体の後、福祉的な要素というところでしたけれども、区としても、そうした福祉的な施設ができていくということは、この前の請願の中にも特養みたいな話もありました。ぜひ区としても後押しできるところがあれば、していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問","question":"１点、上大崎寮の部分でご質問します。通常、半年間ぐらいで通知が来るということで、今２月ですので、年度末、年度明けというところで、通常のものをすごく逸脱しているというところではないかと思うのですけれども、今後のスケジュールですとか、確定のものではなくて、通常どういった形でこういったケースを進めていかれるのかというところだけ教えていただけたらと思います。","respondent":"柏原企画調整課長","answer":"実際、随意契約の相手方としますといって契約の書類が来るのですが、その契約の書類が来てから、金額の部分につきましては何ヶ月という有効期限なのですが、さらに２年間の中で契約を結んでくださいと。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"今の横山委員にも関連するのですけれども、そうすると当然今回の、まだ予算書をよく見ていないのですけれども、今回には当然入れていないということと、それから、願わくば来年の４月には開設できればいいなと。まだ保育園とは決まっていないのかな。一応、この中では保育園という話を聞いているのですけれども、その辺のスケジュールを教えてください。","respondent":"柏原企画調整課長","answer":"仮に動き出したときに、解体の手続き、それからその後、あちらの現地をご覧いただいているかと思うのですが、あそこは擁壁が三方囲まれていますので、あと昔の水路が通っているというところがありますので、若干その設計であるとか工事に関しては。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"上大崎の件については、ぜひ積極的に区としても進めていっていただきたいと思います。品川第二寮のほうで、対象になるものとならないものがあるということでしたけれども、どういった基準があるのか。それと、今回の第二寮がそれに当たらない理由を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"すみません、対象というのは都営住宅の移管の件でよろしいですかね。平成１２年のときの都区の移管のときの合意といいますか、一連の中で、都営住宅で１００戸未満のものは、基本的には区に移管だという方針を都は出しています。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"すぐには無理だということでしたけれども、ぜひ区でも、移管も含めて検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-03","title":"羽田空港の機能強化に関すること","agenda":"羽田空港の機能強化に関すること","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"すみません、今、最後におっしゃっていただいたところで、そうすると、ミニオープンハウスが開かれるというのは、何か地域の方からの要望を受けてやるということになったのか、国交省からそこをピンポイントで選んでやるというふうになったのか、教えてください。","respondent":"三ツ橋環境課長","answer":"そのときは国交省から、一番影響が大きいであろうと思われる地域を対象にしておりまして、今回もそのことを国交省が考えて、今回ミニオープンハウスとなっております。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"先ほどのミニオープンハウスの日程をもう一度教えてください。書いてあるのかと思って聞き漏らしてしまったので、お願いします。","respondent":"三ツ橋環境課長","answer":"失礼いたしました。３月５日（土）が南大井文化センターで開催されまして、時間が１３時から１７時です。次の３月６日（日）ですが、こちらは品川保健センターで開催されまして、１３時から１７時です。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"先ほど、この下に書いてある主な意見等というところで、区の職員が聞き取ったものということでしたけれども、そこに「区の方針は？」と書いてあるのですが、これについてはどういった答えをしたのでしょうか。","respondent":"中村都市計画課長","answer":"これから、国交省では具体的な対応策等明らかにしていくというふうにしておりますけれども、それを踏まえて、区としてまた必要な対応について求めるかどうか、その辺を検討していくです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"本会議場でも第２フェーズの説明について質問が行われまして、それについて、十分とは言えないと答弁がありましたけれども、今のご回答だと、周知について十分ではないと考えているということでしょうか。もはや関与しないというような態度ですけれども、これで住民の不安や怒りに答える具体的な対策が示されたとは思っていませんが、区はどう考えているのか伺います。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、対応について十分ではないというところは、常に完全というところがないということで、国には常にこれからも求め続けていくという姿勢を区としては貫くべきと考えています。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"第２フェーズが終わった今こそ、品川区が反対表明していただきたいと思っているのですけれども、区はいつになったら反対表明するのでしょうか。","respondent":"中村都市計画課長","answer":"区がそういったことを求めた結果、そういう回答が得られたですけれども、ただ、まだその対応策について具体的に示されたわけではございませんので、区としては今後それを注視していくという態度です。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"この具体的な対応策が示されなかった場合は、区は反対するのでしょうか。","respondent":"中村都市計画課長","answer":"具体的な対応策の中身によりますので、反対あるいは賛成という具体的な回答は、今のところできませんけれども、ただ対応策も、先ほど申し上げましたけれども、これで万全ということはございませんので、引き続き国と協議を進めていくという形になろうかと思います。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ協議を続けていって、具体的な対応策を示されなければ、品川区として、一番被害を受ける自治体になると思いますので、反対の立場に立っていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"確認","question":"今の質疑の中で確認だけしたいのですけれども、例えば前の行革委員会で確認した記憶はないのだけれども、品川区が仮に航空機はうちの上空を通るなと、それを決めたところで、その権限が実際に及ぶのでしょうかの確認をお願いします。","respondent":"中村都市計画課長","answer":"国の見解はそういったところです。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"確認","question":"これを物理的に止めることはできないと思うのですが、いかがですか。","respondent":"中村都市計画課長","answer":"引き続き、区として可能な限りの協議を進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だからむしろ、今まさに課長がおっしゃったように、今ある様々な仕組みをフルに活用して、品川区の要望を伝えて、そして様々な解決策を具体的に導き出していくことのほうが、単純にいたずらに品川区が飛行機を止めろと言っても止められないのだから、より現実的で具体的な成果を出すことにつながると思うのです。","respondent":"中村都市計画課長","answer":"この周知の方法や説明会の方法などについて、まだ万全あるいは完全ではないという区の見解ではありますけれども、ただ、国としても現在、区の意見を聞いていただいているという姿勢でいていただいておりますので。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"そんな中で、先ほどご案内のあった３月５日と３月６日のミニオープンハウスということなのですけれども、これをミニと言っている理由というのは、会場が狭いとか、何かそういうことなのでしょうか。ミニと言っていることの理由というか、裏づけみたいなことをお伺いしたいのと、この周知ですね、今から２週間後ぐらいでしょうか。","respondent":"三ツ橋環境課長","answer":"それなので、ミニオープンという形になっておりまして、若干規模が小さくはなっておりまして、例えば国の説明の人員が若干少なかったり、あと対象となる部分の方も、先ほどのオープンハウスですと区全体を対象としておりますけれども、特にミニオープンですと。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうすると、あまり大々的に品川全土でみんなに来てもらうという趣旨ではないということなので、そういう目的別にやるということは理解できますので、そういう意味では目的に沿う形で、地域住民の方には回覧板でというふうにお話ありましたけれども、町会掲示板とか、いろいろな形で地域への周知というのはまたあり得ると思いますので、そこには一層力を入れていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問・要望","question":"今、国からの回答待ちということなのですけれども、この資料を見る限りはフェーズ１とフェーズ２の、フェーズ１で要望を受けた中で、騒音レベルというのが体感できないかということで、第２フェーズではそれが活かされているということだと思うのですが、またこの第２フェーズの主な意見等の中で、今まで出た意見とほぼ同じということで、区はそのように捉えているのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"説明のことで、今の教室型なのですけれども、再三品川区が教室型も要望しているということなのに、他区では行われているところがあるのですよね。それは品川区としては、一番影響が大きい自治体の一つなので、ゆゆしき事態ではないかと思うのですけれども、これは国が品川区の要望を聞いていないということになるのではないですか、いかがでしょうか。","respondent":"中村都市計画課長","answer":"ですので、規模の大小を問わず、引き続き教室型の説明会については求めてまいりたいと思います。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"その点はお願いします。そもそも第２フェーズの位置づけとして、最後に書いているのですけれども、フェーズ２として、対策や運用方法等と、皆様のご意見を伺いながら、環境影響に配慮した方策を策定します、とあるのですが、今までの質疑ですと、環境に配慮した方策ということでは不十分ですと、さらに、今後明らかにしていくと国が言っているので、さらに求めていくということだと思います。","respondent":"中村都市計画課長","answer":"ですので、これもなかなか難しいのかなというふうには考えております。模索ですけれども、この模索は、言葉としては委員ご指摘のように、あくまで具体的な対応策を示したということにはならないと思います。これは検討という言葉が、むしろ近いのかなと解釈をしております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の国の説明ですけれども、今度の新ルート計画で品川区内のＰＭ２.５をはじめ、大気汚染が現状よりどう変化するかという答えではなくて、全国ではこれだけの大気汚染物質排出量がありますよと。そういった経緯を、区のこれまでのお考えを照らしますと、今回の国の大気汚染についての説明は、完全に話のすり替えではないかと思うのですけれども、そう思いませんでしょうか、伺います。","respondent":"三ツ橋環境課長","answer":"区としても八潮で、委員がおっしゃられたように、ＰＭ２.５は実際に測っていることは測っておりますけれども、航空機からの影響のＰＭ２.５なのか、それとも通常の状態のＮＯｘからのＰＭ２.５なのか、そのような部分が。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここに関しても、航空機の影響でどういう変化が出るのかというのは、当然、国が新たなルートを設定するわけですから、示して然るべきだし、それを求めていく必要があると思いますけれども、国はこんな説明です。そこら辺を求める考えはあるのかどうか、合わせて伺います。","respondent":"三ツ橋環境課長","answer":"先ほどの大気の、国がすり替えという文言をおっしゃっていましたけれども、なかなか大気汚染のＰＭ２.５というものも、本当に難しい部分というのは、こちらとしても周知は十分わかっているところでございまして、データの分析というのも本当に必要に応じて、航空機からなのか。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"落下物と墜落なのですけれども、落下物は、国はわざわざ羽田空港では０件、成田空港では１０年間で１８件と書いていますけれども、わざわざ数字を記載しているのですが、これはあたかも羽田は今回で落下物は落ちませんよという、ごまかしの説明だと思うのですけれども、そういうふうに思いませんでしょうかというのが１つの質問です。区はどう思うかということですね。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"落下物については引き続き、可能性がゼロでないというところから努力は、０件であろうが何件であろうが引き続き行っていただくことについて変わりはございませんので、この辺は区からの要望に対しても。先ほどの大気汚染のデータですけれども、今までも大気汚染のデータにつきましては環境課、区のホームページ上で情報を開示しておりますので、引き続き情報公開してまいります。","id":"exchange-031"},{"speaker":"安藤委員","kind":"提案","question":"海から入って海に出ていくわけですから、海上ルートですね。私が伺ったのは、見過ごせない重大な数字だと思うのですが、いかがでしょうかと、そう思いませんかということをお伺いしたので、改めてこちらについてもお伺いします。冊子にも載っていますけれども、新飛行経路の午後の運用時間（１５時～１９時）は守られるのですかと率直に質問して、それが冊子に載っております。","respondent":"中村都市計画課長","answer":"しっかりとそれを求めていくことによって、国としても引き続きしっかりと対応してまいりますというふうに、区からもお願いをしている際に、そういったやりとりもあります。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"ですから私は、一旦飛び始めれば、いずれ広げますよという、広げることもありますよという余地を残した、非常につくり込まれた行政的な表現だと思うのですけれども、そういう回答だと思うのです。それとあわせて、区長が１月２３日（土）の大崎ニューシティの説明会に参加をされたということです。区長はなぜ参加をしたのでしょうか。どんな思いで参加したのでしょうか。それを伺いたいと思います。","respondent":"中村都市計画課長","answer":"オープンハウスでもそんな説明もございましたので、現在、区としてもその時間帯が守られると考えて、今後の協議を進めてまいりたいと考えています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそういった、感じていただいた区民の不安ですとか怒りも含めて、今後はさらにそれを踏まえた上で、１歩も２歩も前に進んだ対応をとっていただきたいと思います。先日、日曜日に、品川区民の住民団体の皆さんが計画撤回を求めるデモ行進がありました。ＮＨＫなどでも報道されました。現行計画撤回に向けて区民運動を起こすことを求めていきたいと考えています。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"お願いがあります。私は海沿いなので、そちらの話をすると、例えば品川駅へ４００ｍぐらいで来て、それから天王洲へ来てというと、一番うちに近いところなのだけれども、５０年ぐらい前は、私の子どものころは、小学校へ行っていた頃はしょっちゅう飛んでいて、それはよく肌で感じている一人なのだけれども、距離感というのかな、今はゼロになっているわけではないですか。これはぜひお願いしてほしいのです。","respondent":"三ツ橋環境課長","answer":"落下物につきましても、私どもも全然、はっきりどの程度のものなのかというのも知識的にもよくわかりませんので、実際に区として、国に対して要望はしてまいりたいと考えています。","id":"exchange-035"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"ぜひそれは、計画案が出てくるのかどうか、それが８月かどうかわかりませんが、その前にはぜひやっていただいて、区民の方々にも、町会長クラスにはいろいろご説明に上がったり、町会長会議、地域センター会議とか、いろいろ活動されていくというお話も聞いているので、そうすると、必ずそういう距離感、どこというのは出てくると思うので、ぜひそこら辺の話は進めていただければと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほどの質疑を聞いていて思ったのですけれども、航空機事故のリスクやら、落下物のリスクの話がありました。これを品川区に求めても、どうしようもない話だと私は思うのです。だけれども、先ほどの話を聞いていると、全部品川区にお願いする形があるので、それは違うだろうと。そういうふうにしていったほうがいいと思うのですが、改めてお願いですが、いかがですか。","respondent":"中村都市計画課長","answer":"今後、国から具体的な対応策が示されるに当たりまして、区としてはやはり最大限、国が品川区に対して対応をしていただくように、引き続き協議を進めてまいります。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"先ほど市街地上空を飛行機が飛ぶことは違法ではないというお話でしたけれども、違法でないと区は反対の表明というのはできないのでしょうか。制度上のお話をお聞きしたいと思います。","respondent":"中村都市計画課長","answer":"区としましては、違法ではないとか違法だというところとは、直接区の対応は関係ないと考えております。たとえこれが、違法であれば当然のことですけれども、合法だとしても、上げるべきときは意見として上げてまいります。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"今はまだ結論は出せないということでしたけれども、ぜひ、首相も地元の理解を得てルート変更も考えていくと言っておりますので、やる前から諦めずに、品川区がぜひ反対の立場に立っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで影響について、さっきとは違った観点でお伺いしたいのですが、まず、実際に具体的にどういう新ルートの下の施設が影響するのかというところで、一般質問で昨年の１２月と、先日の一般質問でも聞いたのですけれども、新ルートの下にある施設について伺ったのですが、地区ごとに数だけお答えいただいたのですけれども、具体的な施設名についても先日の一般質問で伺いましたが、答弁ありませんでした。","respondent":"三ツ橋環境課長、藤田都市環境部長","answer":"実際に答弁のときには、大井地区５６件、八潮地区１４件、品川地区３１件と申しております。これにつきましては答弁のとおり、地区にある一定規模以上の施設として挙げているものです。そういう話の中で、地区としての施設の数を上げるときに、大井地区全体とか品川地区全体として拾っておりますので、影響の範囲がどこまで広がるかというのが検証できている状態でもございませんので。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"ただ、出されている数というのは、それと関係ない数だったということなのですかね。そこら辺がわからなかったので、お伺いしたいのが１点あります。品川区は、ここでいう今回の新ルートで最も大きな被害を受ける、安倍首相が言うところのまさに地元に当たると思うのですけれども、いかがでしょうか。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"この地区ごとの部分ですけれども、今部長が答弁したように、今後国土交通省から明確なルートなどが示された場合に、正確なものとなっていくと考えられますので、今の大井地区５６件、八潮地区１４件、品川地区３１件というのは。今現在飛んでいなかったところに、新たに飛行経路となるということに関しましては、品川区は当事者であり地元であるという認識です。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは区に求めたいのですが、委員長、いかがでしょうかというのが１つです。それと、地元ということでした。安倍首相が言っているのが、地元の理解を得てということなのですけれども、この施政方針と照らして、地元である品川区が理解を示さない限り、計画は進まないと考えてよろしいのかどうか、伺います。","respondent":"中塚委員長、中村都市計画課長","answer":"初めに、資料の取扱いについては、正副で調整したいと思います。品川区としましては、区の理解をもって進めていただくように、国に引き続き求めていく所存です。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"地元の意向を無視して計画が強行されるということがないように、さらに努力をしていただきたいと思います。これまでの経緯なのですけれども、今回の新ルートというのは、かなりの方針転換だと思うのです。伺いたいのは、これまで品川区としては騒音対策、羽田問題に対して、どのような努力を重ねて、何を成果として上げてきたのか、そうした区の認識を伺いたいと思います。","respondent":"中村都市計画課長","answer":"対応策についてですが、これは具体的にこれから第２フェーズの後、夏までにですので、これについてはまだ引き続き継続中です。","id":"exchange-043"},{"speaker":"安藤委員","kind":"提案","question":"すみません、私が伺ったのは、今回の新ルートの提案というのはこれまで、先ほど紹介しましたけれども、品川区も大きな影響を受けるということで、三者協の中で不文律のルールをつくったり、モノレールより海側を通るようにしなさいねと言って実現したり、あるいは沖合移転などを実現させたという、それはやはり、市街地上空のルートというのが本当に大変な大きな影響があるということだったから。","respondent":"中村都市計画課長","answer":"この努力は努力として、成果として、区の成果であるというふうには考えておりますけれども、ただ、今回新たな飛行経路、まさに新たなというところがつくところにおきましては、今までの努力もあるけれども、今後また新たに国から示された案について、国から示されたわけですので。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"一般質問で私たちが聞きましたけれども、人口密集地を低空で飛ぶこの新飛行ルートは、海外を含めてほかに例があるのですかと聞きました。そうしましたら、品川区は、ロンドンのヒースロー空港や伊丹空港などを挙げましたけれども、伺いたいのは、品川および東京２３区、都心の密集地を飛ぶ空港というのは、区が答弁された様々な空港の中に、ほかにあるのでしょうか、伺います。","respondent":"三ツ橋環境課長","answer":"委員が言われました人口密集地を低空で飛ぶ飛行ルートということに関しましては、国の資料によりますと、ロンドンのヒースロー空港、ニューヨークのラガーディア空港、大阪伊丹空港、福岡空港などを示しております。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"国の資料で書いていますが、私が伺ったのは区の認識なのです。東京２３区における、区の認識を改めて伺います。１,２００万人の方が、これだけの限られた土地に密集していると、こういう空港というのはほかにあるのかということを聞いたので、区としてはどのように思っているのか、伺います。","respondent":"三ツ橋環境課長","answer":"人口密集というものが、どの程度のものを人口密集と言うのか、はっきりなかなか申し上げられにくいと思いますけれども、国の資料によりますと、人口密集地域という部分に関しましては、ロンドンであったり、ニューヨークであったり、また伊丹であったり。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"これはつまり、人口密集と一言で言えばたくさんありますけれども、今回の新ルートの計画、飛ぶ地域というのは、今回の例というのは、では世界で一番最大の人口密集地を飛ぶ計画ということなのでしょうか。様々あります、ヒースローや伊丹などありますが、挙げられた例の中で比べても、一番密集している人口地を飛ぶという計画でよろしいのでしょうか。","respondent":"中村都市計画課長","answer":"密集の度合いにつきましては、例えば他都市におきまして、では密集していなければいいのかといったことにもなるかと思いますので、密集そのものの度合いで経路の検討の結論が変わってくるということはございませんので、回答は差し控えるべきと考えております。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほかの例と比べて、今回の新ルートがどういうルートなのかということを知る上でも、ぜひ示していただきたいのですが、改めて、今回の新ルートは国が示している空港の中で、一番人口密集地を飛ぶという計画でよろしいのでしょうか、伺います。","respondent":"中村都市計画課長","answer":"例えば東京と大阪といった大都市単位で人口密度というのは公表されているものがありますけれども、まだ品川区内では具体的に、経路案として示されているもので、具体的にこの位置というふうに示されているものではございませんので、そういった意味からしますと。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどから、今回のルートは確定していないものなのでという答弁もありますが、夏までに決定すると言って、しかも第２フェーズの中で品川区の地図まで示されて、それでまだここを通るかどうかわからない、だからというのは、私は無責任なのではないかと思いますので、では逆に言うと国は、変更するかもわからない、そこではないかもしれないけれども、とりあえず線を引きましたというような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどルート下の施設を地区ごとに出したときに、一定規模以上の施設を挙げたということですけれども、その一定規模以上というのはどういう基準で決めたのか。あるいは、それと影響がどこまであるかわからないという話でしたけれども、今回出した数字としては、ルートのどのぐらいの幅で出したのか、教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"一定規模以上といいますのは、例えば病院をカウントするとしたら、どのくらいの規模の病院をカウントするのかとか、そういう具体的なものを考えましたところ、一定規模以上という文言を申しております。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"一定規模以上ということでしたけれども、何m2以上とか、そういったことも決めていると思うので、そこをお伺いしたいと思います。","respondent":"三ツ橋環境課長","answer":"m2数といいますか、今言いましたように、例えば病院でありますと病床数など、そういう部分に関係してきますので、m2数という具体的なものではない場合もあります。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々な施設がありますので、いろいろ基準があるとは思いますけれども、資料をほかの委員が求めましたので、そこにもその基準がわかりやすくなるように資料を出していただきたいと思います。請願が５つありますけれども、全て住民の生活が脅かされる新ルート、市街地ルートはやめてほしいという願いだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"沢田委員","kind":"質問・要望","question":"それからまた、この騒音対策を求める意見書の中にもありますけれども、こういった件に対して、意見書のとおり、そういった答えはまだ何も出ていない部分もあると思いますので、そういったことも含めて、現在の段階では請願に対しては、継続で進めていきたいという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"たけうち委員","kind":"質問・要望","question":"我が会派も継続していただきたいと思います。それに対して、この夏に向けて、対応策等を国交省が提示してくるという動きをしっかりと注視した中で、結論を出していかなければいけない中で、今の段階で中止もしくは撤回ということについて判断をするというのは、非常に難しいということで、継続をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"結論を出すということでお願いしたいのですが、態度としては、やはりこの時点でしっかりと採択をして、現行計画の撤回を区として求めていくべきだと思います。大気汚染の問題もあります。区民生活に広範囲にわたり重大で深刻な影響を及ぼす計画は到底認められず、中止すべきです。ましてや、まともな説明がないままに進めているのも論外ですということで、採択を私たちは主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"大倉委員","kind":"質問・要望","question":"我が会派としては、継続でお願いしたいと思います。先ほど来もお話があったとおり、区議会として意見書を出し、その意見書の中でも様々求めていく中で、説明会がフェーズ１・２と、この後もミニというので開かれていく中でしっかりと意見を集めていただき、これからの国の動きをしっかり見ていく中で検討していくべきだと考えますので、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]},{"id":"topic-04","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"まとめの方向については、正副の案に賛成です。国に対して３ヶ月ぐらいで回答しなさいということで、いつも情報が来るのですけれども、国に対して、適切な時期に公有地情報を出していくということを求めることが私は必要だと思いますし、都有地に関しては、国のようなルールがあまりないのかなと思っていますので、さらにそうした適切な時期に公有地情報を出してほしいという要請が必要ではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"伊藤委員","kind":"意見","question":"私たちとしては、せっかく正副がまとめてくださいましたので、これをもとに進めていっていただくことをお願いしておきます。それだけです。殊さらここに来て意見を追加することはしませんので、ぜひまとめてください、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/700324?Template=document&Id=6002#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":45129,"voices":134}},{"id":"h28-20160225-18","meetingId":"h28-cm02","date":"2016年2月25日","dateIso":"2016-02-25","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ３時０１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/969591?Template=document&Id=6488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":3783,"voices":13}},{"id":"h28-20160301-3","meetingId":"h28-c-budget","date":"2016年3月1日","dateIso":"2016-03-01","committee":"予算特別委員会","time":"午前１０時００分～午後６時３８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を177件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"つる副委員長","kind":"質問・要望","question":"会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"提案","question":"私ども、自民党・子ども未来会派、それぞれこの予算特別委員会、高い志を持って、しっかりと課題は課題で指摘し、そして本当に未来に向けた要望・提案、区長の言うチャレンジというものにすごく共感を持ちながら質疑をしていきたいと思います。私は５７ページのシティプロモーションサミットのところ、５８ページ、文化スポーツ振興基金積立て、時間があれば宝くじ等、伺ってまいりたいと思います。","respondent":"柏原企画調整課長、秋山財政課長","answer":"そうした中で、地方創生の交付金を活用しながらシティプロモーションサミット、品川区もシティプロモーションを押し出していますので、共催という形で進めていこうという形になったというものです。文化スポーツ振興基金のお問い合わせです。オリンピック・パラリンピックが２０２０年にあるというのは契機ということで、目的のところはご説明をさせていただいておるところであります。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"その辺の、単に積み立てる中で、寄附金の取扱い、その辺の、何というのですか、募集の仕方も考えられるのではないかと思いますので、それを一つ考え方を伺いたいです。そんなところでは、連携ができる仕組みができるのではないか、あるいは今後、オリンピック・パラリンピックに向けて国際大会の誘致という大きな目標も定められるのではないかと思いますので、それの仕組みと今後の展開を教えてください。","respondent":"中元広報広聴課長、秋山財政課長、江部総務課長、小川オリンピック・パラリンピック準備課長","answer":"そのときにはパネリストとして墨田区の副区長が参加したりなどということで、都内の自治体は、品川区を含めて、現在。ただ、基金の名称にもかかってくるのですが、オリンピック・パラリンピックということで寄附をいただくというのは。現在のＣＳＲ推進協議会の６２社の企業の方に参加いただいているところでございまして、今後、企業からの寄附のあり方。国際大会の誘致は当然、考えているところでございまして、そういったところでも折あるごとに。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"提案","question":"これまでの経緯を見ている中で、非常におもしろいアイデアや企画が、区が助成することで、区が課題を提示するのと同時に、区民提案というのは非常にアイデアに豊富で、中身もすばらしいものがあるかと思います。東京都がアーツカウンシル東京という中で、それぞれ区民の提案型に対して、２分の１や３分の１等、助成する。その辺のことを伺えればと思います。その点で考えを伺えればと思います。","respondent":"秋山財政課長","answer":"発信とか、その辺につきましては、オリンピックにも文化プログラムというのは求められていますので、それについて十分２０２０年までの間にオリンピック・パラリンピック準備課等を中心にしてやっていきたいと考えているものです。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問","question":"それと、先ほどの充当事業で、企画として伺えればと思います。区民芸術祭が本当に総合的な冠の中で次々と芽を出すような仕組み、この辺の可能性は十分にあると思われますし、やはり文化スポーツが持つ力の中で、日頃の高齢者福祉の点だとか青少年育成あるいは外国人の交流、あるいはそういう形で新たな引き金、呼び水になるような気がしますので、その辺で文化の観点から伺えればと思います。","respondent":"間部文化観光課長","answer":"本基金を使いました映画祭やアートへの展開ですけれども、積極的に考えていきたいと思います。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、３６ページ、個人番号カード交付事務費補助金、５５ページ、ネットワーク・セキュリティ経費、３８ページ、生活困窮者支援費補助金の中の自立支援事業について、３点にわたってお伺いさせていただきたいと思います。マイナンバーが今現在、カードの普及を進めているところですが、なかなか広がっていかない。そこで確認をさせていただきたいと思います。","respondent":"井浦戸籍住民課長","answer":"こちらの戻りの対応につきましては、臨時交付窓口で、１日２００件ほどお客様が平均でいらっしゃいまして、順次交付しているという状況です。実績としましては、区の窓口で１万６２８件、交付済みです。２点目の、マイナンバーの申請数です。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"このマイナンバーカードの申請数に対して、４２３件という、非常にまだ少ない数であるかと思います。できましたら、このことをホームページまたは区報などで、品川区はこれぐらいの申請があって、これぐらいに申請した人はいつぐらいにこのマイナンバーカードが受け取れますよというようなことを周知していただきたいと思いますが、いかがでしょうか。","respondent":"井浦戸籍住民課長","answer":"通知カードを受け取っていない区民の方への対応ですが、区でお預かりしている通知カードが全部で１万６,３８３件ありますが、順次、整理いたしまして、おはがきでご案内をしています。ホームページ、広報誌等々でご案内して、受け取りにおいでいただく。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"区民にわかりやすいように、具体的に、ホームページ、また区報を使って、いつぐらいには届きますということをご案内していただきたいと思います。次に、ネットワーク・セキュリティにつきまして確認します。そこがまた、マイナンバーカード申請につながらないところにもつながっているのですけれども、品川区としての対策をお伺いします。","respondent":"仁平情報推進課長","answer":"さらにマイナンバーの導入にあたりまして、システムの強化施策以外に職員のほうの教育も必要ということで、実際、平成２７年度に入りまして、まず職員向けの制度説明会、１７０人程度を実施させていただきました。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"大変わかりやすくありがとうございました。ネットワークの部分以外の職員研修も含めてのご回答をいただき、これは安全対策をしっかりとれているという確認をとらせていただきました。そして３点目、生活困窮者支援補助金についてお伺いいたします。この中の自立支援事業の内容をお聞かせいただきたいと思います。","respondent":"伊東生活福祉課長","answer":"ただいまご質問のところですけれども、こちらの自立支援事業につきましては、生活保護受給者に対する就労意欲喚起事業、就職レベルアップ事業と金銭管理支援事業ということの自立支援事業の部分が財源更正ということで、こちらのほうになってあります。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"昨年の４月に暮らし・しごと応援センターができて、間もなく１年弱となります。多くの方がご利用いただいておりまして、私もご相談者の方をつなげておりますが、簡単にこの利用状況と、またこの中でどこまで対応いただいているのか、例えばここでアウトリーチが可能なのか、そしてご利用者数に対して職員数が足りているのかどうかということも含めて確認させていただきたいと思います。","respondent":"伊東生活福祉課長","answer":"ただ、１日平均にしますと５.５人程度という形になりますので、何とか体制上やれるのかと考えています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"周知がされて、大変ご相談のしやすいところが区にあるということは、とても安心なところであります。ニーズが増えてくる中で、きめ細やかな対応をしていただく中でも、職員の配置もまたご検討いただきたいと思っているところもありますので、今後ともどうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"増の要因を教えていただきたい。これが２点目です。地方消費税の交付金のほうも伺いますが、当初予算が９２億円、前年度比で２５億円の増でした。補正で８億円増で、合計１００億円となっていますけれども、消費税は社会保障の財源となっていますけれども、この１００億円のうちどのぐらいが社会保障に使われてきたのか教えてください。","respondent":"黒田税務課長、秋山財政課長","answer":"増の要因ですが、当初予算編成時につきましては、平成２６年１月１日から平成２７年１月１日のいわゆる賦課期日現在の人口増が３,３１６名で、そのうち生産年齢人口が３２３名ということで。地方消費税の交付金のご質問です。今回、８億円ということで、この要因につきましては消費の伸びであるとかというところかと考えております。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"消費税もあわせて耐えがたい重税になっていると思うのですが、まず区の認識をお伺いします。消費税のところなのですが、１.７％のところで、平成２７年度の予算書では、地方消費税のところが３７億９,０００万円を使うのだと書いてありましたけれども、ここはこれ以上使ってはいけないのですか。何か制約があるのかどうか、１００億円の枠があるので、十分使っていただきたいのですが、いかがでしょうか。","respondent":"黒田税務課長、秋山財政課長","answer":"税収増は区民の負担増ではないかというお尋ねですが、先ほどご答弁申し上げたとおり、納税義務者の方が増えたということは、所得を得た方が増えたですので、税収増が区民の負担が増えたということではございません。それの１０倍以上のお金を、区としては一般財源も含めて使っているですので、ここで地方消費税交付金が１００億円あったから、それをどうこうということではなくて、これは一般財源として入るものですから。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もっともっと現状よりもここが使えるのだったら使っていただきたいという思いで質問しているので、そこを答えていただきたいのと、あと納税義務者が増えているといったところにおいては、全体のところなのですけれども、ここから税金のところの階層などで、区民の生活実態というのは区は受け止めているのでしょうか。先ほどの、納税義務者の様子がどのぐらいわかるのかということとあわせてお伺いします。","respondent":"黒田税務課長、秋山財政課長","answer":"区民の実態をですが、平成２７年度の課税状況を見ましても、いわゆる所得の階層の分布につきましては大幅な変化はございませんので、国の統計等を見ますと就業者数は増えている、給与も増えているというふうな状況にありますので。それ以外のものについては一般財源ということで区として使っていくです。４１億円につきましては、４１億円だけでは当然できませんので、５３０億円を区としては社会保障で使っているです。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"確認","question":"消費税、このところ本当に１０％も言われていますが、国民の中で本当に低所得者の人ほど負担が大きくなりますし、この消費税を実行したら、景気の底が抜けている現在がもっとひどい状況になってしまうといった意味では、絶対に１０％増税は許せないと私たちは思っていますけれども、消費税の財源、社会保障の充実のためにぜひぜひ使っていって。","respondent":"秋山財政課長","answer":"それで、もちろん１００億円を全部社会保障に使っていると申し上げてもいいのですが、一般財源というものは、何々に充てたということではなくて、一般的に使われる財源ということになっていますから、４１億円以外は一般財源ですので。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"提案","question":"「路頭に迷ってしまう」、「何とかしてほしい」こういった声がたくさん届いていますが、なぜ保育園の増設にもっとお金を使えないのか。給食費の補助なども出して、もっと負担を軽減してほしい。やれることはたくさんあると思うのですけれども、いかがでしょうか。区でできる社会保障の充実、生活支援のために、区民の税金を積極的に使うべきであると思いますが、いかがでしょうか。","respondent":"秋山財政課長","answer":"地方消費税の社会保障分というのは財源の内訳の話でございまして、何度もお話をさせていただいているように、社会保障にはそれなりの金額を使わせていただいているというところで、例えば３７億９,０００万円の内訳にしても、障害者福祉費に７億円であるとか。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"社会保障にお金を充てているのは当然であって、今日の私の質問の趣旨は、区民の生活が困難な中で、消費税なども本当に低所得者の人ほど負担が大きくなっている。このための緊急の対策のために、こうやって豊かな財源になっている、ここを緊急でぜひ使ってほしい。これが今日の質問の大きなところなので、ここにちょっと少しも答えていただけていないので、ぜひお願いします。","respondent":"中山企画部長","answer":"後半のほうのご質問は、社会福祉の充実にしっかりと施策をエネルギーを割くべきではないかですので、地方消費税交付金の財源の使い方云々ということよりも、先ほど申し上げた一般財源の投入も含めて、しっかりと福祉の充実は、今年度予算の補正。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"私からは、５５ページの情報セキュリティ強化対策費、関連して３６ページの国庫補助金、４８ページの、ふるさと納税寄附金について、７７ページの公園管理費、公園新設改良費について、時間がありましたら６３ページの、ねたきり高齢者等福祉費更正減額について伺います。５５ページの情報セキュリティ強化対策費について伺います。先ほども新妻委員からありましたが、重ならないように質問いたします。","respondent":"仁平情報推進課長","answer":"こちらのほう、品川区も、それぞれに１台ずつパソコンという運用はなかなか難しいものがありますので、一部のところで、ちょっとネットワーク上、共有している部分があります。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"今ちょっとお答えいただいた中で、モデルが国からということだったのですけれども、国からモデルというのは幾つか出ていたのでしょうか。といいますのは、先ほども、３６ページの国庫補助金の情報セキュリティ強化対策補助金では３,０００万円がつけられているのですけれども、その関係について伺いたいと思います。","respondent":"仁平情報推進課長","answer":"今回、補助金との関係ですが、国のほうはあくまで一時的な構築経費ということでの基準になっておりまして、団体によりまして規模が違いますので、国が想定した、例えば品川区ですと３７万人ほど人口があるわけなのですが、ここの人口に対して、国が決めた基準額がございまして。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"今後はマイナンバー制度も始まり、さらにサイバー攻撃に対するセキュリティ強化が求められますので、しっかりと対策をお願いいたします。次に、４８ページの一般寄附金のふるさと納税寄附金について伺います。この金額の内訳のことについて伺いたいのですけれども、何名の方からふるさと納税を受けたのか、また差し支えなければどのようなコースが選ばれたのか伺いたいと思います。","respondent":"黒田税務課長","answer":"寄附の内訳ですが、一番少額の方が５,０００円で、一番高額な方で１７万円を超えるという金額がございまして、その中で、いわゆる返礼品ですが、はがきが１件、あと、しながわみやげにつきましては、Ａコース、Ｂコース、Ｃコース、それぞれ１件ずつの返礼を送っているものです。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"その６件についてですけれども、いつ頃入金されたのかと思いまして、聞きたいと思います。というのは、昨年の１２月２４日にふるさと納税に関するホームページの更新が行われたと思うのですけれども、その影響もあったのか伺いたいと思います。","respondent":"黒田税務課長","answer":"そのうちの１２月２４日以降ですと１件ですが、この寄付が一番金額が大きかったですので、ホームページを見ていただいた方も、多少といいますか、かなり効果はあったのではないかと思っているところです。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"次に７７ページの公園管理費、そして公園新設改良費について伺いたいと思います。初めに公園児童遊園維持管理費に対する寄附金の収入についてですけれども、この寄附金は限定寄附金なのでしょうか。この寄附金はどのように使われたのか伺いたいと思います。あわせて、しながわ水族館運営費の諸収入ですが、どういった収入なのか伺いたいと思います。","respondent":"多並公園課長","answer":"水族館のほうの収入ですけれども、多言語化対応のために、今年度、デジタルサイネージ等の整備を進めているところですけれども、その補助金が、公益財団法人の東京観光財団の区市町村観光インフラ整備支援補助金という補助金がございまして、これが夏頃やっと示されまして。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問・要望","question":"今、その観光財団からの補助を受けているものがほかにあったら教えていただきたいと思います。こうした補助で活用できるものが品川区にありましたら教えていただきたい、今後についてです。","respondent":"間部文化観光課長","answer":"来年度以降につきましては、ほかに使えるのが、無料のＷｉ－Ｆｉの設備ですとか、例えばクレジットカードの決済だとかムスリム旅行者の関係ですとか、あと案内看板ですとか、そのようなメニューがありますので、現在。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"わかりました。次に、公園新設改良費について伺います。特定財源のその他の欄に４億円減額になっておりますが、その内容について伺います。そして、西大井広場公園改修工事についてですけれども、約１億２０６万円減額になっておりますが、その理由についても伺いたいと思います。","respondent":"秋山財政課長、多並公園課長","answer":"これにつきましては、区民公園のプールの工事が、繰越明許費ということでご説明させていただきましたけれど、平成２８年度に移りましたので、それに充てていた財源の基金繰入金が今年度要らないということで。その中で土壌調査を行ったところ、基準値を超える鉛が発見されたということで、ここにありますような、今年度予定していた工事は中止し、今回、この内容ということで減額、その工事費全て１億２００万円余というのが。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"最後に、現在そのことで特区制度を活用して西大井広場公園に保育園をつくるということでありますけれども、影響は出てくるのでしょうか。例えば工期が遅れるとか、またそういった原因で取消しになったりすることはないのか、最後に伺いたいと思います。","respondent":"多並公園課長","answer":"今のお話ですけれども、特区の関係で保育園を設置する計画ということで、保育部門と連携し、民間事業者がどれぐらいで工事できるかというのを全体的に把握して、今回、我々のやる土壌改良工事もその中で検討した結果、間に合うということで。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"３６ページ、児童保育費、３８ページ、子ども・子育て関係、４２ページから４５ページ、保育園関係、４８ページ、公園整備指定寄附金、５５ページ、基金積立金追加、５７ページ、シティプロモーション、６５ページ、わっくわくランドしながわ、８１ページ、義務教育施設整備基金追加についてお伺いします。","respondent":"竹田保育課長","answer":"そのほか、その３つ下、区内私立保育園経費ほか１１事業については財源更正、その下の保育園経費ほか７事業につきましても延長保育や一時保育等の財源更正です。その４つ下、待機児童解消区市町村支援事業補助金の区内私立保育園経費につきましては、新規開設の増加の分です。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"よくわかるようでわからない説明でしたけれども、とにかく、要するに名前のところで事業名称が載っているけれども、いわゆる説明のところで全てが区内私立保育園経費で一緒くたにして、中身がさっぱりわからない説明になっているのですけれども、こういういわゆる表記の仕方で、予算書の責任を持つ財政課はこれでいいと思っているのでしょうか。","respondent":"秋山財政課長","answer":"歳入につきましては、それぞれの項目によって、出てくるもとというか補助金が、それぞれの要綱で定められておりますので、何の補助金でどの仕事を行っているかというのを明らかにするというのが一つの目的ですので、今回、国の制度変更にかわりまして。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"課長、私は、先の一般質問でも予算の見える化についてどう考えているのだという一般質問をさせていただいた人間としては、やはりこの辺はよく説明していただいて、わかりやすくしていくのが流れだと思っているのですけれども、その辺について改めて答弁していただけますか。","respondent":"秋山財政課長","answer":"ですので、まずは何をもとにどういう事業をやっているのかというのを正確にあらわすというのがまず最初だろうとは考えてあります。ただ、わかりやすさというのは、これからもずっと、説明のしやすさですとか、そういうところは追求していかなければいけないと考えています。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"よろしくお願いします。予算の見える化。次に基金関係なのですけれど、４８ページのところで公園整備指定寄附で、公共施設整備基金積立金に１億１,０００万円余を充てるとなっていますが、先ほども、具体的にどういう目的で寄附されたのでしょうか。そして、とりあえず基金に積み立てたのでしょうか。今後どういうふうに使っていくのか、考え方と見通しについて改めてお伺いします。","respondent":"多並公園課長、秋山財政課長","answer":"指定寄附についてお答えします。この経緯ですが、実は、寄附された方は現時点ではお亡くなりになっている方のご寄附という形です。今回、公共施設整備基金というところで入れさせていただいたのは、公園に使っていただきたいというご意思がございましたので、公共整備基金から公園に使うということで入れているものでございまして、この金額につきましては。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"今までにもこういう形で、土地も含めて現金という形で寄附があったと思うのですけれども、その辺の考え方というのはしっかりと計画的にしているのですかという質問と、５５ページに、公共施設整備基金には、先ほどの寄附金が入っているのでしょうか。あわせて、義務教育施設整備基金積立金の追加分はわずかに５１３万円で、この考え方についてもお伺いします。","respondent":"秋山財政課長","answer":"財調基金につきましては、基金につきましては税収が多いときに積んで、少なくなったときに充てるというのは基本的な考えですので、その分については財調の基金のほうに今回、一般財源分として２２億円ほど積み立てているというものです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"うーんと言うしかないですが、基金に関して考え方が変わったのですか、一貫しているものがないのかと、かみ合わないですけれど。義務教育、基金も五百十何万円。これは、学校に関して改築等いろいろ目的があるにもかかわらず、この金額でいいのでしょうかという思いがあるので、改めてそこを答弁ください。すばらしいですね。「わ！これはいかがなものだと、無駄にならないのか、その辺についてお伺いします。","respondent":"中元広報広聴課長、秋山財政課長","answer":"できましたら、参加者の方にお持ち帰りいただきまして、またおうちでも繰り返しお使いいただければということで考えてあります。それで、財調基金につきましては、やはり一般財源として使えるということでありますし、２３区を見ても財調基金に比較的多めに積んでいるというところもありますので、そういう意味からして。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"わかりました。それで、コースターにいきますが、コップのあれのためにコースターというのはあるわけです。それを何回もという発想がすばらしいです。すばらしい。自分の箸を持ちましょう。そこまでやってきた区でもあるのにかかわらず、コースターは再利用と言うけれども、その辺について、環境課長が今いらっしゃるけれど、環境課としてはどういう考えがあるのでしょうか。","respondent":"三ツ橋環境課長","answer":"委員ご指摘のように、「わ！しながわ」シティプロモーションのコースターにつきましては末永くですけれども、また今後は、国産間伐材の使用のことを検討するなどを含め、環境面からもサポートしていきたいと考えています。","id":"exchange-032"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"マイナンバーの利用によって、税、年金、雇用保険などの行政手続に必要だった添付書類等々が削除され、手続の利便性が高まると思いますけれども、ここで質問なのですけれども、個人番号カード交付の予約状況、そしてカード申請の予約、それと品川区マイナンバーのコールセンターが今、設置されておると思うのですけれども、コールセンターはいつまで設置していくお考えなのでしょうか。","respondent":"井浦戸籍住民課長","answer":"１点目の、マイナンバーの予約状況です。１月２５日から予約を開始いたしまして、現在までで６１２件の予約を頂戴しております。ちなみに３６９件につきまして交付済みという状況です。続きましてカードの申請状況ですが、２万９,０５４件です。３点目のコールセンターです。","id":"exchange-033"},{"speaker":"高橋（伸）委員","kind":"質問","question":"コールセンターは、本年の３月末日、今月の末で終了ということですけれども、コールセンターは、月、日にどれぐらいの問い合わせがあるのでしょうか、その辺をお聞かせください。","respondent":"井浦戸籍住民課長","answer":"コールセンターにつきましては、９月１日から開設してございまして、延べ２万５,８００件を受けてあります。２月につきましては、１日平均２９４件という数字です。１時間当たり３６.７件という実績です。","id":"exchange-034"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"マイナンバー制度は非常にいい制度だと思うのですけれども、反面、安全管理、セキュリティの問題もあると思うのですけれども、個人情報の漏えい等が懸念されております。企業全体でマイナンバーを取り組んでいるということは、大企業がそういった取組み、１００名以上の会社では国がガイドラインを公開して求めている管理体制になっていますけれども、マイナンバー制度、管理体制をとらなければならない。","respondent":"井浦戸籍住民課長","answer":"ちなみに、国のコールセンターに１日２,０００件から３,０００件、事業者の方からお問い合わせが寄せられており、国で丁寧に対応しているということも聞いてあります。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"零細企業にとっては、これは非常に大変な問題だと思うのです。この情報を区の機関で零細企業に対して、いろいろもっとセミナーとか、そういうことを、いろんな発信をしていただきたいと私は思っているのですけれども、再度改めて、もう一回、区の対応、これからの零細企業に対しての対応をお聞かせいただければと思います。","respondent":"井浦戸籍住民課長","answer":"零細企業の皆様方には国のホームページ等でもガイドラインということで、物理的なセキュリティ体制、また、職員の取扱いの規則の細目の策定という形でご案内していますが、さまざまな産業関係に関する私どもの支援の中で、セミナーですとか、あるいは税務署と連携いたしまして。","id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういったところを、もっと品川区が情報を発信していただいて、青色申告とか、いろんな団体がありますけれども、そういったところで連携して、いま一度、もう一回、そういったセミナーとか、区と協働、共催していただき、やっていただきたいと思いますけれども、その辺のこと、セミナー等々のお考えはあるのかどうか、お聞かせいただきたいと思います。","respondent":"井浦戸籍住民課長","answer":"青色申告会の場をお借りいたしまして、マイナンバーについての説明も区として行ったところです。引き続き、しっかりと周知を進めていきたいと考えています。","id":"exchange-037"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ周知を徹底してやっていただきたいと思います。それと、これは今度コンビニで、住民票の写し等の交付がスタートが、予定としては今年の９月からサービス開始予定となっておりますけれども、その辺について開始予定となっておりますので、その辺のところ、今、状況がどういうふうになっているのかお聞かせいただきたいと思います。","respondent":"井浦戸籍住民課長","answer":"コンビニ交付につきましては、９月２０日施行予定という形で固めてございまして、区内店舗二百三十数店、または全国４,７００店で、朝の６時半から２３時まで年中無休で行政サービスを受けられるというような仕組みを導入するということで準備しています。","id":"exchange-038"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これは品川区内のコンビニが、今、２３２店あると思うのですけれども、この辺のところはこれから区としては連携を当然していると思うのですけれども、実際、開始が入って納入されたところで、パトロールとか、そういう連携体制というのは当然、構築していくのだと思うのですけれども、その辺のところの対応をお聞かせいただければと思います。","respondent":"井浦戸籍住民課長","answer":"コンビニ交付につきましては、セキュリティ対策といたしまして、専用回線を使用する。あるいは店員の方が直接タッチしないで、自動交付機で交付を受ける。交付された用紙についてはさまざまな技術的な偽造防止措置が講じられているという中で安全を講じてまいります。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も過去３回のものを調べてみましたけれども、そのパンフレットや説明書きの中には共催と書いてあるところは一つもなくて、先ほどありました２０１３年、尼崎、２０１４年、相模原、２０１５年に弘前と、これは主催ということでしか載っていないのですが、今回あえて共催という形をとったということについて、私は非常に重たいと思うのですが、ここについてご所見を伺いたいと思います。","respondent":"中元広報広聴課長","answer":"福井県坂井市につきましても、これまでサミット自体、共催はとっていないとしましても、前回、パネルディスカッションのパネリストに市長がかかわるなど、深くかかわったところが次を開催するみたいな流れもあるやに聞いてありますので。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先日、一般質問で、フィルムコミッション的機能の強化ということも申し上げましたけれども、今回はシティプロモーションにかかわる部署だけがこれにかかわるのか、そうではなくて文化観光も含めてこのサミットにかかわるのか、そこについて教えていただきたいと思います。","respondent":"中元広報広聴課長","answer":"委員がご質問のとおり、今回に関しましては、区を挙げてかかわるという意識で取り組みたいと思ってあります。文化観光課のほうで持っている観光資源でありますとか文化財資源もあわせまして、品川区を全国に紹介する機会として捉えてあります。","id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問","question":"今あるコンテンツの中で主催まで検討していく。坂井市も調べてみると消滅可能性都市ではないということで、今までこれに携わった自治体は、そこまではいかないけれども、大体、中規模の人口動態のあるところのネットワークをつくっているということですので、またネットワークというものがあるみたいなのですが、品川区はこのネットワークに入っていらっしゃるのでしょうか。","respondent":"中元広報広聴課長","answer":"現在の段階では入ってございません。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１２都市でしょうか。第１回目からこれに深くかかわっている都市がこのネットワークというのを形成しているようですけれども、またこういったところへの加盟も検討していっていただきたいと思います。この整合についてどのようにお考えになっているのか、どなたでも結構ですが、お答えいただきたいと思います。","respondent":"柏原企画調整課長","answer":"やはり、そういう両方の面を持った競争でもありますし、共存・共栄の考え方もあるということで、これはどこかに特化した営利ということではなくて、そういった共存・共栄の形をより強くしていくためにはシティプロモーションも一つの大事な項目であると考えています。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"最後に１点、坂井市ですけれども、今回、昨年の１月にシティセールス推進室というところの室長が民間雇用されたそうです。任期は５年間。今年、共催ですので、そういった情報が入っているのかどうか。同じ観点で、やはりシティプロモーション担当の強化というところも図らなければならないと思うのですが、その点のご見解を伺います。","respondent":"中元広報広聴課長","answer":"カウンターパートナーとしてそういう方をというお話ですが、これは考え方かと考えています。こういう人材をいきなり当てるのか、品川区といたしましては、まずは事業提案、運営の部分で大きく民間の活力というか民間委託ということで現在取り組んでいるです。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"続きまして、文化スポーツ振興基金積立基金３０億円で、総務委員会でこの条例審査が行われましたけれども、その中でさまざまな意見がありました。ご説明だと、オリンピック・パラリンピックが基金創設の一つの契機となっているので、五輪に関したものということで、そういうご説明があったのですけれども、五輪後の基金の存続についてどういうふうにお考えになっているのか教えていただきたいと思います。","respondent":"秋山財政課長","answer":"今回、２０２０年後はどうするのかというご質問ですけれども、当然、文化スポーツ、オリンピック・パラリンピックを文化プログラムということで、文化も一緒にやっていこうという形でオリンピックの現状はなっておりますので、そういう面も含めて。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その後も文化振興のためにしっかり活用していくという趣旨だと思うのですけれども、今回の平成２８年度の充当事業の中で、文化と読めるところは、芸術祭というものと、だいたい半分、その経費を持つということになっていると思うのですけれども、文化というところに芸術祭を当てた意図、今回、オリンピック・パラリンピックに特化しているということだと思うのですが。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした意味で、今回、充当事業の中に品川区民芸術祭が入ったという経緯です。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"こんなことが今、言われていますけれども、今度は東京オリンピックに関しては、全国でそれを超える２０万件のイベント、また５万人のアーティスト参加、５,０００万人の総参加者数、今日本の人口の半分ぐらいがそれに参加していくのだという打ち出しは、出ているはずなのですけれども、それに関して芸術祭、もちろんそれを核にするということも大事なのですが、品川区として、先ほどもあった。","respondent":"間部文化観光課長","answer":"したがいまして、今までのやってきたものについては、さらに充実・発展させていますし、今後、国等から協力が要請されるものについてもきちんと捉えて対応していきたいと考えています。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは、今までと、引き続き活用して頑張られるということでしたけれども、文化プログラムに正式に認定されるのはかなりのハードルがあるということで、先ほどのロンドンの１８万件というのも、認定されていないものも入っていたということですので、これに先んじて、品川区もそれを待ってからでは遅いと思いますので、ぜひ強化していただきたいと思うのですけれども、先ほどのご答弁、もう一度。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"私からは、最終補正予算の考え方について、特に新たに支出額を増やすほうの考え方についてということで、主にＰ５５、２款総務費、１項総務管理費と、７款１項教育総務費の基金積立追加分、それからＰ５８、２款総務費、２項地域振興費の積立金について伺いたいと思います。それから、Ｐ６２の３款民生費、１項社会福祉費の２目高齢福祉費についても時間があれば伺っていきたいと思います。","respondent":"秋山財政課長","answer":"ただ、積立ての考え方ですけれども、これはもう、税収が上がりました、当初の予算よりも税収がありました、その分は余裕ができるわけですから、その余裕をどうするかといったときに、今後税収が下がったときのために積み立てておくという形で。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"地方財政法に半分ぐらいは積み立てるようにということで、どの程度の縛りなのかわかりませんけれど、半分程度は積み立てるようにということですか。今の時点で剰余金、だから要するに、剰余金の中のどれぐらいを積立てに回そうとしているかということが伺いたくて、剰余金の見込みがあるはずだと思って伺ったのですが、いかがでしょう。","respondent":"秋山財政課長","answer":"要するに、２分の１を下回らない剰余金が出た場合には積み立てろというのが、縛りといえば縛りです。今年の剰余金ですが、財政上、特別区民税の増であるとか消費税交付金の増であるとか特別交付金の増であるとかというのが直接的には剰余になっていると考えているものです。","id":"exchange-050"},{"speaker":"吉田委員","kind":"提案","question":"本当は、だから全体剰余の中でどれぐらいを積み立てて、どれぐらいは次の繰り越しにしようとしているのかというあたりで、補正の考え方がわかるかと思って伺いました。それから、新たに創設が予定されている文化スポーツ振興基金に、一気に、他の積立額の合計より４億円ぐらい多い額が積み立てられるという提案なわけですが、その根拠も伺いたいと思います。","respondent":"秋山財政課長","answer":"それ以外にも、近づけば何らかの事業等が増えてくるであるはずだろうということで、３０億円という規模を考えたです。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"ちょっと、よくわからないのですけれども、先ほどこの３０億円という額が、ほかにも積立て追加が予定されている額の合計よりも多い額ということですよね。その考え方と、この文化スポーツ振興基金は必要のほうから積み立ててしまったというか、何かほかの基金の考え方と矛盾するように感じてしまうのですけれど、その点についてはいかがでしょうか。","respondent":"秋山財政課長","answer":"それは十分、クリアしているといった上で、その上で３０億円というものについては、ほかの基金と比べて多いとか少ないとかいうことではなくて、３０億円の規模というものでこの基金をつくっていくのだという姿勢を現わしたものだと考えて。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"ということは、この文化スポーツの振興ということを、ほかの必要性よりも優先して、この３０億円を一気に積み立てる必要があるというふうに考えたという理解でよろしいのでしょうか。一度、お答えいただいたほうがいいですか。","respondent":"秋山財政課長","answer":"基金の積立ては、当初予算にそれなりの金額を、四十数億円を出しておりまして、それプラス、今回、積立てをしているです。","id":"exchange-053"},{"speaker":"吉田委員","kind":"提案","question":"ただ、このことについては、今伺ったということで、質問はここまでにしたいと思います。６２ページの３款民生費、１項社会福祉費です。当初予算が５,４６０万円ということですので、４００万円を決算に向けて残すのみで減額しているということについて、現時点でどれぐらい利用されているのか、それから５,０００万円が更正減額となった要因について伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"実際、もともとの想定でいくと、延べ１万８００人の利用者を見込んでおりましたので、それによりまして５,０００万円の減額ということで提示しているものです。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"大変必要な事業だと言うふうに皆さん認識していらっしゃいましたし、私もこれはニーズがあるのではないかと思ったのですが、いろいろな手だてで周知は図られたということなのですけれども、ここまで差が出たということは、どうなのでしょう。周知の問題なのか、実はニーズがなかったのか、それとも例えば手続などに難しい点があったとか、要因はどのように考えられるか、もう一度伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、実際には思ったほどにいかなかったということですけれども、周知のほうがもう少し、１年目ということで不足していたかという部分もありますので、これにつきましては、来年度はポスターを新たに作成いたしまして、医療機関等にも配布するということを考えております。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"ちょっと予算のほうにかかってしまうのですけれども、大分額が減っているようで、一方で、もうちょっとニーズは掘り起こしてということと、予算が減っているということについて、私はあまり縮めてほしくないという気持ちなのですけれども、その辺はいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"やはり予算はきちんとした見込みを立てて、その実績に伴った予算を立てなければいけないと考えております。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問","question":"ぜひ、縮める方向、縮小の方向でなく、ニーズに合わせてということで考えていただけたらと思います。最後、６２ページの社会福祉総務費の繰出金のマイナスについて、計画とこれだけ差が出たことについて、社会福祉総務費全体の補正額ではなくて、ここに挙げられている３つの特別会計で伺いたいと思うのですが、時間の範囲内でお願いいたします。","respondent":"秋山財政課長","answer":"これにつきましては、国民健康保険等の歳出の連動で、マイナスした分の実績の見合いということで、繰出金がそれぞれ減額されていると考えております。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"時間が中途半端にあれなのですけれど、それぞれの３つの特別会計、１個だけでも、こういう出入りでというのを教えていただけるとわかりやすいかと思うのですが。","respondent":"永尾高齢者福祉課長","answer":"介護保険の繰出金の関係ですけれども、介護保険の関係は、平成２７年度の東京都、国からの歳入の分の清算をした結果、実績に見合っての変更ということになります。","id":"exchange-058"},{"speaker":"南委員","kind":"質問","question":"３６ページの個人番号カード交付事務費補助金について伺いたいと思います。１,１４９万８,０００円が計上されていますが、この間、マイナンバーを構築するにあたっての経費、総額でどのぐらいかかっているのか、国からの補助金として来ている金額、品川区の独自財源から支出している額があれば教えてください。","respondent":"仁平情報推進課長","answer":"システムの改修費、それと個人番号カードの交付事務関係とか、それらの経費を一応、積み上げますと、全体経費で３カ年で８億７００万円弱という形になります。特定財源のほうは３億２,６００万円ほど見込んでいるところです。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"それで、昨年から通知カードが発送されてきていますけれども、配達の総数、そして住所地とは別の場所に配達してほしいという希望もとられたと思いますけれども、その数、戻ってきた数は先ほど質問がありましたので承知していますが、その数も教えていただきたい。それから、全てトラブルなく配達、発送については終了したのか、その辺もあわせて教えてください。","respondent":"井浦戸籍住民課長","answer":"こちらにつきましては、２０万８,５８２世帯に配達しています。住民登録地以外の居所への配達のご希望という方については、７３９件でございました。戻った数の見込みですが、当初、２.５％から５％と考えてございました。現実には３万通以上ということで、１６％の戻りです。","id":"exchange-060"},{"speaker":"南委員","kind":"質問","question":"マイナンバー法は、個人情報の提供について守秘義務が解除され、提供する義務があると説明されています。しかし一方、地方公務員法では守秘義務が定められているわけです。この関係をどういうふうに見ればいいのでしょうか。マイナンバー法が上位法になるということなのでしょうか、お伺いします。","respondent":"井浦戸籍住民課長","answer":"地方公務員法の守秘義務につきましては、一般法ということであまねく定められているところです。マイナンバー法につきましては、個人情報関係の一般法であります個人情報保護法の罰条をさらに強化した形での特別法という位置付けです。","id":"exchange-061"},{"speaker":"南委員","kind":"質問・要望","question":"例えば住民税などでは、税情報に寡婦控除とか障害者控除だとかが、一定の記載がされていると聞いているのですけれども、そういう自分以外の方たちに知られたくない情報があるとしたら、マイナンバー法では提供する義務があるとなると、これは個人のプライバシーのところと本人の同意が必要としていないという関係で、どういうふうに区はこのあたりを考えておられるのか、そこを伺いたいと思います。","respondent":"井浦戸籍住民課長","answer":"２点目の、本人同意なくてもマイナンバーの番号を提供するということが義務付けられてありますが、個人情報保護法の一般法であります行政機関個人情報保護法におきましても、本人同意のほかに、法令上の定めがある場合という形で明記されてあります。","id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"それで、先ほど答弁をいただいた、この間の経費が８億７００万円弱という経費をかけて、いろいろな問題があるという法律、マイナンバー制度について、やはり品川区としては、国からのあれだからやむを得ないと思っているのか、あるいはいろいろな問題点を抱えているけれどもという大前提でやっているのか、その辺をどういうふうに見ているのかを伺いたいと思います。","respondent":"井浦戸籍住民課長、仁平情報推進課長","answer":"韓国につきましては、マイナンバーの番号そのもので本人確認をするという仕組みになってありますので、日本は、本人確認情報についてはきっちりと運転免許証あるいは顔写真付の公的な証明書で確認するという形で構築されてありますので。今後、自治体間で情報提供のネットワークを構築していくことになりますけれども、こちらのほうも、安全性といいますかシステムを強化しながら、安全な運用に努めていきたいと考えているところです。","id":"exchange-063"},{"speaker":"南委員","kind":"質問・要望","question":"そういうこと、お金をかけてまでやる必要があるのかと非常に思います。別にマイナンバーを構築しなくても、９９.９％までの連携がとれているという実態がある中で、こんなにお金をかけて、しかも危険な、情報漏えいが絶対ないわけではないわけですから、そういう本当に危険な、しかも本人の個人情報を提供することを同意も求めない、そういうやり方でやる必要があるのかとすごく思うのです。","respondent":"井浦戸籍住民課長","answer":"日常的な窓口業務の中では、細心の注意を払いながら適切に対応してまいりたいと考えています。","id":"exchange-064"},{"speaker":"南委員","kind":"質問","question":"実際、区にはどの程度の相談あるいは苦情が寄せられたのかをあわせて伺いたいと思います。それで、細心の注意とおっしゃるけれども、本人にとっては、やはりそれは知られてほしくない。どんなに細心の注意をしていただいても、そういう気持ちは拭えないというところを、どういうふうに区は思うのかというところをあわせて教えてください。","respondent":"井浦戸籍住民課長","answer":"このマイナンバーのカードの制度につきましては全国的な制度ですので、視覚障害をお持ちの方への対応、さまざまな障害をお持ちの方の対応についても、国から通達が発せられるですので、ご指摘の課題につきましても国の通知を待って対応してまいります。","id":"exchange-065"},{"speaker":"横山委員","kind":"質問・要望","question":"文化スポーツ振興基金の積立金についてお伺いいたします。そして確認なのですけれども、具体的には先ほどアーツカウンシル東京の文化芸術支援事業のお話がございましたが、品川区内の個人・団体が芸術文化の魅力を発信する創造活動に対して、例えば東京都や財団法人などの助成支援の活用というのを積極的に実施していただきたいと考えますが、そのあたりもお聞かせください。","respondent":"秋山財政課長","answer":"ご提案のいろいろな施策というか、映画のものであるとかということもご意見をいただきましたけれども、そういうものを含めて、今後どういう形でそれを文化プログラムの中でやっていくのかとか、そういうことも含めて今後検討をしていきたいと思っていますし。","id":"exchange-066"},{"speaker":"横山委員","kind":"提案","question":"大井町の駅でアンケートを実施していただいたり、さまざまな、先ほどありましたけれども、キャンペーンサイト、ＳＮＳの連動、ノベルティーグッズの活用、またキャッチコピーも決まってまいりましたし、動画、民間ならではのさまざまな活力を提案していただいて、一緒に、ともにやっていくといった方針が打ち出されてまいりましたけれども、こうした他自治体との連動。","respondent":"中元広報広聴課長","answer":"１点目の、全国シティプロモーションサミットの件ですが、こちらのほう、会場に出展等できるように準備を進めているのですけれども、伝えるというコミュニケーションの部分では、これは来年度予算のところでのことになりますけれども、品川区を紹介する動画などを検討しています。","id":"exchange-067"},{"speaker":"横山委員","kind":"意見","question":"しながわ」の統一イメージを、いろいろな方に、さまざまな、かかわってくださる方にお伝えして、一連の統一的なシティプロモーションとして実施していただくということなのですけれども、例えばＳＮＳで各事業者同士がお互い広報を協力し合っていく体制ですとか、またノベルティーグッズを各事業者に活用していただけるような、連動して重層的に仕掛けていくような観点を。","respondent":"中元広報広聴課長","answer":"伝わるというところですけれども、こちらのほうから積極的に発信していくことで、その結果、効果等が見込めていければと考えているところです。","id":"exchange-068"},{"speaker":"横山委員","kind":"提案","question":"区のほうで提供していただくというのは、物資だったりノベルティーグッズをそのまま提供ということだけではなくて、今ご答弁いただいたように、情報として、こういった活用の例がありますということで、ホームページにも掲載があるかと思うのですけれども、例えば次回の事業提案の募集の際などに、十分な情報提供と。","respondent":"米田人事課長","answer":"管理職に向けましては、人事課のほうで把握いたしました超過勤務時間につきまして、四半期ごとに所属長のほうに提示し、残業に偏りがないか、効率的な職務の遂行ができているかということを通知するとともに、なかなかイントラなどで判断するというのは難しいのですけれども。","id":"exchange-069"},{"speaker":"横山委員","kind":"質問・要望","question":"超過勤務に関しては、適正な管理の徹底に努めていただきたいということで、今後ともお願いいたします。職員の給与に関する条例の改正において、管理職および係長職の職責の高まりを考慮して、４級以上の級において引き上げを強め、６級以上の級においてはさらに強めた引き上げを行っておりますが、今後の各昇任選考のあり方についてお聞かせください。","respondent":"米田人事課長","answer":"いわゆる処遇の面についても、昇任意欲の向上にはつながると思ってありますので、その辺は人事委員会等の調査にもよりますけれども、その辺の取組みとしては２３区で、より魅力のある管理職や管理・監督層の構築についての制度構築を行ってまいります。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"当初予算では、巡回相談員等経費ということで、６,２３７万７,０００円ということで、なぜいじめ防止対策事業補助金が巡回相談員等経費というところに充てることとしたのかということの経緯と、補助金を入れることによりまして事業内容に何らか影響や変化等があったのかどうかということについて教えていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"私のほうから、巡回相談員等の経費についてご説明いたします。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問","question":"この、いわゆる、何というのですか、巡回相談員における業務の内容とかスキル、資格と言ってもいいかもしれませんけれども、そういったものがどういった違いがあるのか、また、２つの業務というか、かぶるところもあるのではないかと思うのですけれども、そういう意味では、事業の連携とか情報の共有とか、そういうことは図られていたりするのか、その辺をお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"一方、特別支援という部分につきましては、心理職ではありますので、各教室に配慮を要する子どもたちの、教員への対応の仕方を助言したり、また保護者について、子どもたちの様子を先生、担任と学校とをつなぐという役割を持っております。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういった条文をしっかりと定める中で、品川区のいじめ防止をより一層進めていただきたいというような思いですので、よろしくお願いしたいと思います。続いて人間ドック助成追加分なのですけれども、当初予算が１８５万３,０００円から、補正で２８３万１,０００円ということで、非常に当初予算を上回る補正ということで、大幅に増額になっておりますけれども、まずこの辺の理由についてお伺いします。","respondent":"高森国保医療年金課長","answer":"平成２７年度におきましては、平成２６年度の見込みもまだ立たない状況でございましたので、平成２６年度と同じ形で２００件、１６０万円の予算計上をさせていただいたところですが、平成２７年度、平成２６年度につきましても、終わりましたところ、３５５件の利用をいただいた。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問・要望","question":"今ご説明があったとおり、非常に、人気という言い方でいいのかどうかわからないですけれども、大変、要望、ニーズが多い事業かと思います。来年、平成２８年度は３年目になるかと思いますけれども、今ご答弁があったかもしれません。この８,０００円というのが、今どのように評価されているかお伺いいたします。","respondent":"高森国保医療年金課長","answer":"人間ドック助成金の８,０００円の根拠というか、決めた内容ということですけれども、ここはおおよそですが、国保基本健診に受診されましたときの経費というのが、実は７,８００円ほどかかってございまして、そこから同様の助成をということで。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問・要望","question":"今ご説明いただいたのですけれども、人間ドックは一般的には非常に、１０万円ぐらいは大体かかってしまうかというふうに、普通に見ると思うのですけれども、そういった中で、広くいろんな方に利用していただくという意味で、今、非常にこの事業のニーズは進んでおりますけれども、一方で、全体の費用から考えた助成の金額というのを検討していただきたいというようなところもございましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"大倉委員","kind":"質問・要望","question":"ページ数で、５３ページ、日野学園人工芝生化新設事業、あと５７ページ、シティプロモーション経費追加分、またあと一点、これはわからなかったので教えていただきたいのですが、もしかしたらここではないのかもしれないのですが、学校施設整備費で体育館の床の張替えが行われているかと思うのですが、ここに入っていないかもしれないのですが、ちょっと今までの文教委員会でも報告等なかったので。","respondent":"品川庶務課長","answer":"日野学園の人工芝についてですが、場所はまず校庭のほうになります。人工芝は校庭のほうで行っております。今まで日野学園はゴムチップだったのですけれども、それの張替えで人工芝ということになっております。それから工期については、現在もう終了しているような状況です。","id":"exchange-076"},{"speaker":"大倉委員","kind":"質問・要望","question":"人工芝生が選ばれた理由について教えていただきたいのと、今まで第三日野小学校等、人工芝生化が行われている部分の評価について、子どもたちの安全性の向上とか運動面とか、夏場は実は湿度が上がって大変とか、空き時間の活用が増えたとか、そういうさまざまな観点からどのように評価しているか教えていただきたいと思います。","respondent":"品川庶務課長","answer":"あとスパイクを使った競技ができないとか、そういうデメリットもあるというような状況です。","id":"exchange-077"},{"speaker":"大倉委員","kind":"質問・要望","question":"さまざま子どもたちにおいてはメリットがある。一方で、耐震車とか、車が入れないという部分や、野球、サッカーのスパイクが使えないというところがあるというところで、わかりました。それで、今後、そういった人工芝については品川区内でどのような展開を考えておられるのか教えていただきたいと思います。よろしくお願いします。","respondent":"品川庶務課長","answer":"ただ、昨今、人工芝も大分、金額が安くなっていますので、これもやはりこれからに向けて、導入コストとか、あとランニングコスト等も見ながら、今後も研究をしながら人工芝化を進めるかどうかも考えていきたいと考えています。","id":"exchange-078"},{"speaker":"大倉委員","kind":"質問・要望","question":"私も地域を回っていると、土で水はけが悪くて困っているところなどというのは聞いておりますので、ぜひともそういったところも勘案していただきながら研究していただきたいと考えています。次に移ります。この「わ！しながわ」の色、青、赤、緑、ピンクなどといろいろあるのですが、これは何か一つ一つ意味などというのがあるのでしょうか、教えてください。","respondent":"中元広報広聴課長","answer":"こちらのロゴマークの色の意味ですが、特に一つ一つの色の意味を固定しているわけではございません。多様な要素、魅力を持っている品川区をあらわすということで、色を変えているです。","id":"exchange-079"},{"speaker":"大倉委員","kind":"質問","question":"まさに、「何とか＆ＴＯＫＹＯ」というところで、東京でしか出会えないような価値、新しい発見と体験にあふれた日常の楽しさを、東京都が一丸となって発信していくというところで、これは東京都のホームページのあれなのですが、これだと、例えば「＆ＴＯＫＹＯ」の「＆」が色違いで、あかね色、藤色、クチナシ色、松葉色、はなだ色、いろんな伝統のある色使い、昔からあるような色を使って。","respondent":"中元広報広聴課長","answer":"ロゴマークのマニュアルのほうでは、多色展開のほかにも１色で、何色かをご用意をしていますので、各、使われる方のお気に召す色とか方針に合ったものをダウンロードしていただければです。","id":"exchange-080"},{"speaker":"大倉委員","kind":"質問","question":"例えば、このシティプロモーションの中には、区外の方が品川に興味を持ち、実際に訪れることで、住んでみたい品川区を感じてもらえるシティプロモーションというところで書いてあるのですが、外国人の方などにも、こういった色の違いというのは結構わかりやすいのではないかというところで思っておりますので、もう一度、その後の展開について、ぜひ進めていけないのかと思っているのですが、どうでしょう。","respondent":"中元広報広聴課長","answer":"確かに委員のご提案のような考え方で、藤沢市などはある程度、色ごとに使う組織を決めていたり、そういう展開をしているところもあります。しかし、ここのところにつきましては、区としては、現段階ではまだ今後の研究課題とさせていただきたいと思っているところです。","id":"exchange-081"},{"speaker":"大倉委員","kind":"質問","question":"わかりました。体育館のほうなのですが、以前、いろんなところで、第一日野小学校でしたっけ、体育館のささくれが起きて、張替えが行われて、また削られてというところで、体育館の床がまた新たに張替えられているというところで、この中の例えば学校設備費が入っているのかどうか、入っていなかったとしたら、ここで質問していいかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"大倉委員","kind":"質問・要望","question":"今の説明だと、非構造部材、補正予算の中で、張替えが行われたのですが、これはいつ行われて、どういう理由で行われたのか教えていただきたいのですけれど。","respondent":"品川庶務課長","answer":"今年度、体育館の床の張替えは、冨士見台中学校、大分、床がささくれ等もございまして、非常に体育館を使う中でも、いろんな制限を学校内でかけていたりとか、やっていたところなのですが、そこの部分については体育館の床の改修を行っております。","id":"exchange-083"},{"speaker":"大倉委員","kind":"質問","question":"第一日野小学校の張替えが行われたのかと思ったのですが、冨士見台も行われたということでいいのでしょうか。第一日野小学校の張替えについて教えてください。","respondent":"品川庶務課長","answer":"そういった塗料材を使って床の補修をしていくというものを、業者のほうでも少し使ってみたいというようなことがありましたので、こちらの無償という形で体育館の床を整備したというような状況です。","id":"exchange-084"},{"speaker":"大倉委員","kind":"質問・要望","question":"これはいつ行われたのでしょうか。教えていただきたいのと、張替えで、業者のほうから無償で塗料を塗る形で変更があったというところで、もともとの床との違いというのは、そんなに出ていないのかどうか。","respondent":"品川庶務課長","answer":"今後、維持の経費につきましては、基本的には塗料を塗ってありますので、壊れていくとか、そういうことがない限りにつきましては、特段、費用が掛からないものと考えております。","id":"exchange-085"},{"speaker":"大倉委員","kind":"質問・要望","question":"塗料を塗られているというところで、逆に言うと、例えば床に紙を置いて、ペンでなぞるとへこんでしまうとか、床に書きにくくなってしまうとか、シャーペンの芯が刺さって残ってしまうなどという話も耳にしましたので、そういったところも勘案して、いろいろそういった、子どもたちに対するけがとか、ないようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問","question":"私からは、まず一つ、３４ページの特別区民税、８億円余が増加されました。いろいろ今まで質問がありまして、納税者が増えましたということを言っているのですが、人口増もあるのだろうということで、これらの人口増に対して、世代別に対しての分析をどういうふうに見られているのか、まずお聞きしたいと思います。この地方創生加速化に対して、児童センターが充当事業とありますが、中身を教えてください。","respondent":"黒田税務課長、柏原企画調整課長","answer":"平成２７年から平成２８年の人口増につきましても、同じように４０歳代、５０歳代の増が多いというものです。それで、児童センター運営費になってありますのは、平成２７年度に岩手のほうから雪を運んできて、ＥＣＯフェスティバルのほうでやった事業があるのですが、それを、児童センターのお祭りを５月の連休で予定してございまして。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"人口増ということで、４０代から５０代。そして、この人口増に対して、品川区はいいと思っているのかどうなのか、そこの分析はどうされているでしょうか。児童センターのほうで単発的な事業に充当したということなのですが、地方創生加速化ということであるならば、もう少し広い展開で継続的な何かそういうものも計画していいのではないかと思うのですが、その辺のご意見をお聞きします。","respondent":"柏原企画調整課長","answer":"それで、今おっしゃっていただいた行政ニーズにつきましては、当然、人口が増えることによってニーズが高まるとは認識していますので、さまざまなニーズの分析をしながら、必要な行政ニーズに対応する施策というのはやっていかなくてはいけないと捉えているところです。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"地方創生という意味では、これから国の動向がいろいろあるかと思いますので、活用できるように注視していただきたいと思います。だけれども定住するかというと、定住がどこまでするのでしょうかと。そうすると、当然そこでの税収の配分も行政ニーズも変わってくる部分があると思うので、それらの使い方を含めた形での補正予算をつくっていくべきではなかろうかと思うのですが、その辺のお考えをお聞きします。","respondent":"柏原企画調整課長","answer":"これにつきましては、税という観点で言いますと、区全体として捉えておりますので、それをいかに地域、エリアで行政ニーズが出てきているのか、それに対してどう対応していくかというのは、まさに地域の実情を分析しながら。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"要は定住していくという、外に対して、中に対して、どういうイメージを持って品川区を見ているのかというところが、やはりもう少しはっきりと認識するべきではないのかと思っているのです。住み続けていただきたい。だから、全体的に人口増をどう見て、これから５年後、１０年後先にどう品川区をつくっていくのかというのは、もう少し分析を進めて実態を見ていく必要があるかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"渡部委員","kind":"質問・要望","question":"１６、１７ページの国民健康保険事業会計、１０２ページのあたりからいろいろ質問をさせていただきたいと思います。先に、思いのある質問をする前に、この表の見方で、１０２ページです。例えば今回、節のところで、後期高齢者支援金分というところで、３節、４節が出ています。何が繰越しなのというのがちょっとわからなくなったので、先にその２点を説明いただけますでしょうか。","respondent":"高森国保医療年金課長","answer":"この繰越金につきましては、平成２７年度の補正に載っておるわけですけれども、平成２６年度におきまして、歳出部分のいわゆる余剰金というか、残ったお金がありまして、その残ったお金が平成２７年度、翌年の歳入ということで繰越金ということで、ここに歳入計上しているもので。","id":"exchange-091"},{"speaker":"渡部委員","kind":"質問","question":"繰越金のところはわかりました。すみません、もう一つ、１０８ページと１１８ページのところなのですけれども、高額医療費共同事業というのが歳入・歳出と同じ額で入っているのです。この高額医療費共同事業交付金というのは、都支出金とか国とも書いていなくて、どこから交付されるのでしょうか。それで、この共同事業というのは何なのでしょうか。そもそも、今さらなのですけれど、これは何なのでしょう。","respondent":"高森国保医療年金課長","answer":"これは、２３区の共同事業という形になっておるわけなのですけれども、品川区で被保険者の方が大変高額な医療がかかったりした場合に、品川区で全額それに対して負担しなくてはいけないというふうなリスクを回避するために、先に共同事業の拠出ということで。","id":"exchange-092"},{"speaker":"渡部委員","kind":"質問","question":"払ってもらえないみたいなところだと思うのですけれど、今、実際、９万人のうちどれぐらい滞納者がいるのでしょうか。パーセントを追いかければあれなのですけれども、たしか課長に前にお伺いしたところ、２年で時効だということですが、例えば２年間、もう本当に払わないで逃げ切ってしまったといいましょうか、時効を迎える方々というのは、大体どれぐらいいるのでしょうか。","respondent":"高森国保医療年金課長","answer":"合計額ですが、平成２６年度におきましての、時効２年ということでの不能欠損額は５億９７０万円ほどです。短期証の関係ですが、短期証の方につきましては、平成２７年１０月の数字がございまして、対象者数は４,６９２名、資格証の世帯については１１６世帯です。","id":"exchange-093"},{"speaker":"渡部委員","kind":"質問","question":"この間、もう約６０年でしょうか、皆保険の制度ができて、いわゆる被用者保険、企業などに入っていると、会社も負担してくれる、個人も負担してくれるで、保険がかかるわけです。それで、当たり前のことを当たり前にやっていただかないと、税の公平性とよく言いますけれど、これこそまさにそれではないですか。これは行政がやらなければならない義務だと思うのですが、その辺の意気込みをお願いいたします。","respondent":"高森国保医療年金課長","answer":"ただ、その中で低所得者の方に限りましては、均等割額が７割軽減、５割軽減、そして２割軽減というふうな形で、必要に応じて、所得に応じて、低所得者に対してはそういうふうな形で保険料を軽減いたしまして納付をいただいているものですから。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問","question":"私からは、６５ページの民生費、保育従事職員等処遇改善事業とその下の保育士等処遇改善臨時特例事業。それから２点目が、１０２ページの国民健康保険料、今、渡部委員が質問をされまして、少々重なる部分もありますけれども、ご了承ください。その改善策に、本来執行されるはずの本予算額、そのまま減額、未執行となっているように見受けられますけれども、補正減額の理由をまずお聞かせください。","respondent":"竹田保育課長","answer":"こちらの処遇改善につきましては、平成２５年度から予算計上し、個別事業として実施してまいりましたが、平成２７年度より施行されました子ども・子育て支援新制度におきましては、基本運営費相当額である公定価格の中に処遇改善が加算項目として含まれましたので。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"その辺のチェック状況というのでしょうか、区としてはどのように把握し、確認しているのでしょうかというところが１点と、それからもう少し具体的に保育士の処遇改善状況をお聞きしたいのですけれども、例えば国では、職員の勤続年数や経験年数に応じて３％加算するとか、また東京都では２０１５年度から、保育士の評価・昇進制度を導入する民間事業者を対象に。","respondent":"竹田保育課長","answer":"家賃補助ですが、こちらは東京都から２月に要綱が届きまして、平成２７年度の単年度の要綱ということで来ておりますが、現在の状況を鑑みますと、平成２８年度以降も必要な事業だと考えておりますので、今後も平成２８年度も継続していくものと考えております。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"国民健康保険料については、基本的なお金の流れを確認させていただきたいと思います。４億円増の減となっておりまして、なぜこのような、当初予算に対して大きく乖離してしまうのでしょうかというところと、それから当初予算の保険料の見込み、納めていただく見込みが違っているのか、算定の違いがあるのか、それのほかに要因があるのか、そこのところを教えていただきたいと思います。","respondent":"高森国保医療年金課長","answer":"当初予算では、平成２８年の３月末が９万１,０００人ということで見込んでおったのですけれども、既に平成２７年の１１月末で９万１５０人ほどになっているということで、３月はそれをさらに下回るような状況ということで減額補正をさせていただいているところと。","id":"exchange-097"},{"speaker":"こんの委員","kind":"質問","question":"現状がわかりました。この国民健康保険料は、先ほどの渡部委員のご質問もありましたけれども、非常に仕組みが複雑でわかりにくい。ですので、この国民健康保険の仕組みと保険料の関係、それから医療給付との関係、こうしたことも、加入者にもっとわかりやすくお知らせしていただいて、ご理解とご協力をいただけるような対応の強化が必要と考えるのですが、ご見解はいかがでしょう。","respondent":"高森国保医療年金課長","answer":"今、ご意見をいただきました。現在も４月に「こんにちは国保」だとか、また保険料を算定して、ご案内さしあげているのですけれども、それとは別にホームページ等やってあります。今後、今の意見を受け止めまして検討しますので、よろしくお願いします。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問・要望","question":"５５ページの総務費、基金積立金追加分について伺います。これですけれども、平成２５年度末の７７７億円から引き続き過去最高を更新しております。一方で、待機児童、１次で４月の入園申込みが１,１８５人になるなど、切実な区民要望はあふれているという中で、私は、こうしたお金というのは区民の暮らし、福祉に充てるべきだと思いますけれども、そのお考えはあるかどうかお伺いします。","respondent":"秋山財政課長","answer":"この基金を補正でどう使うかということでありますけれども、当初の予算で、それぞれ社会保障なり何なりということは扱ってありますし、今回の補正につきましても、補正予算の中で保育園の部分に入れているというのは、補正予算の中でもお示ししているとおりですので。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問","question":"当時、１年前の資料では見込みということで、７１４億円が１３０億円増えて、最終補正ではこうした額になっているわけですけれども、これは見込みどおり、当時見込んでいた額より１３０億円も増えたというのは、見込みの想定をさらに超えているのではないかと思うのですけれども、区としては見込みどおりなのかどうか伺います。","respondent":"秋山財政課長","answer":"基金の当初の見込みは、あくまでも当初の見込みでありますので、それから経済がどう動いているのかという現状を見て補正をするですので、決して何か余分に入れているというような、ため込んでいるというようなところではないと考えているものです。","id":"exchange-100"},{"speaker":"安藤委員","kind":"意見","question":"ちょっと、税収増と執行効率ということですが、執行効率を上げるにしても、すごくこんなに増えるということは、どれだけ効率を上げたのだろうと。裏を返せばどれだけ合理化したのだろうかという思いを抱かざるを得ません。それで、ちょっと見込みどおりかどうかというか、１３０億円増えてしまったということは見込みどおりだったのかどうか、ここはどうかというのを聞いたので、もう一度お願いします。","respondent":"秋山財政課長","answer":"それは、そのときそのときで補正はしていますし、それなりにこちらも考えているですので、当初から、今の時点で１３０億円がどうかという議論にはちょっとならないのではないかと思います。","id":"exchange-101"},{"speaker":"安藤委員","kind":"質問","question":"それが、実際にやってみて最終補正で、これが７４９億円に、１００億円も増えたと。ですから、今の平成２７年の基金残高も、今回７１４億円という数字がさらに増えて８４５億円の数字が出ておりますが、これからさらに、過去の例を見ますと、増えて、決算値では９００億円に達する可能性もあるのではないかと思うのですけれども、そこら辺の見込みはいかがでしょうか。","respondent":"秋山財政課長","answer":"ただ、当初の予算で、これから先１年後に、また百何十億が入ってくるというふうに想像するというのは、想像することは可能ですけれども、それをもって予算をつくるというわけにはいきません。","id":"exchange-102"},{"speaker":"安藤委員","kind":"質問","question":"これはもはや見込み違いの域を超えていると私は思います。しかも責任ある行政を担っている品川区ですから、初めからちょっと厳しい、厳しいといって、やはり一つ、ある意味出資を抑えたり、予算を厳しく見積もって、年度末補正ですとか決算時にどーん、どーんと積み増していっているようにしか思えないのですけれども、これは違うのでしょうか、違うのかどうか伺います。","respondent":"秋山財政課長","answer":"来年度予算はちょっと話せないのかもしれませんけれども、伸びの中で社会保障を増やすためには、基金というのが当然、歳出を伸ばすにはそれだけの歳入が必要ですから、基金というのがないと区民サービスのために仕事ができないということになりますので。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば、先ほども紹介しました１次で１,１８５人ものお子さんが入れなかったというところで、本当にもう明日どうなるのか、仕事をやめざるを得ないという悲痛な声が届いている中で、むしろ予想を超えて多く集まったというのであれば、そこは品川区として姿勢を見せて、基金を積み上げるのでなく、今、本当に緊急に求められているそうした対策にこそ充てるべきだと思うのですけれども、いかがでしょうか。","respondent":"秋山財政課長","answer":"それはなぜかというと、今後区政が、経済の状況が悪化したという場合においても継続できるようなということで考えて積み上げている。それが、それぞれの目的に沿ったものでやっているというものです。","id":"exchange-104"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただ、それでも、今の切実な区民の要望からすると、苦境からすると、足りないということなのです。ですから、そこにはきちんと、今、財源があるわけですから、しっかり充てていくということが私は必要だと思いますし、そのことを求めますけれども、いかがかと。区はそうした考え方なのでしょうか、そこら辺をしっかりと考え方を聞かせてください。","respondent":"秋山財政課長","answer":"基金に積み立てるのを行政の目的としているわけでは全くありません。もちろん区民の生活のためにいろいろな事業を行っていくのが品川区の財政運営だと思っていますので、そのようなことは考えてございません。","id":"exchange-105"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、福祉の充実、区民要望の実現というのがやはり区政の最大の使命ですので、そこに視点を当てて頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"鈴木（真）委員","kind":"確認","question":"財調です。そこら辺の部分について確認したいのですが、というのは、この予算でも、区税が８億円、消費税が８億円というプラスの部分も入っています。ここで、収入額は見ないで調整額だけ出てくるのか、そこら辺の入り組みについて確認させてください。","respondent":"秋山財政課長","answer":"それを各区に分配ということで、２５億円程度であろうということで、今回、補正予算に載せさせていただいたです。","id":"exchange-107"},{"speaker":"鈴木（真）委員","kind":"質問","question":"３８６億円の入ってくる計算根拠というのは、資料の中で見ると何項目か算定が入って増えてきたと、それが３８６億円という数字になっていますけれども、その段階においては、もう３８６億円だけを按分していく。各区によって、今言った、区税ですとか消費税の問題も絡むと、収入額が相当変わると思いますが、そこら辺は算定の根拠に入ってこないで計算するものなのでしょうか。","respondent":"秋山財政課長","answer":"基本的に財調の場合は、収入額と需要額の差を財調の交付金としますということで、それが調整三税の５５％と合うように調整しているというのが現状あります。ですので、今回も収入額と需要額の差というところで、各区を見て、それを算定する。","id":"exchange-108"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっと、その差額というか、余裕が出た数字が、その辺がちょっと疑問もあるところなのですけれど、何というのか、算定項目をそこに合わせてしまっているのかという、悪くとればそういう感じが自分には思えているのですけれど、そこら辺はどうとったらいいのかというのと、もう一つ、これから財調の考え方として、来年度も概ね数字は増えていますけれど。","respondent":"秋山財政課長","answer":"今後の財政調整の見込みにつきましては、税制改正というのがございまして、ご存じのとおりに地方法人課税の偏在の是正ということで、平成２８年度では区の割合にすると大体７００億円ぐらい、平成２９年度ですと７６３億円がマイナスという形に、今、特別区では。","id":"exchange-109"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。これから法人住民税の国税化という問題もありますし、区としてやはりこれからも厳しい状況になってくると思うので、収入の面につきましてもうまく調整していただきたいと思います。公債費で確認します。公債費の補正予算の資料の８２ページですと、利子の金額が３億３５３万６,０００円。これだけ、数字の確認をしたいのですが。","respondent":"秋山財政課長","answer":"これについては、減税補填債のほかに、一時借入金等の利子も含まれているので、若干数字が違うです。","id":"exchange-110"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。ここが数字が違ったので、それが一つ気になったのと、それから、これだけ金利が下がっている中で、大分前だと思うのですけれど、公債の借替えをやったことがあると思うのです。今の借りている金利とこれからの金利を考えると、そこら辺はどういうふうに考えていくのか。確かに大変難しかったというのは記憶があります。その辺の考え方を教えてください。","respondent":"秋山財政課長","answer":"ただ、そのときは減税補填債なので、法的に可能と国が法律で変えましたので、借替えをしたということになっておりますので、基本的には、高いときに借りたものを、何ですか、中途で一括償還して低い金利に借り替えるという、通常。","id":"exchange-111"},{"speaker":"鈴木（真）委員","kind":"確認","question":"後でたしか、その減税補填債、ちょっと自分の記憶があれですけれど、何か特殊なケースでやったという記憶があったので、それを確認したいと思います。これもやはり議会側に何もなくて、それで品川区と宮古市で５項目結んだなどとある。最近、そういう情報が議会側に入ってこないケースがややあるような気がするのですが、その辺、どうお考えでしょうか。","respondent":"中元広報広聴課長","answer":"シティプロモーションのほうの認定事業の総務委員会報告ですが、９月２５日の総務委員会で採択事業を決定した段階で一度ご報告させていただき、その後、２月２３日のご報告という流れです。","id":"exchange-112"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これに限らず、ちょっとその辺はうまく情報を出していただきたいという気がしますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"債務負担行為の八潮図書館防犯カメラですが、なぜこの八潮図書館に防犯カメラが必要になったのかというのと、理由があれば教えていただきたいのと、区全体でのいわゆる区有施設における防犯カメラの設置状況、また区の考えと取組みについてお伺いします。よろしくお願いします。","respondent":"渋谷指導課長、小林施設整備課長","answer":"小中一貫の２年で打切りになったという件ですが、国のほうの事業の内容が３年で当初予定していたものが、２年で事業の組替えということで、２年間で変更になったというふうなことです。八潮図書館の防犯カメラの件につきまして、図書館の資料および利用者の安全を確保するということで聞いております。","id":"exchange-114"},{"speaker":"石田（し）委員","kind":"質問","question":"小中一貫教育はわかりました。特段問題はないということですが、３年のものが２年になったということで、しっかり調査研究がされたということでよろしいのですか。わかりました。防犯カメラなのですが、区の全体的な考えをお聞きしたので教えてください。１億５,２９９万５,０００円ですか。その契約についてもお伺いいたします。","respondent":"秋山財政課長、仁平情報推進課長","answer":"この辺の考え方は、それぞれ周囲の状況といいますか、社会的な防犯カメラに対する考え方というところも、ここ１０年を考えればかなり変わってきますので、その時々で必要なところに必要なものをつけていくという方針です。今回の補正で備品購入費として大きな額になっておりますけれども、これは国の補助金の関係で、一時的な経費ということで、購入経費、通常ですと賃借料という形を区はとるのですけれども。","id":"exchange-115"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"各種がん検診の追加分ですが、説明の中では実績増だということですので、当初予算だと子宮がん検診が１万３,８００人、乳がんが１万１００人、肺がんが１万８５０人というふうに当初予算がされていたのですが、その変化について内訳を教えていただきたいのと、例えば検診率がどのようになっていったのかということ、それと区の目標値があるのかどうか、あったらその目標値を教えていただきたいのと。","respondent":"仁平情報推進課長、川島健康課長","answer":"このシステムは新しく増えていくという形になります。こちらのほうは、そのシステム構成を構築する際に、間をファイアウォールで挟み込むなどという対策が必要になってまいります。数的な部分で言いますと、子宮がん検診は１,７４０件、それから乳がん検診が１,２６５件の増ということで、当初の部分で見込めなかった要因があったのかどうかというようなお話ですが、多分、こちらの数が増えている部分。","id":"exchange-116"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひ上げていっていただければと思います。本日から８日までの間の１週間ですか、女性の健康週間だというのを目にしたので、こういったときに、ぜひそういった検診の周知をやっていっていただければと思うのですが、その点、いかがでしょうか。","respondent":"川島健康課長","answer":"ご指摘のものに限らず、折に触れて、どういったところで訴求力のある啓発ができるかというのは研究させていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"３点、基本的なところを確認します。それから、現状の進捗状況、また今後についてもお話を伺いたいと思います。それから更正減額の理由をお聞きします。デッキの所有者、また管理や運営者はどういう方なのでしょうか、お聞きします。当然あると思いますので、法令の中での規制だということだと思うのですけれども、そういう規制がどういうふうにかかっているのかというところを教えていただきたいと思います。","respondent":"溝口都市開発課長、永尾高齢者福祉課長","answer":"今回補正を組みます４５０万円につきましては、今回のモデル事業に採択されたことによって、もともと大崎の駅前地区の再開発にあたって。入院中の紙おむつ代助成事業の件数ですけれども、当初予算では延べ１万８００人を予定しておりましたけれども、平成２７年１１月までの実績でいきますと、延べ１９９人ということでございました。","id":"exchange-118"},{"speaker":"若林委員","kind":"確認","question":"では一つだけ。紙おむつは、入院中の方が１万８００人が対象で、在宅ではなくて入院中の方がということで。もう一回、確認をさせてください。","respondent":"永尾高齢者福祉課長","answer":"ですので、この方たちのうち申請された人という考えではなくて、あくまでも初年度でしたので、そういう想定で数字を決めさせていただいたところです。","id":"exchange-119"},{"speaker":"若林委員","kind":"質問","question":"わかりました。ではいずれにしても、想定はなかなか難しい想定だったという中で、非常に、これは割り返すと１,０００人分でしょうか、１人５,０００円ということですので、これは、先ほどの質疑の中では、要介護度をちょっと緩和しようという、来年度に向けてのお話があったのですが、この事業はそもそも最初の説明は低所得者対策、非課税の方を何とか支援しようというところでスタートしたはずです。","respondent":"永尾高齢者福祉課長","answer":"それで、平成２８年度予算で今考えているところでは、非課税はそのままにしておいて、要介護度を３以上というものをとろうかというふうに考えているところです。","id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"来年度予算になってしまいますけれども、要するに、今必要な方がもしかしたら１９９人以上、たくさんいらっしゃるかもしれないというところを、先ほどの質疑では周知をしっかりやっていくという言葉で全部おさまってしまったのですけれども、周知をしても届かない人がそもそもいるという視点で、また来年度取り組んでいただきたい。では要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"本多委員","kind":"確認","question":"７２ページから７９ページの土木費について、補正前の２７９億６,８３６万４,０００円、補正額がマイナス２８億６,０５８万４,０００円ということで、土木費全体で約２８億円余のマイナスということなのですけれども、それぞれ全体の中では増があったり減があったりで、トータルでマイナス２８億円余ということなのですけれども、執行として、この２８億円余についてどのような捉え方をされているのか。","respondent":"秋山財政課長","answer":"は再開発等の事業進捗により、１１億円程度減額させていただいているということなので、そういうところで大きくなってしまっていると認識しております。","id":"exchange-122"},{"speaker":"本多委員","kind":"質問・要望","question":"いろんな項の中で２つだけ絞って聞かせていただきます。道路橋梁費の１５億円余の減、都市計画費の１２億円余の減、理由は今、課長がご答弁いただいた同じ内容かもしれませんが、この辺の分析を、どういうふうに、こういう背景があるのか、その辺をそれぞれお聞かせいただきたいと思います。","respondent":"稲田道路課長、溝口都市開発課長","answer":"それから２つ目は東品川橋架替に伴う護岸の復旧工事というのがございまして、これが不調になってしまいまして、対応策、それから内容の検討等行い、今年度の実施を見送ったようなものです。都市開発費の大きな減のところでいきますと、再開発事業に伴う補助金の関係が大きいと思います。今年度の最終補正の内容につきましては、国庫補助金の配分減に伴う区の補助金の額の減額というのが一番大きな理由になっているものです。","id":"exchange-123"},{"speaker":"本多委員","kind":"質問","question":"理由は本当に今のでわかりましたけれども、この補正予算書で、どうしても補正の予算書で計上するときはこういう表記の仕方になってしまうのかもしれないのですけれども、内訳、事業を実施してみたら減額の結果になったものと、事業が実施できなかったものと、それぞれあると思うのですが、その辺、金額も大きいことですし、もう少しその辺の色分けというか、表記の仕方とか、説明というか。","respondent":"秋山財政課長","answer":"その辺の切り分けというのは非常に難しいものがあるのではないかと思っておりまして、できるだけわかりやすいということで、私の読み上げのときには、なるべく減の理由等をお話しさせていただいたつもりでおりますので。","id":"exchange-124"},{"speaker":"本多委員","kind":"質問","question":"今、表記が難しいという、わかりました。当初計画の何％とか、さらにそういうのがわかりやすくなればと思うのですが、いかがでしょうか。","respondent":"秋山財政課長","answer":"補正予算ですので、まだ、これからほかにも全体の入り繰りというのがありますので、この段階で何％というのは、一つの補正、この時点のパーセントということになってしまいますので、決算であれば何％であるなどということが言えるのですけれども、補正の段階ですと。","id":"exchange-125"},{"speaker":"本多委員","kind":"質問","question":"次にいきます。７７ページのしながわ水族館の諸収入増額に伴い、一般財源の歳出を更正減額というふうに書かれておりまして、この文字から読み込むだけでも、努力をされて成果が出たのかと思うのですけれども、その辺の成果についてお知らせください。","respondent":"多並公園課長","answer":"水族館について答弁します。今の委員からのご指摘がありましたように、この収入のところでは、先ほどもお話しさせていただきましたが、多言語対応等の、これからの国際化に向けた整備ということで進めるために財源を投入したというのがあります。","id":"exchange-126"},{"speaker":"本多委員","kind":"質問・要望","question":"ただ、よく見ていると、目黒川ですから、品川地区、大崎地区、五反田地区と入ってきて、どうも目黒雅叙園のあたりがメーンになっていて、うれしいのだけど、通過点をもうちょっと充実してもらいたいと思うのですが、桜のトンネルをつくっていただきたいと思うのですが、その意気込みというか充実についてお聞かせください。","respondent":"溝口都市開発課長","answer":"そういった中では、しっかり、品川区内の桜全てが桜の名所になるよう地域の方たちとともに取り組んでいきたいと考えているものです。","id":"exchange-127"},{"speaker":"本多委員","kind":"確認","question":"よろしくお願いします。次に、若林委員も取り上げました、大崎歩行者デッキの改修設計についてです。Ｏ歩道橋の打ち切り再計上ということなのですけれども、これは設置されたときの計画で、耐久性とか何十年とか、計画と合致されているのかどうか、その辺だけ確認させてください。","respondent":"溝口都市開発課長","answer":"そういった中で、今回いろいろ改修工事をすることによって、さらにその先１００年もつようにと、一応、平成１００年までライフサイクルコストとしては考えて、今回の補修設計をしていきたいと考えているものです。","id":"exchange-128"},{"speaker":"本多委員","kind":"質問・要望","question":"すみません。関連して、近隣の小関橋のデッキのことを一言お聞きします。いろいろ議会でも取り上げられて、先様と交渉が難航しているのもよく内容は承知しておりますが、朝夕のラッシュに現場を当事者、区の担当者もそうですし、相手様の担当者も、朝夕のラッシュを見たら、もっと何か考えが変わるのではないかと。現場をまず見たかどうか、見ていただきたいので、それだけちょっと教えてください。","respondent":"溝口都市開発課長","answer":"私ども、現地を見させていただいて、都市開発課として、信号の設置、または早期な目黒川デッキの架設に向けた取組みというのは必要だと感じております。これからも早期架設に向けて取り組んでいきたいと考えているものです。","id":"exchange-129"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、６４ページの民生費、児童福祉費にかかわって、３月末、また４月に向けた保育園待機児ゼロの対策について伺いたいと思います。今回、最終補正ですけれども、この最終補正で、４月待機児ゼロに向けた区としての追加対策はあるのか、伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"補正予算ですけれども、今回、子ども・子育て計画では、年度当初４園の新規私立保育園の開設ということでやってまいりましたけれども、今回、待機児童が増えるという平成２７年４月の現状を見まして、区立のひろまち保育園とともに。","id":"exchange-130"},{"speaker":"石田（ち）委員","kind":"質問","question":"努力を進めているということですけれども、この最終補正に対策が、追加でもいいのですけれども、含まれているのかということを伺ったので、そこをもう一度お願いします。それと、１次申請で申込者数が３,３６５人。そのうち入れたのが２,１８０人ということが本会議等でも明らかになっているわけですけれども、入れた２,１８０人の、０から５歳の年齢別の内訳の人数も教えてください。","respondent":"今井待機児童対策担当課長","answer":"補正予算で４園開設したところで２園という形でプラスになりましたけれども、それぞれ当初、大体１億円ほどの補助を見込んでおりましたけれども、国の補助基準額が上がりましたことから、大体１園１億５,０００万円ぐらいの補助という形で。","id":"exchange-131"},{"speaker":"石田（ち）委員","kind":"質問","question":"一方で、入れなかった、不承諾通知を受けた人は１,１８５人です。この不承諾通知を受けた１,１８５人中、０から２歳児は１,０３６人と、１,０００人以上が入れない、全然足りない状況ということですけれども、４月待機児ゼロに向けて何が足りなかったのか伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"私ども、今、委員にご指摘いただきましたとおり、今回、０から２歳が乳児ということで、３７６人分の開設を予定しておりますので、昨年から比較しても待機児童数は減るものということで見込んでおります。","id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は、不承諾通知を受けた１,１８５人中、０から２歳児、１,０３６人が、もう１次で入れない。不承諾通知を受けている。こういった状況を、何が足りなかったのかということを伺ったのです。２次の新規の申請数がわかればちょっと伺いたいのですが、お願いします。","respondent":"今井待機児童対策担当課長","answer":"２次の申請につきましては、新しく対象になる方も含めまして、昨日までの申込みでございましたけれども、大変恐縮ですけれども、まだ最終的な申込みの集計はしておりません。","id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"質問","question":"１次で入れなかったママたちからは、もう目の前が真っ暗になったと、どうしたらいいのかと必死に訴える姿に私も胸が痛みました。この最終補正に、３月末はもちろんですけれども、４月以降の待機児ゼロに向けた計画予算は入っているのか伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"補正予算につきましては、国や都の補助金のこともありますので、こちらは現在、４月１日に開設する予定の施設につきまして計上しているものです。今後の開設につきましては、平成２８年度当初予算に、年度途中の開設についても計上させていただいているところです。","id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問","question":"４月にゼロはもとから考えていないということなのでしょうか。伺いたいと思います。そして、１,０００人を超える不承諾通知が２年連続なわけです。それがまた今年も続くのかと、お母さんたちはもう昨年から不安でいっぱいだったと思うのですけれども、１,０００人を超える子どもが入れないというのはいつからわかっていたのか、予測ができていたのか、ここを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"私ども、申込者数の増を確認いたしまして、改めて４月の開設に向けて取り組んだ結果が、今回の補正予算で７億円を超える開設経費の増という形の補正予算を積極的に組ませていただいているところです。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問","question":"待機児予測。昨年の１０月の決算特別委員会でも、今年の待機児は減るというふうに答弁されていたわけです。申請状況を見通して、待機児予測もあるのに、なぜ３月末までに追加対策が打てないのか、１次申請でこれだけあふれるのか、こういった事態がちょっと理解できないです。そして、この最終補正で対策予算をつけるべきだと思いますけれども、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"こちらのほう、待機児童対策という形で、認可保育園、そして認証保育所、小規模保育を含めた地域型ということで開設はしております。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問","question":"さまざまな調整が必要だとお聞きしています。どのような調整が出てきているのでしょうか。それから、９月補正と３月補正の性格の違い等も含めてお尋ねします。この金額が４,７８４万円なのですが、これは受託収入というのは、人件費のほうにも充当されているのでしょうか。ここ５年間の計画というのは、１年間はお示しいただいたのですが、５年間の計画というのはどういう形で出てくるのでしょうか。","respondent":"秋山財政課長、和田河川下水道課長、寺嶋木密整備推進課長、溝口都市開発課長","answer":"補正予算の基本的な考え方ですけれど、これは最初にご説明させていただきましたけれども。これについては、東京都から減額を申し出されたわけではなくて、この事業、工事につきまして。私は、３８ページの社会資本整備総合交付金の減額についてご説明いたします。私からは３８ページの、充当事業でいきますと目黒駅前地区と、あとその下の武蔵小山駅周辺地区、再開発事業に関する減額についてですが。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"受託事業のほうは、国庫補助、先ほどの社会資本のほうもそうですが、都や国の補助を返還することがないと先ほどありましたけれども、ぜひ計画的に事業進捗を図っていただきたいと。そういうことで、うまくいかなかった場合は、先ほどちょっと大きな障害物がありましたけれども、次年度に向けて円滑に進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は６７ページの一番下のところの不妊治療助成事業追加分。それから７９ページの、今も出ましたけれど不燃化１０年プロジェクトの用地取得費の２点をお伺いします。それともそこはそうでもないのだけれども、いわゆる不妊の方が増えているのかとか、その辺の何か分析がわかれば教えてください。","respondent":"寺嶋木密整備推進課長、川島健康課長","answer":"そういった場合について、もちろん出たら全てというわけではないのですけれども、そういったことに対応できるように予算を計上しているというものでありまして、これは数年計上はしているのですけれども。当初予算ですと８４５件のものが９４５件に１００件増ということで増えております。この数が年々増えている要因なのですが、やはり委員がおっしゃったとおり晩婚化が大きな要因ではないかと私ども分析しております。","id":"exchange-139"},{"speaker":"たけうち委員","kind":"質問・要望","question":"最初の不燃化のほう、そうすると、ちょっといま一つ、もう一回ご説明いただきたいのと、それから明日以降の予算のほうになってしまうのですが、新年度は今度、見たら１,５２０万円の計上になっていて、今年度と比べると、１０分の１までいかないのですけれど、かなり大幅な減の計上になっているのですけれども、そうすると目的を達成できるのかということが心配なのと、また一方で国と都の補助金が随分。","respondent":"寺嶋木密整備推進課長、川島健康課長","answer":"若干、繰り返しになりますが、不燃化１０年プロジェクトのほうは、若干小規模な土地を購入して、単独では広場にならないものも。今の晩婚化についてもう少し踏み込んだ説明ですが、女性の方の妊娠に至る確率というのが、だんだん年が上になるほど下がってくるということが科学的にも言われているところです。","id":"exchange-140"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ちょっと時間があったので、５９ページの文化スポーツ振興基金の積立金で、何度も今日、出てきましたけれども、これについては代表質問でちょっと触れさせていただいて、来年度の事業についてはいろいろペーパーで出ているので大体決まっていると思うのですけれども、今後の文化財の活用に向けて、安藤部長から答弁をいただいたときに、基金も一つの視野に入れてと。","respondent":"秋山財政課長","answer":"文化的なものについても、今後基金のほうは使っていきたいというふうなことは申し上げてありますので、今回文化ということで区民芸術祭を平成２８年度は予定していますけれども、視野に入れてというのは、例えば２０２０年以降。","id":"exchange-141"},{"speaker":"たけうち委員","kind":"質問","question":"今、２０年以降とおっしゃったので、随分先だと思ったのですが、私の思いとしては、オリンピック・パラリンピックに向けて、当然、外国人が増えてくるわけです。そこで活用しない手はないだろうという意味合いがあったので、その視野が随分先だと思ったので、もうちょっと前倒しして検討しないといけないのではないかと思うのだけど、どうですか。","respondent":"秋山財政課長","answer":"当然、先ほども何度もお話ししますけれども、文化プログラム等も入ってありますので、その辺も含めて文化にも基金は活用していきたいと考えているものです。","id":"exchange-142"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２０２０年以降と言わずに、ぜひその前に検討していただきたいと思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"伊藤委員","kind":"質問","question":"それで、自民党・子ども未来の高橋委員も指摘させていただきました。それで、お伺いしたいのが、そういう導入計画と、それから大きなシステムを動かして問題が出てきたときの対処。それから将来的な、安定した制度の運営のための計画といったらいいのか、そういう総合的なものをつくってどこかでしっかり議会に示していかないと非常に不安だと思うのですが、いかがでしょうか。","respondent":"仁平情報推進課長","answer":"大きなシステムですので、次にどういう制度変更が入ってくるかちょっとわかりませんけれども、それはそれで、そういうタイミングでまたシステムのほうを見直して必要な改修を慎重に行っていこうと考えているところです。","id":"exchange-144"},{"speaker":"伊藤委員","kind":"質問","question":"それはもうそのとおりなのですけれど、私たちが思うのは、そういうものを、何というか、全庁的にやっていく責任があるのではないでしょうかということをお伺いしているのです。だって、全ての区民であり全ての国民に関する内容をこれから展開していくわけでしょう。","respondent":"仁平情報推進課長","answer":"その他の事務レベルにつきましては関係所管課長の連絡会。こういう中でもって体制を組んで取り組んでいるところです。今後とも、この制度を推進していくにあたりまして、いろいろ調整が必要になってまいりますので、引き続き努めていきたいと考えているところです。","id":"exchange-145"},{"speaker":"伊藤委員","kind":"質問","question":"よく言うＰＤＣＡシステムという品川区はよく使っていますが、だから、今のところはＰｌａｎであって、Ｄｏでいいと思うのだけれども、実際にこれが走ってみたら、いろんな問題が出てくる可能性があるわけではないですか。それから児童１人当たりの平均の運営経費月額が１５万７,２００円。改めてお伺いしたいのが、こういう事業展開をした結果、品川区の保育園定数が何人拡大したのかということが１点。","respondent":"今井待機児童対策担当課長","answer":"保育園の開設につきましては、待機児童対策ということで進めておりまして、毎年、５億円から１０億円程度の開設経費を私立保育園だけで積んでいるところです。","id":"exchange-146"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほどの数字にあるように、保育園の全体コストは１２４億円。その費用の観点から見れば、利用料金の引き上げについてはある程度理解はできるのです。ですから、こういう情報は本来、サービス事業者にまず提供されるべきであり、常日頃から品川区の行政サービスのコストを利用者の方々に提供して理解を求めていけば、料金改定時、ある一定の理解を得られやすいのではないかと思いますが、いかがでしょう。","respondent":"今井待機児童対策担当課長","answer":"今後も開設に伴う待機児童の対策の経費だけではなく、運営の経費も含めて区民の方にご理解をいただきながら進めていきたいと考えています。","id":"exchange-147"},{"speaker":"伊藤委員","kind":"質問","question":"やはりいろんな観点で、利用者の方々に対してＰＲしていかないと、こういうことについて、まださまざまな疑心暗鬼な可能性があると思うので、これはもっと言うと品川区全体のサービスにかかることですから答弁を改めてお願いいたします。","respondent":"柏原企画調整課長","answer":"今後、さまざまな事業展開、事務事業評価等もそうですし、諸々見直しをしていかなければいけない視点というのはあります。そういった中で、事業のコストの見える化といったところもあわせて検討できればと思ってあります。","id":"exchange-148"},{"speaker":"伊藤委員","kind":"質問・要望","question":"全ての品川区の事業を出せということだと大変なことになるから、利用料金をいただいているものがあるではないですか。そういうことから考えると、こういうさまざまな民営化することを展開するときには、ぜひ民営化のメリット、成果、区政に対する評価、将来にわたる節税効果等々、理論的・客観的に見える資料を対処していって、多くの区民の方々に理解を求めるべきと考えますがいかがでしょうか。","respondent":"竹田保育課長","answer":"民営化は今後、大きな保育行政の課題だと考えております。民営化を着実に進めるにあたっては、利用者の方あるいは近隣の方、多くの区民の方のご理解が必要だと考えておりますので、皆様に丁寧に対応していきたいと考えております。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"私は、３６ページ、地方創生加速化交付金と、５９ページ、文化スポーツ振興基金についてお聞きしたいと思います。これは財政課にお聞きしたいと思います。これも税金であります。この交付金は、この２つの事業に使っていいのですか、まずお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"この交付金は、国のほうから説明があった際に、今、委員がご指摘があった部分とあわせて、交付の条件ということで、地方自治体が計画をしているものの中で、例えば今、策定しています総合戦略といった中に含まれているもの、それから、今、仕事創生というのもありましたけれども。","id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"そもそも地方創生という言葉。これは一般の区民、国民が聞いてもそうですが、いろいろ、これもあれも使えるという、つけるのはいいのですが、今、品川区に実際当てはまるのでしょうか、地方と比較して、マンション等の高層集合住宅は増えています。こういう状況を見て、この補助金を使うことに区民の理解というのは得られるのでしょうか、もう一度言います。ちょっともう一回、ご見解をお聞かせください。","respondent":"柏原企画調整課長","answer":"これはまさに地方と都市が連携しながら共存・共栄といいますか、それを支えながらやっていこうです。趣旨といたしましては、全然間違ったものというところではないと理解しています。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"見解の違いはありますが、地方創生ですから、この東京都内、２３区で、地方を我々も視察に行っています。全然、状況は違います。それは当たり前です。その税金が品川区で使っていいのかどうかというのは私はやはりちょっと疑問だと感じます。次に、同じく財政課にお聞きします。区の方針は変更したのですか、そして、もし変更したならその理由も教えてください。","respondent":"秋山財政課長","answer":"したがいまして、一般財源として使えるものに財調基金があるわけですけれども、それに積み立てて、リーマンショックみたいなものについてもきちんと対応するようにするということは、やはりその状況を柔軟に判断して主体的に決めていくという姿勢の現われだと考えています。","id":"exchange-152"},{"speaker":"須貝委員","kind":"意見","question":"２つとも、実際のところ、予算が残ったから、急に基金を積み上げたように見えます。」と。実際、品川区というのはどれだけしっかりして財源として、また毎年の黒字か赤字かで運営していて収支がどうなのか、今、基金に入れてしまったら見えにくい。そして、基金に入れなければ、一般財源ならば、自由にそれを使えるし、どんな事業にも使えると思うのですが、それについてご見解をお聞かせください。","respondent":"秋山財政課長","answer":"繰越金が増減すれば繰越金が増えていることがわかりますし、同じように、財調基金が増減していれば、その分、一般財源として入っているということですので、その辺は、わかりやすいということであれば、基金としてきちんと積立てをして。","id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、ほかの方にご答弁がありましたが、例えば文化スポーツ振興基金、毎年５億円ずつ出していくということの話がありました。一般財源として毎年予算化すればいいわけではないですか。そうですよね、もう、あらかじめ毎年、５億円ずつ、５年たてば２５億円。そうしたら、何で必要あるのですか、教えてください。","respondent":"秋山財政課長","answer":"それは基金としての存在理由として、この事業を品川区としては計画的にやっていきますと言うために３０億円積み増したという宣言です。一つの政策を実行する上での宣言としての、姿勢としての基金とお考えいただければよいかと考えています。","id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"それぞれやむを得ない事情があるのもわかりますが、何か多過ぎませんかと思うのです。これは本会議で議員が、皆様が議決した予算に対して金額がこれだけ大きく変更したということに対しては、どのようなお考えをお持ちでしょうか。そして、議会は今後とも、１０％以上かわかりませんが、予算に対して相当の変動があるということを我々は想定していなければいけないのでしょうか、お考えをお聞かせください。","respondent":"秋山財政課長","answer":"決してそういうことではなくて、執行の段階でも予算の段階でも工夫はしていますし、執行の段階でも工夫して、なるべく最小の経費で最大の効果を出すということでやっている結果としてこうなっているとお考えいただければと思います。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"これは会社ではないので、使い切ればいいという話ではなくて、皆様それぞれ各所管の事業が、自分たちで予算を立てて、そして積算して議会に出して、本会議で予算を皆様が議決しているわけではないですか。会社はわかります、無駄なものをどうのこうの。アクシデントはあると思いますが、それを今申し上げているのですが、課長、いかがですか。","respondent":"秋山財政課長","answer":"結果としてこうなっているということが一つお話ししていきたいということと、あとは決算のときまでに、最終補正の段階ではこういう形になります、決算のときまでにどのぐらいが出てくるのかというのは、今後の内容を見ていかないとわからないと考えています。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"先ほどもほかの委員が言っていました。これだけ残ったのですか。いや、それぞれの所管がそれぞれ一生懸命やっているではないですか。だって、そこにあまり離れて予算と補正がこれだけ出てしまうということは、私は財政課でも考えないといけないのではないかと、だって、間、間に毎月、どれだけ執行しているというのを見ているわけではないですか、それだけちょっと言いたいということで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"あべ委員","kind":"確認","question":"個人番号カードなのですが、いろいろありました中で、大体、様子も見えてきたのですけれども、今まだ配布が終わっていないものが、まだ２万件ぐらいですか、あるということで、これはいつごろ渡し終えるのか、あるいはまた年度末、３月末までにどの程度渡し切って、あと残るのか、その見通しを教えてください。課長、コースターの持ち帰り率というのはどのぐらいなのでしょうか。","respondent":"井浦戸籍住民課長、竹田保育課長、中元広報広聴課長","answer":"国からの課されている義務として、３月３１日までは通知カードを保管するようにということで達しがありますが、品川区としましては。全体としては減っているものではないと考えております。コースターの持ち帰り率ですが、正確な数字はつかんでおりませんが、大まかなところで私が出ました広報者の会合などですと、きちんと説明を差し上げて。","id":"exchange-158"},{"speaker":"あべ委員","kind":"質問・要望","question":"個人番号カードなのですけれども、３月末でも通知カード１万通がまだお渡しできない状況にあるということで、再郵送についてお答えがなかったので再答弁をお願いしたいと思います。私が出席した会は必ずしもそういう丁寧な説明がなかった会も多かったものですから、非常に残っている率が多いものを何度か見させていただきました。あわせて答弁をお願いします。","respondent":"井浦戸籍住民課長、竹田保育課長、中元広報広聴課長、柏原企画調整課長","answer":"現在、２月の平均で１日２０６件のお客様が見えておりますので、５月には計算上は完了する計算ですが、６月以降も粘り強く呼びかけをしながら。ちなみに、歳出面から言いますと、６４ページの児童福祉費は補正額が４億５,０００万円余の増額補正をしておりますし。コースターの件ですけれども、今年度、本当にシティプロモーションを積極的に外へＰＲし出したツールとして、まずはこれで広げていこうと。それはここに限定してということではなくて、さまざまなチャネルを使いながら、タイミング、そのときによって。","id":"exchange-159"},{"speaker":"あべ委員","kind":"質問・要望","question":"オリンピック・パラリンピックというキーワードで言えば、桟橋でも電柱でもいいのですけれども、ある程度のお金が今後５年間まとめて用意しておいて、それをアピールもしていくという考え方もわかるのですけれども、やはりオリンピックの後始末と言うとあれですが、一通り終息した後、３０億円規模で文化スポーツ振興基金という形でずっと維持していくのか、これだけの金額が必要なのかということと。","respondent":"秋山財政課長","answer":"今回はオリンピック・パラリンピック２０２０年が契機ということで、いかにそれを盛り上げていくかというような視点も契機に文化スポーツ振興基金をつくったですので、今後の使い道については、もちろんそういうベースはありますけれども。","id":"exchange-160"},{"speaker":"あべ委員","kind":"質問・要望","question":"５年後の予算の話ですから今ではないかもしれませんけれど、基金創設のこのタイミングであえて言わせていただければ、オリンピックが終わった後でその文化スポーツというのであれば、やはりそのイメージの、文化スポーツと一般的に言われている中での事業展開にしていただきたいと思いますし、今、文化スポーツの振興費というのは、品川区はちょっとオリンピック関連で膨らんでもせいぜい年間で７億円。","respondent":"秋山財政課長","answer":"使い道については、その時々、その時々、検討してまいりたいと思っていますし、そういう形で文化にももちろん使っていきたいと考えております。","id":"exchange-161"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、１０２ページからの国保と、それから６３ページの入院中の紙おむつ代の助成事業について伺いたいと思います。全国知事会では、限界に近づいている被保険者の負担軽減のために国費を追加すべきだと提言も出しました。改めて、国、東京都、品川区、それぞれ幾ら入っているのか、そして予算書のどこに入っているのかを伺いたいと思います。これを品川区が何に使ったのかもお聞かせいただきたいと思います。","respondent":"高森国保医療年金課長","answer":"委員からのご質問、公費１,７００億円のお話ですが、国保につきましては、３６ページの１項１目民生費負担金の中の国民健康保険負担金というのが、保険者支援金分として来ているものです。","id":"exchange-162"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"当初予算で見込んだ数が１万８００人に対して、決算での見込みの人数が１９９人ということで、桁が２桁ぐらい違うわけですけれども、これは１万８００人が入院している人の数だということで、要介護３以上の人の人数ということで出したということなのですが、今回の制度は所得制限がつけられていて、住民税非課税世帯ということになっていますが、この１万８００人というのは。","respondent":"永尾高齢者福祉課長","answer":"ですので、その方がそのまま１カ月入院しているかどうかとか、所得がどうかとか、そういうところまでの把握はできておりません。やはり次年度以降については、実際のご要望だとか、そういうものを判断した上で、内容等についても検討していきたいと考えているところです。","id":"exchange-163"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど、要介護３以上の方というふうなところは外されるという方向で検討しているということですので、それはぜひともやっていただきたいということで強く要望します。品川区の５,０００円よりも少ない額というのは２３区の中で３区しかありません。そういうところからすると、これはせめて２２区の平均並みに引き上げていただきたいと思うのですが、この３点、お聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、あと金額の５,０００円についてのお話ですけれども、まず今の状況ですと、利用してくださる方の人数がまだ少ないというところで、今はその人数をいかに増やしていくかというところに注視していきたいと考えているところです。","id":"exchange-164"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要介護３というのは取り除くということなので、それは対象が広がることになると思うのですけれど、やはりすごくこれができるということで楽しみにしていたのに、非課税世帯ですから、１人でも課税者がいると、これが受けられないということになってしまうわけです。そういうことから考えたら、ぜひ所得制限をなくすということでもご検討いただきたいと思いますが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"金額についてもさまざまな金額になっており、条件につきましても、要支援１以上の設定だったり、要介護３以上の設定だったり、各区まちまちです。その条件の中で各区を比較するというのは、なかなか難しいところかと感じているところです。","id":"exchange-165"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ所得制限をなくす方向も検討していただきたいと思います。基金のため込み金が平成２７年度当初見込みより１３０億円も増えて、過去最高の８４５億円にもなったにもかかわらず、区民の切実な願いに応えた使い方になっていないということが１点。それから消費税増税分が２５億円プラス８億円、３３億円も増えたのに、これも区民のために使われていない。高過ぎる保険料引き下げにこそ使うべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-166"},{"speaker":"浅野委員","kind":"質問","question":"私からは、６９ページの温暖化対策事業の財源更正についてということで、これに関しての国の考え方とか、国の現在の方針、何を考えておるのかということについて聞きたいと思います。８１ページの学校環境整備更正減額、非構造部材の耐震化工事について。時間があれば、１１９ページの特定健康診査事業費更正減額について伺います。これに関しての区の見解ですか、そこも含めてご答弁をお願いします。","respondent":"三ツ橋環境課長","answer":"区の考え方ですけれども、今、委員がおっしゃいましたように、２０５０年に向けてマイナス８０％という大きなものを掲げております。区も、東京都の動向や、また国の動向を踏まえながら、環境計画などを推進していきたいと考えています。","id":"exchange-167"},{"speaker":"浅野委員","kind":"質問","question":"それと、次ですけれども、学校環境整備事業更正減額ですけれども、非構造部材耐震化につきまして質問しますが、５億円の更正減額ということで、かなりの減額になっております。これは耐震工事等が完了したというようなことも含まれているかと思いますけれども、この５億円も更正減額になったということについての内容について教えてください。","respondent":"品川庶務課長","answer":"あとは工事を進めていくにあたりまして、例えば足場の設置とか、それからあと、今回、非構造部材は体育館がメーンになるのですけれども、体育館の照明など大分変えております。","id":"exchange-168"},{"speaker":"浅野委員","kind":"質問","question":"この非構造部材の耐震については、行政のほうも本当に力を入れていただいて、３・１１以降、最初にほかの区を、何というのでしょうか、先導するような形で、最初に非構造部材の耐震対策を行っていただき、建設基準法の対応も２回も行っていただいたということで、そういう重なった工事になったかもしれませんけれども、品川区教育委員会が子どもたちの安全を最優先したということに対しては。","respondent":"品川庶務課長","answer":"非構造部材の工事に伴いまして、体育館のＬＥＤ化なのですけれども、やはり全部ではなくて、一部できていない学校もありますが、概ね照明はＬＥＤ化しているという状況です。","id":"exchange-169"},{"speaker":"浅野委員","kind":"質問・要望","question":"時間がたつと、こういうものも、地震が発生したときに落下するとか、そういうような危険性も出てくるものでありますので、これはやはり学校のほうで、しっかりと定期的に、何というのでしょうか、その意識を持って、落下する危険性があるのか、ないのかということを、ぜひとも教育委員会のほうから各学校に通知をするなり、たまにやっているかどうかという確認もとっていただければ。","respondent":"高森国保医療年金課長","answer":"特定保健指導の更正減額についてお答えします。対象者は３０％で当初予算は見込んでおったのですけれども、実績見合いということで、対象者は２０％というふうに下げました関係で、減額補正ということになっております。","id":"exchange-170"},{"speaker":"浅野委員","kind":"質問","question":"平成２７年度の目標は、受診率が５５％、そして将来的には平成２９年、国の参酌標準値６０％。これは保健指導もその６０％になるかと思います。そして、当初の目標パーセントというのでしょうか、最終の見込みというものはどのような数字になるか、落ち着くのかということを教えていただければと思います。どのように力を入れていくのかということで、今後の考え方を教えてください。","respondent":"高森国保医療年金課長","answer":"そういう方に対して、一つの文書でもって勧奨通知をご案内さしあげていたのですけれども、そういうところももう一歩踏み込んだ形で、それぞれの被保険者、隔年で実施される方もいらっしゃれば、全く受けていない方もいらっしゃいますので、そういうふうなところから、手厚く。","id":"exchange-171"},{"speaker":"沢田委員","kind":"質問","question":"６５ページの子どもすこやか医療費助成と、５５ページ、奨学金貸付事業、それから６７ページの不妊治療助成と、時間があったら、６６ページと６３ページの生活困窮者自立支援についてお伺いしようと思っています。昨年から比較しても、年々、子どもすこやか医療費が大変増加してきていまして、どのように分析されているのか、また予算の組み立て方をどう考えられているのかお聞かせください。","respondent":"廣田子ども家庭支援課長","answer":"２月末現在で執行率が今、９５％ほどになっておりまして、３月分の支払いの実績、平成２６年度の実績どおりでも５,０００万円ほど足らなくなってしまうという見込みですので、伸び率を考えて７,８００万円という補正を上げさせていただいたところです。","id":"exchange-172"},{"speaker":"沢田委員","kind":"質問・要望","question":"奨学金貸付事業の更正減額についてですけれども、ちょっと出ていたかもしれないですけれど、５９６万円の減額ということで、補正の歳出予算見積書にもあるのですけれども、入学準備金が予算では公立１０人、私立１２人ということでしたけれども、結果として０人、０人ということで、今、本当に、子どもの貧困とか格差ということがいろいろと言われていますけれども、この奨学金に関して。","respondent":"廣田子ども家庭支援課長","answer":"平成２８年度の奨学支援に関しましては、申込みが出ずということで、こういう結果になってあります。","id":"exchange-173"},{"speaker":"沢田委員","kind":"意見","question":"そういったニーズが減ってきているということもあるのかもしれないですけれど、こういった制度があるので、もしかしたら知らない方もいらっしゃる場合もあるかもしれないですし、今おっしゃったとおり、ほかの制度と比較して、条件があまり品川区の制度がよくないということもあるのかもしれないですけれども、利用しない制度がこういう形であるということは、ちょっと問題だと思いますので。","respondent":"廣田子ども家庭支援課長","answer":"他区で、世田谷区でありますとか足立区でありますとか、給付型をやっているところもございまして、情報をリサーチしています。今後の方針につきましては、他区の状況等を見ながら研究させていただきたいと思っているところです。","id":"exchange-174"},{"speaker":"沢田委員","kind":"質問・要望","question":"しっかりと活用していただける。それで、次に不妊治療費の助成なのですけれども、先ほど、また代表質問でもたけうち委員からもありましたし、我が会派でも以前からこれについては質問をさせていただいていますので、ちょっと何度も繰り返しになる部分はあるかもしれないですけれども、改めて確認させていただきたいと思います。どれぐらい妊娠したのか。","respondent":"川島健康課長","answer":"ただ、特定不妊の助成の件数というのは、東京都でも公表はしていないのですが、大体の数ということでいきますと、東京都全体で大体１万７,０００件から１万８,０００件前後、１年間に助成しているところで。","id":"exchange-175"},{"speaker":"沢田委員","kind":"質問・要望","question":"障害者や母子家庭とか、そういったところの部分ではしようがないと思いますけれども、そういった世帯を除いたその他の世帯という世帯が平成２６年で８２８世帯ということでありますけれども、これについて、それぞれしっかりとした、どのような理由であるとか、対応をどうされているのかとか、そのあたりのところをしっかりとお聞かせいただきたいと思います。","respondent":"伊東生活福祉課長","answer":"生活保護に関してですけれども、委員ご指摘のとおり、平成２１年以降、大分、増加傾向が続いて、最近はちょっと安定というか高止まりという状況で、微増傾向というような状況です。","id":"exchange-176"},{"speaker":"沢田委員","kind":"質問・要望","question":"高齢者世帯が増えているのはわかっていまして、その他の世帯の推移ですね。特に長年、生活保護を受けている、その他の世帯というものの数、ずっとこういうことを受けていらっしゃる、そういうものの調査をしっかりとしていただきたいと思うのですけれども、自立支援をしっかり強化して、不正受給への取り締まりを強化していかなくてはいけないと思うので、その辺のところを改めて確認させてください。","respondent":"伊東生活福祉課長","answer":"先ほど不正受給に関しての話がございましたけれども、それにつきましても、調査員等々を活用して、さまざまチェックしまして対応しています。","id":"exchange-177"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/257095?Template=document&Id=1036#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":136656,"voices":427}}]);
